COLLDATA("asabahur","ur",[[2573,"§۲۵۸۰ ۔ الربیع بن زید(1)\nبقول بعض: “ابن زیاد” ایک قول “ربیعہ” کا ہے۔ بقول بغوی: مجھے معلوم نہیں، آیا یہ صحابی ہیں یا نہیں؟ پھر وہ خود اور الجرانی(2) بطریق داؤد الاودی کی روایت کرتے ہیں کہ انہوں نے ابو کبر حارثی سے بواسطہ طریق بن نوید سنا کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم نے ایک نوجوان کو دیکھا جو راستہ سے ہٹ کر چل رہا تھا۔ آپ نے فرمایا: کیا ہوا ہے راستہ سے ہٹ کر چل رہے ہو؟ اس نے کہا: گرد و غبار سے پریشان ہوتا ہوں، آپ علیہ السلام نے فرمایا: “اس راستہ سے ہٹ کر نہ چلو! اللہ کی قسم جس کے ہاتھ میں میری جان ہے، یہ تو جنت کی خوشبو ہے”۔ اسی روایت کو ابو داؤد نے مراسیل میں اور نسائی نے الکنیٰ میں نقل کیا ہے لیکن انہوں نے “ربیع بن زیاد” لکھا ہے، ابن مندہ نے ذکر کیا تو ربیعہ بن زیاد یا ابن زیاد لکھا ہے۔ بیار شاد ایک غزوہ کے موقعہ پر آپ صلی اللہ علیہ وسلم نے فرمایا تھا۔ (عارف نمدی)","",{"fn":"(1) اسد الغابہ (۱۶۲۶) تجرید (۱۷۷/۱)\n(2) المعجم الکبیر (۴۶۰۸/۵) معجم الزوائد (۲۸۷/۵)"}],[2574,"§۲۵۸۱ ۔ الربیع بن سہل(1)\nبن حارث بن عمروہ بن عبد رزاح بن ظفر انصاری ظفری۔ بقول ابو عمر:(2) احد میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۶۲۷) استیعاب (۷۵۴)\n(2) استیعاب (۶۸/۲)"}],[2575,"§۲۵۸۲ ۔ الربیع بن طعیمہ\nبن عدی بن نوفل بن عبد مناف القرشی المونلی۔ جبیر بن مطعم بن عدی کے چچا زاد بھائی۔ ابو طعیمہ بن عدی تو بدر کے روز کافر مارا گیا تھا۔ ان کی والدہ حبیبہ بنت ابی العاص سیدنا مروان بن الحکم رضی اللہ عنہ کی پھوپھی تھیں۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[2576,"§۲۵۸۳ ۔ الربیع بن قارب العبسی(1)\nابو علی الغسانی نے اپنے استدراک میں ان کا ذکر کیا ہے کہ ان کی حدیث ان کے بیٹے کی اولاد عبد اللہ بن قاسم بن حاتم بن عقبہ بن عبد الرحمن بن مالک بن عبید بن عبد اللہ الدین الربیع بن قارب سے نقل کی جاتی ہے کہ ربیع نبی صلی اللہ علیہ وسلم کے پاس آئے۔ آپ نے انہیں پہننے کو چادر اور سواری کے لیے اونٹنی دی اور ان کا نام عبد الرحمن رکھا۔","",{"fn":"(1) اسد الغابہ (۱۶۲۸)"}],[2577,"§۲۵۸۴ ۔ الربیع بن مالک\nالربیع بن ربیعہ میں ان کا تذکرہ گزرا ہے۔"],[2578,"§۲۵۸۵ ۔ الربیع بن معاویہ\nبن فجاج بن عمرو بن عقیل بن الحجاجی، بیعت کی اور اسلام لائے۔ ابن سعد نے بنی عقیل کے وفد میں ان کا ذکر کیا ہے۔ میں نے اپنے شیخ، شیخ الاسلام ابن تیمیہ کے قلم سے تحریر کے ایک نسخہ کے حاشیہ پر اسی طرح لکھا دیکھا ہے پھر میں نے طبقات ابن سعد کی مراجعت کی، مطرف بن عبد اللہ بن الشلم کے حالات میں میں نے ان کی حدیث ذکر کی ہے۔"],[2579,"§۲۵۸۶ ۔ الربیع بن نعمان(1)\nبن یافا، حارث کے بھائی، احد میں شریک ہوئے۔ الاثیر کی نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۳۰)"}],[2580,"§۲۵۸۷ ۔ الربیع الانصاری الزرقی(1)\nبغوی، ابن ابی عاصم اور طبرانی(2) نے بطریق جریر بن عبد الملک بن عمیر سے بحوالہ الربیع الانصاری روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے میرے چچا زاد بھائی کی عیادت کی، ان کے گھر والے رونے لگے۔ سیدنا عمر رضی اللہ عنہ نے ان کو روکا۔ کہا: بس! آپ علیہ السلام نے فرمایا: انہیں رونے دو جب تک میت پڑی ہے یہ روتی رہیں گی، جو بھی میت اٹھے گی یہ چپ ہو جائیں گی۔ جریر نے ایسا ہی کیا۔ اسی روایت کو داؤد اور طائی نے بواسطہ عبد الملک بن عمیر جریر بن حنیک سے نقل کیا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۱۶۲۰) استیعاب (۷۵۱) تجرید (۱۷۶/۱)\n(2) المعجم الکبیر (۴۶۰۷/۵) مجمع الزوائد (۳۰۰/۵)"}],[2581,"§۲۵۸۸ ۔ الربیع الانصاری(1)\nان سے ان کی بیٹی ام سعد روایت کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “بد اخلاقی بے برکتی کا باعث ہے، عورتوں کی ہاں میں ہاں ملانا پشیمانی و ندامت کا ذریعہ ہے اور سلیقہ مندی بدصورتری اور برکت کا سبب ہے”۔ ابن مندہ(2) نے اسے درج کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۳۱)\n(2) ابو داؤد کتاب الادب باب فی حق المملوک (۵۱۶۳، ۵۱۶۲) مسند احمد (۵۰۲/۳)"}],[2582,"§۲۵۸۹ ۔ الربیع الجرمی(1)\nبقول ابن حبان:(2) انہیں شرف صحابیت حاصل ہے۔ طبرانی(3) اور باوردی نے بطریق مسلم بن عبد الرحمن، سوادہ بن الربیع سے روایت کی ہے کہ “میں اور میرے والد نبی صلی اللہ علیہ وسلم کے پاس گئے۔ آپ نے چند اونٹوں کا حکم دیا...”۔ (حدیث) ابو نعیم لکھتے ہیں: یہ روایت ایک جماعت نے مسلم بن عبد الرحمن سے نقل کی ہے “اپنے والد کے” الفاظ ماسوائے سلمہ بن رجاء کے جو انہوں نے اس روایت میں نقل کیے ہیں، کسی اور نے نہیں کیے۔ بغوی کے ہاں دوسری سند سے مروی ہے کہ میں اپنی والدہ کو لایا، آپ نے ان سے فرمایا۔ ابتدا یہ بھی لکھا جایا جائے۔","",{"fn":"(1) اسد الغابہ (۱۶۳۲) تجرید (۲۷۷/۱)\n(2) اسد الغابہ (۱۶۳۳/۳)\n(3) المعجم الکبیر (۴۶۰۴/۵)"}],[2583,"§۲۵۹۰ ۔ ربیعہ بن اکثم\nبن ابی الجون خزاعی، ابن اسکن نے ان کا نسب لکھا ہے اور ان کی وہ حدیث نقل کی ہے۔ جو ہم نے ظلایات میں بطریق سعید بن المسیب بحوالہ ربیعہ بن اکثم میں روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم عرضی (چوڑائی میں) مسواک کیا کرتے تھے۔ سعید بن المسیب تک کی اس کی سند ضعیف ہے۔ بقول ابن اسکن ان کی حدیث ثابت نہیں۔"],[2584,"§۲۵۹۱ ۔ ربیعہ بن اکثم(1)\nبن تحمرہ بن عمرو بن لکیر بن عامر بن غنم بن دودان بن اسد بن خزیمہ اسدی، بنی عبد شمس کے حلیف۔ موسیٰ بن عقبہ اور ابن اسحاق(2) وغیرہ نے شرکاء بدر میں اور شہداء خیبر میں ان کا تذکرہ کیا ہے اس وقت یہ تیس سال کے تھے۔ قلعہ وطاۃ میں حارث یہودی نے انہیں شہید کیا تھا۔ معاذ بن ماعص کے سوانح میں ان کا ذکر آتا ہے۔ ان کا قد میانہ سے کم تھا۔ کنیت ابو یزید تھی۔ ابو عمر(3) نے ان کے حالات میں وہی حدیث نقل کی ہے جو میں نے بعد والے صاحب کے حالات میں روایت کی ہے۔ بظاہر ابن اسکن کی ترتیب زیادہ درست ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۳۲) استیعاب (۷۵۶) تجرید (۱۷۸/۱)\n(2) السیرۃ النبویہ (۲۴۲/۲)\n(3) استیعاب (۶۹/۲)"}],[2585,"§۲۵۹۲ ۔ ربیعہ بن ربیعہ بن امیہ بن ابی الصلت الثقفی\nمرز بانی نے ان کا ذکر کیا ہے اور ان کا یہ شعر پڑھا جس میں وہ اپنے والد کی طرف اپنے انتساب کا جواب دیتے ہیں: “ہم چند قیس کا گروہ ہیں۔ ہماری اور ان کی نسبت ایک جیسی ہے”۔ یہ بات بارہا دفعہ گزر چکی ہے کہ ثقیف اور قریش کا کوئی شخص بھی جو مکہ اور طائف میں رہا ہو وہ چچہ الوداع میں مسلمان بن کر شریک نہ ہوا ہو۔ اس سے پہلے امیہ بن ابی الصلت کی وفات تو یقینی بات ہے۔ جو ہجرت کے نویں سال ہوئی۔ اس کی کچھ تفصیل ان کے بھائی قاسم بن امیہ بن ابی الصلت کے سوانح میں بیان ہوگی۔"],[2586,"§۲۵۹۳ ۔ ربیعہ بن ابی براء\nابن عامر بن مالک ہیں، ان کا تذکرہ ہوتا ہے۔"],[2587,"§۲۵۹۴ ۔ ربیعہ بن حارث(1)\nبن عبد المطلب بن ہاشم ابو ارویٰ ہاشمی، زبیر کا قول ہے: یہ آپ علیہ السلام کے چچا عباس سے زیادہ عمر رسیدہ تھے۔ اور یہ اپنی قوم کے ساتھ بدر میں شریک نہیں ہوئے۔ کیونکہ وہ شام میں غائب تھے۔ ان کی والدہ عمرہ بنت قیس القمریہ ہیں۔ صحیح مسلم میں بطریق عبد اللہ بن عبد اللہ بن حارث بن نوفل بن عبد المطلب بن ربیعہ بن حارث بن عبد المطلب اور عباس بن عبد المطلب دونوں اکٹھے ہو کر کہنے لگے: “اگر ہم یہ دونوں لڑکے نبی صلی اللہ علیہ وسلم کی خدمت میں پہنچ جائیں اور آپ انہیں زکوٰۃ کی وصولیابی پر مقرر کر دیں”۔(2) یہی حدیث ہے۔ دور جاہلیت میں ربیعہ تجارت میں سیدنا عثمان رضی اللہ عنہ کے شریک تھے۔ دار قطنی نے “کتاب الاخوۃ” میں لکھا ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں خیبر سے ہر سال سو دق کھجوریں دینے کا حکم دیا۔ یہی زبیر کا قول ہے سیدنا ربیعہ اپنے بھائیوں نوفل اور سفیان سے پہلے خلافت فاروقی میں فوت ہوئے۔ بقول بعض ۲۳ھ مدینہ میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۶۳۵) استیعاب (۷۵۷)\n(2) ابو داؤد کتاب الدیات (۴۵۴۷) ترمذی کتاب الدیات (۱۳۳۹، ۱۳۳۸) نسائی کتاب القسامہ باب ذکر الدیۃ من الورق (۴۸۱۷)"}],[2588,"§۲۵۹۵ ۔ ربیعہ بن حارث\nبن نوفل۔ بغوی نے ان کا صحابہ میں ذکر کیا ہے کہ مدینہ ہاشمی رکھتے تھے، محمد بن اسماعیل کی کتاب میں میں نے ان کا نام دیکھا ہے لیکن ان کی کوئی حدیث نہیں ملی۔ میں کہتا ہوں: ان کی حدیث حسن بن سفیان نے اپنی مسند میں نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جب تم میں سے کوئی رکوع کرے تو یوں کہے: اللھم لک رکعت و بک آمنت”۔(1) (حدیث) ابو نعیم نے یہ حدیث پہلے والی شخصیت کے حالات میں نقل کی ہے۔ اس کے سیاق میں ہے “ربیعہ بن حارث بن نوفل سے مروی ہے” اگرچہ وہ نوفل بن حارث بن عبد المطلب ہیں تو ان کے والد اور دادا شرف صحابیت سے سرفراز ہیں۔ اور ان کے بھائی عبد اللہ بن حارث کو رویت و دیدار نبوی حاصل ہے۔","",{"fn":"(1) مسلم کتاب صلاۃ المسافرین باب الدعاء فی صلاۃ اللیل و قیامہ (۱۸۰۹) ابو داؤد کتاب الصلاۃ باب ما یستفتح بہ الصلاۃ فی الدعاء (۷۶۰) ترمذی کتاب الدعوات (۲۴۲۲) نسائی کتاب الافتتاح باب نوع آخر من الدعاء بین التکبیر و القراءۃ (۸۹۵) ابن ماجہ کتاب اقامۃ الصلاۃ والسنۃ فیہا باب رفع الیدین اذا رکع (۸۴۶)"}],[2589,"§۲۵۹۶ ۔ ربیعہ بن خراش الصباحی(1)\nرشاطی نے بحوالہ ابن الکلبی مدانی نقل کیا ہے کہ قبیلہ کے سردار الحج کے ساتھ وفد میں شامل تھے۔ فرماتے ہیں: ابن فحون اور ابو عمر نے ان کا ذکر نہیں کیا ہے۔","",{"fn":"(1) تجرید (۱۷۹/۱)"}],[2590,"§۲۵۹۷ ۔ ربیعہ بن ابی خرشہ(1)\nبن عمرو بن ربیعہ بن حبیب بن جذیمہ بن مالک بن حصل بن عامر بن لوی القرشی العامری۔ ابو عمر(2) نے ان کا ذکر کیا ہے کہ فتح مکہ کے موقعہ پر اسلام لائے اور جنگ یمامہ میں شہادت پائی۔","",{"fn":"(1) اسد الغابہ (۱۶۳۷) استیعاب (۷۵۵) تجرید (۱۷۹/۱)\n(2) استیعاب (۶۸/۲)"}],[2591,"§۲۵۹۸ ۔ ربیعہ بن خویلد(1)\nبن سلمہ بن ہلال بن عامر بن عائد بن کعب بن عمرو بن لوی بن غالب ابن فہر الانصاری ابن شاہین نے بطریق ابن کلبی ان کا ذکر کیا ہے کہ وہ صاحب شرف افت انسان تھے۔ ابن فحون اور ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۳۸)"}],[2592,"§۲۵۹۹ ۔ ربیعہ بن دراج\nبن عنبس بن وہبان بن وہب بن حذافہ بن جمح قرشی جمحی۔ مغازی میں واقدی کا بیان ہے کہ جنگ بدر میں یہ کافر قید ہوئے پھر آزاد کر دیئے گئے۔ مشہور تابعی عبد اللہ بن محیر یز کے چچا ہیں۔ ربیعہ سیدنا عمر رضی اللہ عنہ کی خلافت تک زندہ رہے۔ جس سے ظاہر ہوتا ہے کہ یہ فتح مکہ کے مسلمانوں میں سے ہیں۔ اس واسطے کہ حجۃ الوداع کے موقعہ پر کوئی قریشی بھی غیر مسلم نہ تھا۔ ابو زرعہ دمشقی اور ابن سمیع نے تابعین کے پہلے طبقہ میں انہیں ذکر کیا ہے۔ ابن جوصاء کی عبد اللہ بن محیر یز سے بحوالہ ان کے چچا ایک روایت میں ہے: میں نے سیدنا عمر رضی اللہ عنہ کے پیچھے نماز پڑھی، آپ نے عصر کی نماز دو رکعت پڑھائی، دیکھا کہ علی رضی اللہ عنہ عصر کے بعد (نفل) نماز پڑھ رہے ہیں ان پر ناراض ہوئے۔ (حدیث) ابن جوصاء کہتے ہیں: ابو زرعہ دمشقی نے فرمایا: ابن محیر یز کے چچا کا نام ربیعہ بن دراج تھا۔ ابو زرعہ کہتے ہیں: ہمیں ابو صالح نے بواسطہ لیث، یزید بن ابی حبیب کے حوالہ سے بیان کیا کہ ابن شہاب نے انہیں لکھا کہ ابن محیر یز نے (اپنے چچا) ربیعہ بن دراج کے حوالہ سے یہ روایت بیان کی ہے، امام احمد رضی اللہ عنہ نے بحوالہ زہری ربیعہ بن دراج ہی نقل کیا ہے اور ابن المبارک بواسطہ، محمد بن حوالہ زہری ربیعہ سے روایت کرتے ہیں اس میں یہ نہیں کہا: “کہ مجھ سے بیان کیا” یہی درست ہے اس واسطے کہ درمیان میں ابن محیر یز واسطہ ہیں۔ امام بخاری(1) نے اپنی تاریخ میں بطریق عقیل، زہری سے بحوالہ حرام بن ربیعہ روایت کی سیدنا علی رضی اللہ عنہ، اور بطریق یونس زہری سے نقل کیا ہے کہ مجھ سے دراج نے بیان کیا کہ سیدنا علی رضی اللہ عنہ اور بطریق زہری زہری سے مروی ہے کہ انہوں نے ابن محیر یز سے سنا کہ سیدنا عمر رضی اللہ عنہ نے ہمیں نماز پڑھائی۔ یہ سارا اختلاف زہری سے آگے ان کے شاگردوں میں ہوا، سب سے راجح اور زروانی روایت ابو صالح والی ہے جو حلیف سے مروی ہے۔ واللہ اعلم۔ زبیر کا بیان ہے کہ ان کا بیٹا عبد اللہ “جنگ جمل” میں شہید ہوا۔","",{"fn":"(1) التاریخ الکبیر (۲۸۲/۱)"}],[2593,"§۲۶۰۰ ۔ ربیعہ بن رفیع (تغیر ہے)(1)\nابن شبلہ بن ضمیر بن ربیعہ بن یروع بن ابن سہال بن عوف بن امری القیس بن بہثہ بن سلیم اسلمی۔ انہیں ابن ابو کثیر (جوان کی والدہ ہیں) بھی کہا جاتا ہے، بقول بعض: ان کی والدہ کا نام غنفشاء، اسی پر ابن شہاب، ہشام بن الکلبی اور ابو عبیدہ نے اعتماد کیا ہے۔ ابو اسحاق(2) مغازی میں غزوہ حنین کے ذیل میں فرماتے ہیں: جب مشرکین شکست سے دوچار ہوئے تو ربیعہ بن رفیع کو درید بن الصمہ مل گیا جو لڑائی میں ان کے ساتھ تھا تو انہوں نے سمجھا کہ یہ کوئی عورت ہے، کیا د کیا د کہتے ہیں ایک بوڑھا کمزور شخص ہے پھر اس کے قتل کا قصہ بیان کیا۔ اسی میں ہے کہ اس نے کہا: جب تم اپنی والدہ کے پاس جانا تو بتانا “میں نے درید بن الصمہ کو قتل کر دیا ہے”۔ انہوں نے آ کر اپنی والدہ کو بتایا۔ انہوں نے فرمایا: “اس نے تمہاری (نصیلی) مالوں کو ذرا کیا تھا”۔ ابو عبیدہ نے اپنی کتاب “المجاہم” میں یہ اضافہ نقل کیا ہے کہ ان کی والدہ نے ان سے کہا: جس وقت اس نے تم پر اپنا احسان ظاہر کیا تو تم نے اس کے قتل سے ہاتھ کھینچ کر اس پر احسان نہ کیا؟ انہوں نے عرض کی: میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی رضا مندی کے مقابلہ میں احسان کیسے کر سکتا تھا۔ اس سلسلہ میں واقدی نے ابو عبیدہ کی موافقت کی ہے۔ البتہ ابن کلبی فرماتے ہیں: یہ رزق بن ربیعہ بن رفیع ہیں۔ واللہ اعلم۔ حدیث ابو موسیٰ اشعری رضی اللہ عنہ جو مسلم میں ہے کہ انہوں نے درید بن الصمہ کو قتل کیا تھا، اس سے پہلے درید نے ان کے چچا ابو عامر الاشعری کو قتل کیا تھا۔ لیکن ابن اسحاق کا بیان ہے کہ ابو موسیٰ نے قتل کیا وہ سلمہ بن درید بن الصمہ تھا یہی زیادہ مناسب ہے اس واسطے کہ درید بن الصمہ اس وقت اپنے بڑھاپے کی وجہ سے لڑنے والوں میں شامل نہیں تھا۔","",{"fn":"(1) اسد الغابہ (۱۶۳۹) استیعاب (۷۵۸)\n(2) السیرۃ النبویہ (۲۴/۴)"}],[2594,"§۲۶۰۱ ۔ ربیعہ بن رقیع(1)\nبن مسلمہ بن حکم بن صلاۃ بن عبد اللہ بن عبدی بن جنب بن الحمیر تیمی خمیری۔ ابن کلبی اور ابن حبیب نے بنی تمیم میں سے نبی صلی اللہ علیہ وسلم کے پاس آنے والوں میں ان کا ذکر کیا ہے جنہوں نے آپ کو خجروں کے پیچھے سے پکارا تھا۔ الا عمرو بن بشار کے حالات میں بھی ان کا ذکر ہے۔ ابن اسحاق(2) مغازی بواسطہ عاصم بن عمر بن قتادہ روایت کرتے ہیں کہ قتادہ نے کہا: اللہ کے رسول! میرے ذمہ اولا و اسماعیل علیہم السلام میں سے ایک غلام آزاد کرنا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “بلعنبر کے قیدی آئے ہیں”۔ ان میں بنی تمیم کا ایک وفد بھی آیا تھا۔ ان میں ربیعہ بن رفیع بن زمیع، سبرہ بن عمرو، وردان بن محرز، فراس بن حابس اور ان کے بھائی اقرع بھی تھے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے ان قیدیوں کے بارے بات کی تھی۔","",{"fn":"(1) اسد الغابہ (۱۶۴۰) تجرید (۱۷۹/۱)\n(2) السیرۃ النبویہ (۲۰۳/۴)"}],[2595,"§۲۶۰۲ ۔ ربیعہ بن رواء العنسی(1)\nطبرانی(2) وغیرہ نے ان کا ذکر کیا ہے اور بطریق عیسیٰ بن محمد بن عبد العزیز بن ابی بکر بن محمد وہ اپنے والد سے بحوالہ عبد العزیز انہوں نے اپنے والد سے روایت کی ہے کہ ربیعہ بن رواء عیسیٰ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ آپ اس وقت شام کا کھانا کھا رہے تھے۔ آپ نے انہیں کھانے میں شامل ہونے کا کہا تو انہوں نے بھی کھانا کھایا۔ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: “کیا تم میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی دعا و عبادت کے لائق نہیں اور محمد صلی اللہ علیہ وسلم اس کے بندہ اور رسول ہیں”۔ چنانچہ انہوں نے یہی الفاظ کہے۔ آپ علیہ السلام نے ان سے فرمایا: “کیا تم نے اپنی مرضی سے کہے ہیں یا ڈر کر”۔ انہوں نے عرض کی: رغبت و دچپی کا جہاں تک تعلق ہے وہ تو آپ کے ہاتھ میں نہیں۔ رہی خوف کی بات تو اللہ کی قسم! ہمارے ایسے شہر ہیں وہاں ہم تک آپ کے لشکر نہیں پہنچ سکتے۔ (حدیث) اسی میں نبی صلی اللہ علیہ وسلم کا ارشاد ہے: بعض میں بعض لوگ خطیب بھی ہیں۔ اسی میں ہے کہ وہ اپنے علاقہ کی طرف جاتے ہوئے فوت ہو گئے تھے۔ روایت میں جو ابو بکر بن محمد ہیں، میرے خیال میں وہ ابن عمر بن حزم ہیں۔","",{"fn":"(1) اسد الغابہ (۱۶۴۱) تجرید (۱۷۹/۱)\n(2) المعجم الکبیر (۴۶۰۲/۵)"}],[2596,"§۲۶۰۳ ۔ ربیعہ بن روح العنسی مدنی(1)\nبقول ابو عمر ان سے محمد بن عمرو بن حزم نے روایت کی ہے، ابن الاثیر(2) فرماتے ہیں: میرا غالب گمان ہے کہ یہ سابقہ شخصیت کے علاوہ کوئی اور صاحب ہیں۔ کیونکہ ان سے محمد روایت کرتے ہیں، اور وہ مدنی ہیں جبکہ پہلے صاحب اپنے علاقہ میں واپس آ گئے اور نبی صلی اللہ علیہ وسلم کی حیات میں فوت ہوئے۔ میں کہتا ہوں: بلکہ میرا غالب گمان یہ ہے کہ دونوں ایک ہیں۔ ان کے والد کے نام میں لفظی غلطی ہوئی ہے اور جو دبل ابن الاثیر نے پیش کی ہے وہ کمزور ہے، اس واسطے کہ اس میں کوئی مشکل نہیں کہ ان کا قصہ محمد روایت کریں اگر چہ ان کا دور نہیں پایا ہے جیسے دوسرے لوگ روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۱۶۴۲) استیعاب (۷۵۹) تجرید (۱۷۹/۱)\n(2) اسد الغابہ (۱۸۰/۲)"}],[2597,"§۲۶۰۴ ۔ ربیعہ بن زرعہ الخضرمی\nبقول ابو سعید بن یونس۔ صحابی رسول ہیں۔ فتح مصر میں شریک ہوئے۔"],[2598,"§۲۶۰۵ ۔ ربیعہ بن زیاد(1)\nبقول بعض: ابن ابی یزید اسلمی، ایک قول ہے: ان کا نام رزق ہے۔ ان کی حدیث ہے کہ “جہادی سفر میں اللہ نے والا) غبار جنت کی خوشبو ہے” اس کی سند میں کلام ہے۔ ابن مندہ، اور ابو عمر(2) نے اسے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۴۳) استیعاب (۷۶۰)\n(2) اسد الغابہ (۱۶۴۴)"}],[2599,"§۲۶۰۶ ۔ ربیعہ بن سعد الاسلمی(1)\nایو الفراس، امام بخاری رضی اللہ عنہ نے ان کا ذکر کیا ہے کہ مجھے لگتا ہے یہ صحابی ہیں اور حجازی ہیں۔ میں کہتا ہوں: مجھے خدشہ ہے کہ یہ ربیعہ بن کعب ہوں جن کا تذکرہ ہوتا ہے۔","",{"fn":"(1) استیعاب (۷۱/۲)"}],[2600,"§۲۶۰۷ ۔ ربیعہ بن اسکن(1)\nابو رویحہ الخزاعی۔ بقول ابن حبان:(2) انہیں شرف صحابیت حاصل ہے۔ فلسطین میں رہتے تھے اور بیت جبرین میں فوت ہوئے۔ الکنی میں الدولابی یا قرط از ہیں: موسیٰ بن سہل سے میں نے سنا وہ کہتے تھے: ابو رویحہ الفرغی ششم سے تعلق رکھتے ہیں۔ ان کا نام ربیعہ بن اسکنین ہے۔ “الافراز” میں اسحاق بن ابراہیم المرلی نے شام کے جنگل کی احادیث میں سے ان کا ذکر بطریق “حرام بن عبد الحسن ہمی بواسطہ ابو زرعہ النزعی ثم انھلی” کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے لیے سفید کپڑے کا جھنڈا بنایا، جو ہاتھ بھر لمبا اور ہاتھ بھر چوڑا تھا۔ یہ ابن مندہ کے الفاظ ہیں۔ دولابی کی روایت میں ہے “سفید جھنڈا، اور فرمایا: ابو رویحہ! اپنی قوم کے پاس جا کر اعلان کر دو جو اس جھنڈے تلے آ جائے گا اسے امن ہے”۔(3) تو میں نے ایسا کیا۔ دولابی اور ابن مندہ بطریق ابو عبیدہ عبد الجبار بن محرز بن عبد الجبار بن ابی رویحہ اپنے والد سے وہ اپنے والد سے وہ ابو رویحہ بن اسکنین سے روایت کرتے ہیں، فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ صلی اللہ علیہ وسلم نے میرے لیے سفید جھنڈا بنایا۔ ابو نعیم لکھتے ہیں کہ ابو نعیم بحوالہ ابو زرعہ فقی روایت کرتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ لوگوں میں مواخات (بھائی چارہ) قائم کر رہے تھے، میں رو گیا اتنے میں ایک سیاہ فام شخص آیا۔ آپ نے اس کے ساتھ میرا بھائی چارہ قائم کر دیا اور فرمایا: “تم اس کے بھائی ہو اور یہ تمہارا بھائی ہے”۔","",{"fn":"(1) اسد الغابہ (۱۶۴۵) تجرید (۱۸۰/۱)\n(2) الثقات (۱۲۹/۳)\n(3) الکنی والاسماء للدولابی (۳۰/۱)"}],[2601,"§۲۶۰۸ ۔ ربیعہ بن سیار\nبن عمرو بن عوف۔ ابن ماکولا(1) کا بیان ہے کہ انہیں شرف صحابیت حاصل ہے، یہ بات میں نے مغلطائی کے قلم سے لکھی پڑھی ہے۔ جو تجرید میں بھی ہے۔ مجھے خدشہ ہے کہ یہ ربیعہ بن عمرو بن یسار ہیں، جن کا تذکرہ ہوتا ہے۔","",{"fn":"(1) الاکمال (۴۹/۲)"}],[2602,"§۲۶۰۹ ۔ ربیعہ بن ابی الصلت الثقفی\nظلیفہ بن خیاط نے ان کا ذکر بصرہ میں فروش ہونے والے اور وہاں رہائش گاہیں بنانے والے صحابہ میں کیا ہے۔ ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[2603,"§۲۶۱۰ ۔ ربیعہ بن عامر(1)\nبن سجاد الازدی، بقول بعض: الذکلی، اہل فلسطین میں ان کا شمار ہوتا ہے۔ ابو عمر(2) نے ان کے دادا کا نام الباز بتایا ہے۔ ان کی حدیث امام احمد، نسائی، اور حاکم نے بطریق یحییٰ بن حسان جو بیت المقدس والوں کے شیخ ہیں وہ ربیعہ بن عامر سے روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “یا ذوالجلال والاکرام”۔(3) کو نہ چھوڑو۔ بقول ابو عمر(4) ان کی یہی حدیث اسی سند سے مشہور ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۴۷) استیعاب (۷۶۱) تجرید (۱۸۰/۱)\n(2) استیعاب (۷۱/۲)\n(3) ترمذی کتاب الدعوات باب ۹۱ حدیث (۳۵۴۶) مسند احمد (۱۷۷/۴) المستدرک (۴۹۸/۱)\n(4) استیعاب (۷۱/۲)"}],[2604,"§۲۶۱۱ ۔ ربیعہ بن عامر\nبن مالک۔ یہ ابن ابی براء ہیں، وہ تذکرہ ہوتا ہے۔"],[2605,"§۲۶۱۲ ۔ ربیعہ بن عباد(1)\nالدیلی۔ بقول بعض: ان کے والد کا نام عباد ہے، بہر حال پہلا نام درست ہے یہ ابن عتبین وغیرہ کا قول ہے۔ امام احمد(2) نے بطریق ابو نوار و محمد بن ربیعہ بن عباد روایت کی ہے۔ جو دور جاہلیت کے ہیں پھر اسلام لے آئے تھے۔ فرمایا: میں نے بازار عکاظ میں ابو لہب کو دیکھا، وہ جاہلیت میں نبی صلی اللہ علیہ وسلم کے پیچھے تھا اور بازار دی الحجاز میں آپ فرما رہے تھے: لوگو! لا الہ الا اللہ کہو، کامیاب و کامران ہو جاؤ گے۔ (حدیث) عبد اللہ بن احمد نے اپنی زیادات(3) میں اس کی تخریج بطریق سعید بن خالد قتائلی بواسطہ ربیعہ بن عباد و نکل کی ہے۔ فرمایا: میں نے بازار عکاظ میں ابو لہب کو دیکھا، وہ رسول اللہ صلی اللہ علیہ وسلم کے پیچھے پیچھے تھا اور یہ کہو اس کر رہا تھا (نعوذ باللہ): “یہ بہک گیا، کہیں تمہیں نہ بہکا دے”۔ (حدیث) طبرانی(4) نے بطریق سعید بن المکہ بواسطہ ابن اسکنہ راو زید بن اسلم نسب نے ربیعہ سے اسی کا مفعوم نقل کیا ہے اور بطریق ابن اسحاق، حسین بن عبد اللہ اللہ مروی ہے کہ میں نے ربیعہ بن عباد کو فرما تے سنا: میں اپنے والد کے ساتھ تھا، اس وقت میری جوانی کی عمر تھی، میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم قبائل کے ساتھ جا رہے ہیں، میں نے اپنے والد سے پوچھا: یہ کون ہیں؟ پھر حدیث ذکر کی۔ امام واقدی نے ایک اور سند سے بحوالہ ربیعہ روایت کی ہے، فرمایا: فتح مکہ کے بعد میں اپنے والد کے ہمراہ گھاس لینے گیا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، آپ کو دیکھتے ہی میں نے پہچان لیا اور مجھے یاد آگیا کہ میں نے آپ کو بازار ذی مجاز میں دیکھا تھا۔ آپ فرما رہے تھے: “اسلام میں حلیف بننے کی کوئی حیثیت نہیں رہی”۔ ابو عمر(5) فرماتے ہیں: ربیعہ نے لمبی عمر پائی ہے، مجھے معلوم نہیں ان کا انتقال کب ہوا۔ میں کہتا ہوں: خلیفہ اور ابن سعد کا بیان ہے کہ ان کی وفات ولید کے دور حکومت میں ہوئی تھی۔","",{"fn":"(1) اسد الغابہ (۱۶۴۸) استیعاب (۷۶۳)\n(2) مسند احمد (۴۹۲/۳)\n(3) مسند احمد (۴۹۲/۳)\n(4) المعجم الکبیر (۴۵۸۸/۵)\n(5) استیعاب (۷۲/۲)"}],[2606,"§۲۶۱۳ ۔ ربیعہ بن عثمان(1)\nبن ربیعہ التیمی۔ ابن مندہ کی بحوالہ ربیعہ بن عثمان روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں مسجد خیف میں خطبہ دیا، ارشاد فرمایا: “اللہ تعالیٰ اس شخص کو خوش و خرم رکھے جس نے میری بات (حدیث سنی)”۔ حدیث طویل ہے اور بطریق عمرو بن عبد الغفار بحوالہ ربیعہ بن عثمان مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں منیٰ کی مسجد خیف میں نماز پڑھائی۔","",{"fn":"(1) اسد الغابہ (۱۶۵۱)"}],[2607,"§۲۶۱۴ ۔ ربیعہ بن عتیک\nفتوح میں سیف نے ذکر کیا ہے کہ سیدنا خالد بن ولید نے دور صدیقی میں انہیں حیرہ کا امیر بنایا تھا۔ اور ہم پہلے کئی بار یہ بات کہہ چکے ہیں کہ اس دور میں صحابہ ہی امیر بنائے جاتے تھے۔"],[2608,"§۲۶۱۵ ۔ ربیعہ بن عمرو(1)\nبن عمیر بن عوف بن عقدہ بن غیرہ بن عوف بن ثقیف، مختار کے والد ابو عبید کے بھائی۔ ابن مندہ نے بطریق کلبی بواسطہ ابو صالح سیدنا ابن عباس رضی اللہ عنہ سے یہ روایت نقل کی ہے کہ یہ آیت ربیعہ بن عمرو اور ان کے ساتھیوں کے بارے میں نازل ہوئی: “تم لوگ اگر سود سے توبہ کر لو تو تمہارے لیے اصل مال (راس المال) ہیں”۔(2) ان کے بھائی حبیب بن عمرو کے حالات میں ان کا تذکرہ ہوا ہے۔","",{"fn":"(1) ترمذی کتاب العلم (۲۶۵۸) مجمع الزوائد (۹۴/۱) (۱۴۱/۱) جامع المسانید (۲۵۱/۴)\n(2) اسد الغابہ (۱۶۵۲) تجرید (۱۸۰/۱)"}],[2609,"§۲۶۱۶ ۔ ربیعہ بن عمرو(1)\nبن سیار بن عوف بن جراد بن یروع، انجی، انصار میں سے بنی اشجار کے حلیف ہیں۔ یہ دولیجہ بن عمرو کے بھائی ہیں۔ دونوں کا ذکر ابن کلبی نے کیا ہے اور ابو علی الغسانی نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) سورۃ البقرۃ (۲۷۹)"}],[2610,"§۲۶۱۷ ۔ ربیعہ بن عمرو الجرشی(1)\nتابعی ہیں۔ ابن الغاز میں ان کا تذکرہ ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۵۳) تجرید (۱۸۰/۱)"}],[2611,"§۲۶۱۸ ۔ ربیعہ بن عوف\nالربیع بن مالک میں تذکرہ ہوا ہے۔"],[2612,"§۲۶۱۹ ۔ ربیعہ بن عیدان(1)\nیہی مشہور ہے۔ ابن ذی الحرف بن وائل بن ذی طواف الحضری، بقول بعض: الکندی۔ بروایت طبرانی(2) بحوالہ علقمہ بن وائل وہ اپنے والد سے روایت کرتے ہیں۔ فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس تھا آپ کے پاس دو شخص فیصلہ کرانے آئے، ان میں سے ایک نے کہا: اللہ کے رسول! اس نے دور جاہلیت میں میری زمین چھین لی تھی۔ اور وہ امرو القیس بن عابس اور ان کے مد مقابل ربیعہ بن عیدان تھے۔۔۔۔ (حدیث) اس کی اصل مسلم(3) میں حدیث علقمہ سے بغیر نام کے ثابت ہے۔ جس کے کئی طرق ہیں۔ بقول ابو سعید بن یونس: ربیعہ بن عیدان بن ربیعہ الا کبر بن عیدان الا کبر بن مالک بن زید بن ربیعہ حضری، فتح مصر میں شریک ہوئے، انہیں شرف صحابیت حاصل ہے۔ لیکن ہمیں ان کی کوئی روایت معلوم نہیں۔ ان کا تذکرہ عیدان بن اشوع میں ہوگا۔","",{"fn":"(1) اسد الغابہ (۱۶۵۴) استیعاب (۷۶۵)\n(2) المعجم الکبیر (۲۴/۲۲)\n(3) مسلم کتاب الایمان باب وعید من اقتطع حق مسلم (۲۲۴)"}],[2613,"§۲۶۲۰ ۔ ربیعہ الجرشی(1)\nابن عمرو، بقول بعض: ابن الغاز حافظ ابن عساکر فرماتے ہیں: پہلا نام زیادہ صحیح ہے۔ ابن اسکن کا بیان ہے: یہ ربیعہ بن الزوم ہیں، کنیت ابو الغاز رخی۔ یہ ہشام بن الغاز بن ربیعہ کے دادا ہیں۔ بقول علامہ بغوی: ان کے سامع میں شک ہے۔ ابن ابی حاتم(2) فرماتے ہیں، میرے والد نے فرمایا: بقول بعض انہیں شرف صحابیت حاصل ہے۔ ابو زرعہ دمشقی نے ان کا تذکرہ تابعین کے دوسرے طبقہ میں کیا ہے اور ابن سمیع نے پہلے طبقہ میں۔ الدار قطنی فرماتے ہیں: ان کے صحابی ہونے میں تردد ہے۔ بقول ابن عسکر کی: ان کے صحابی ہونے میں اختلاف ہے۔ ابن سعد لکھتے ہیں: شام میں فروش ہونے والے صحابہ میں سے ربیعہ بن عمر الجرشی ہیں۔ یہ حدیث میں ہے انہیں شرف صحابیت حاصل ہے وہ ثقہ معتبر ہیں۔ الصوری طبقات کے حاشیہ پر لکھتے ہیں: مجھے ان کے صحابی ہونے کا علم نہیں۔ ابن اسکن بطریق زید بن ابی افیہ بواسطہ عبد الملک بن یزید بحوالہ ربیعہ الجرشی روایت کرتے ہیں، وہ صحابی رسول ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “قیامت سے پہلے دس نشانیاں ہوں گی”۔(3) پھر وہ حدیث ذکر کی۔ امام بخاری(4) کا قول ہے: بشر بن حاتم بواسطہ عبد اللہ، زید سے وہ عبد الملک سے وہ عثمان کے مولا وہ بحوالہ ربیعہ الجرشی جنہیں شرف صحابیت حاصل ہے، روایت کرتے ہیں۔ ابن ابی شیبہ بطریق ہشام بن الغاز بواسطہ اپنے والد بحوالہ اپنے دادا ربیعہ سے روایت کرتے ہیں۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو ارشاد فرماتے سنا: “میری امت کے آخر میں رمضاء، پھر آذ اور گوناگوں (صورتوں کا گزر) تا ہوگا”۔ (حدیث)(5) بخاری نے بطریق علی بن رباح بحوالہ ربیعہ الجرشی روایت کی ہے، فرماتے ہیں: کسی نے کہا: “اللہ کے رسول! قرآن کی کون سی سورت افضل ہے؟” آپ صلی اللہ علیہ وسلم نے فرمایا: “سورۃ البقرۃ”۔ (حدیث) طبرانی صحیح اسناد سے بواسطہ قتادہ بواسطہ نظر بن انس کہ انہوں نے یہ روایت ربیعہ الجرشی سے نقل کی ہے۔ انہیں شرف صحابیت حاصل ہے۔ انہوں نے اللہ تعالیٰ کے اس ارشاد کے بارے میں فرمایا: “قیامت کے روز زمین و آسمان ان کے دائیں ہاتھ میں لپٹے ہوں گے”۔(6) آپ نے اپنے ہاتھ سے اشارہ کیا، اور بطریق عباد بن منصور بواسطہ ایوب، ابو قلابہ سے وہ عطیہ سے وہ ربیعہ الجرشی سے روایت کرتے ہیں، پھر دوسری حدیث ذکر کی۔ وہ سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے ہیں، ان سے خالد بن معد ان، عطیہ بن قیس، حارث بن یزید، یحییٰ بن میمون، جن دونوں کا تعلق مصر سے ہے۔ مجاہد اور ابو التوکل الناجی البصری فرماتے ہیں: میری ان سے ملاقات ہوئی، وہ لوگوں کے فقیر تھے، انہیں یہ مقام امیر معاویہ رضی اللہ عنہ اور بشیر بن کعب کے دور میں حاصل تھا۔ یعقوب بن شیبہ کا قول ہے: وہ ایک فقیر تھے، مؤرخین کا اس پر اتفاق ہے کہ وہ حجر راہط میں ضحاک بن قیس کے ساتھ ۶۴ھ میں شہید ہوئے، وہ زہری تھے۔","",{"fn":"(1) اسد الغابہ (۱۶۵۵) استیعاب (۷۶۴)\n(2) الجرح والتعدیل (۴۷۳/۲)\n(3) کنز العمال (۳۸۴۴۷)\n(4) التاریخ (۲۸۱/۱)\n(5) کنز العمال (۳۸۷/۶)\n(6) سورۃ الزمر (۶۷)"}],[2614,"§۲۶۲۱ ۔ ربیعہ بن الفراس(1)\nیقال: الفارسی۔ اہل مصر میں شمار ہوتے ہیں۔ ان کی حدیث ابن لہیعہ نے بکر بن سوادہ سے بواسطہ زیاد بن نعیم بحوالہ ربیعہ بن الفراس نقل کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “ایک قبیلہ چلتے چلتے ایک ایسے گھر کے پاس پہنچے گا جس کی عرب پردے ڈال کر تقسیم کرتے ہوں گے یہ اس کا مال لے لیں گے”۔ (حدیث)(2) ابن یونس نے ان کا ذکر کر کے لکھا ہے: بکر بن سوادہ بواسطہ زیاد بن نعیم ان سے ان کا قول نقل کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۱۶۵۶) تجرید (۱۸۰/۱)\n(2) جامع المسانید (۲۵۴/۴)"}],[2615,"§۲۶۲۲ ۔ ربیعہ بن الفضل(1)\nبن حبیب بن زید بن تمیم از معاویہ بن عوف۔ ابن لہیعہ نے بواسطہ ابو الاسود بحوالہ عمرہ ان کا ذکر شرکاء احد اور شہداء احد میں کیا ہے۔ طبرانی(2) وغیرہ نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۵۷)\n(2) المعجم الکبیر (۴۵۹۵)"}],[2616,"§۲۶۲۳ ۔ ربیعہ بن قریش\nربیعہ مادی کے آخر میں تذکرہ ہوگا۔"],[2617,"§۲۶۲۴ ۔ ربیعہ بن قیس العدوانی(1)\nضرار بن صرد نے اپنی عبد اللہ بن ابی رافع تک کی سند سے ان کا تذکرہ سیدنا علی رضی اللہ عنہ کے ساتھ جنگ صفین میں شرکت کرنے والے صحابہ میں کیا ہے۔ یہ عدوانی قس سے ہیں۔ ابو نعیم وغیرہ نے اس کی تخریج کی ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۵۹)"}],[2618,"§۲۶۲۵ ۔ ربیعہ بن کعب(1)\nبن مالک بن شعیر ابو فراس اسلمی حجازی، امام مسلم وغیرہ نے ان کی حدیث بطریق ابو مکہ بحوالہ ربیعہ بن کعب روایت کی ہے۔ فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے دروازے پر رات بسر کرتا، آپ کو وضو کا پانی دیتا مجھے رات کے وقت آپ صلی اللہ علیہ وسلم کی یہ آواز سنائی دی: “سمع اللہ لمن حمدہ”۔(2) ان کا تعلق اہل صفر سے تھا۔ الیاکم ابو احمد امام بخاری رضی اللہ عنہ کے اتباع میں کہتے ہیں: ابو فراس جن سے ابو عمران جو بنی روایت کرتے ہیں وہ ان ربیعہ بن کعب کے علاوہ ہیں۔ امام مسلم اور ابی الکم علوم الحدیث میں لکھتے ہیں: ابو اسلم بن عبد الرحمن بن ربیعہ بن کعب سے روایت کرنے میں منفرد ہیں۔ ذہبی لکھتے ہیں: ان سے محمد بن عمرو بن عطا، حنظلہ بن علی اسلمی اور نعیم ابن حجر بھی روایت کرتے ہیں۔ میں کہتا ہوں: محمد بن عمرو کی ان سے مروی روایت ابن مندہ کے ہاں ہے، لیکن انہوں نے فرمایا: “ابو فراس اسلمی سے مروی ہے” ان کا نام نہیں لیا۔ مسند میں ان محمد بن عمرو کی روایت ابو اسلمہ سے بحوالہ ربیعہ بن کعب ہے۔ اور مستدرک میں بطریق ابو عمران جو بنی ہے۔ مجھ سے ربیعہ بن کعب نے بیان کیا، اس سے اس شخص کی بات کو تقویت ملتی ہے، جو اس کا قائل ہے کہ ابو فراس، ابو عمران کے شیخ ہیں اور وہ ربیعہ ہیں اس سے یہ بات مکمل ہو جاتی ہے کہ ابو اسلمہ کے علاوہ ربیعہ چار راوی ہیں۔ امام واقدی فرماتے ہیں: وہ اصحاب صفہ سے ہیں۔ آپ علیہ السلام کی وفات تک آپ کے ساتھ رہے۔ پھر مدینہ سے چلے گئے اور بلاد اسلم میں جا بسے جو مدینہ سے ایک برید (تقریباً ۱۲ میل) کے فاصلہ پر ہے۔ واقعہ حرا تک زندہ رہے اور ذو الحجہ ۶۳ھ میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۶۶۰) استیعاب (۷۶۷) تجرید (۱۸۰/۱)\n(2) مسند احمد (۵۷/۵) المعجم الکبیر (۴۵۷۱)"}],[2619,"§۲۶۲۶ ۔ ربیعہ بن کعب (دوسرے)\nالربیع بن مالک میں تذکرہ ہوا ہے۔"],[2620,"§۲۶۲۷ ۔ ربیعہ بن کلدہ\nبن ابی الصلت ثقف، شرف صحابیت رکھتے ہیں۔ ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ شاید یہ پہلے والے ہیں، وہاں ان کے دادا کی طرف ان کا انتساب ہوا ہے۔"],[2621,"§۲۶۲۸ ۔ ربیعہ بن لہیعہ(1)\nبقول بعض: لہا۔ الحضرمی یعقوب بن محمد الزہری بواسطہ زرعہ بن مفعلس بواسطہ اپنے والد لہیعہ بن ربیعہ وہ اپنے والد سے ربیعہ بن لہیعہ نقل کرتے ہیں، فرمایا: “میں نبی صلی اللہ علیہ وسلم کے پاس آیا، میں نے اپنی رکاٹا پیش کی، آپ نے مجھے تحفہ لکھوا کر دی”۔(2) (حدیث)","",{"fn":"(1) اسد الغابہ (۱۶۶۲) استیعاب (۷۶۸)\n(2) جامع المسانید (۲۶۳/۴)"}],[2622,"§۲۶۲۹ ۔ ربیعہ بن لیث\nبن مخدج بن سہماس بن لیث “المحرق” ان کا عرف ہے۔ جس کی وجہ شہرت یہ اشعار ہوئے: “میں جب اس زمین میں ہوں جس میں اللہ کا بندہ محمد (صلی اللہ علیہ وسلم) ہے اور وہاں میں ظاہر نہ ہوں تو میرے لئے خشکی اور تری کی زمینی فضا گھٹا نہیں نہ رکھے۔ اور وہاں میں دل میں آنے والی بات ظاہر کر دوں۔ ارے یہ قریش جنہوں نے اللہ تعالیٰ اپنے رب کا انکار کیا جیسے عاد اور ثمود نے انکار کیا تھا”۔ مرز بانی نے ان کا ذکر کیا ہے اور ان اشعار کا تذکرہ عبد اللہ بن حارث بن قیس اسلمی کے حالات میں کر کے کہا ہے کہ ان کی نسبت ان کی طرف زیادہ ثابت ہے۔"],[2623,"§۲۶۳۰ ۔ ربیعہ بن مالک\nالربیع بن مالک میں تذکرہ ہوا ہے۔"],[2624,"§۲۶۳۱ ۔ ربیعہ بن معاویہ\nبن حارث بن معاویہ بن ثور، انہیں شرف صحابیت حاصل ہے۔ یہ قول خلیفہ کا ہے۔ ابن فحون نے ان کا ذکر کیا ہے۔"],[2625,"§۲۶۳۲ ۔ ربیعہ بن ملّہ(1)\nحبیب بن ملّہ کے بھائی۔ ان کا تذکرہ سید بن ابی ایاس کے حالات میں گزرا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۶۵)"}],[2626,"§۲۶۳۳ ۔ ربیعہ بن المنتفق العقیلی\nان کا تذکرہ عمرہ بن مالک الراوی کے سوانح میں ہوگا۔"],[2627,"§۲۶۳۴ ۔ ربیعہ بن ملاعب الاسنۃ\nابو براء، عامر بن مالک بن جعفر بن کلاب کا بھائی ثم جعفری۔ میں نے ماسوائے ابو سعید اسکری کے کسی کو نہیں دیکھا کہ اس نے ان کا صحابہ میں ذکر کیا ہو۔ ابو سعید اسکری نے دیوان حسان جو انہوں نے مرتب کیا ہے اس میں ابو جعفر بن حبیب سے ان کی روایت ہے سیدنا حسان نے ربیعہ بن عامر بن مالک سے کہا اور عامر ملاعب الاسنۃ ہیں جن کا ترجمہ قصہ میں ذکر ہے اور ربیعہ بن عامر کو عامر بن الطفیل کے خلاف ابھارتے ہیں: “ربیعہ کو میری جانب سے کوئی پیغام دے گا، میرے بعد تیم نے کیسی تبدیلی کر دی، تیرا والد کیسے کام کرنے والا ابو براء تھا اور تیرا چچا بن سعد معزز آدمی ہے، کیا المبین کی اولاد تم سے نہیں گھبرائی۔ جبکہ تم اہل نجد کی ہیبت ہوں سے ہو۔ سید زوری جو ابو براء کے ساتھ ہوئی تاکہ وہ اپنا عہد (ذمہ داری) توڑ دے علی، جان بوجھ کر کیے جیسی کیسے ہو سکتی ہے”۔ راوی کا بیان ہے: جب ربیعہ کے کان میں یہ اشعار پڑے تو وہ نبی صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگے: اگر میں عامر بن طفیل پر تلوار یا نیزے کا وار کروں تو میرے باپ کی طرف سے ہونے والی غداری اس سے دھل جائے گی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں۔ چنانچہ ربیعہ واپس آئے اور عامر کو ایسی ضرب لگائی جس سے قتل ہونے سے بچ گیا۔ اس کی قوم ان پر ٹوٹ پڑی اور عامر بن طفیل سے کہنے لگی: بدلہ لو۔ اس نے کہا: میں نے معاف کر دیا۔ میں کہتا ہوں: بہت سے اہل مغازی نے ذکر کیا ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کی خیر یا روشنی پر یہ میں بھیجی تھی۔ مجھے ان کی بحوالہ ابو الدرا روایت بطریق حبیب بن عبد اللہ بن حوالہ دان کے ملی ہے۔ لگتا ہے انہوں نے اسلام میں لمبی عمر پائی ہے۔"],[2628,"§۲۶۳۵ ۔ ربیعہ بن نیار\nبقول طبرانی انہیں شرف صحابیت حاصل ہے اور ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[2629,"§۲۶۳۶ ۔ ربیعہ بن وقاص(1)\nابن مندہ نے بطریق ابان، انس سے بحوالہ ربیعہ بن وقاص نبی صلی اللہ علیہ وسلم سے منقول یہ روایت نقل کی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “تین جگہوں کی دعا رد نہیں ہوتی، ان میں سے ایک مقام یہ ہے کہ جب کوئی شخص جنگل میں ایسی جگہ کھڑے ہو کر نماز پڑھے جہاں اسے دیکھنے والا کوئی نہ ہو”۔ (حدیث)(2) فرماتے ہیں: یہ روایت ہمیں اسی سند سے معلوم ہے۔ میں کہتا ہوں: اس کی سند ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۶۶) استیعاب (۷۶۹) تجرید (۱۸۲/۱)\n(2) جامع المسانید (۴۶۴/۴)"}],[2630,"§۲۶۳۷ ۔ ربیعہ بن یزید السلمی(1)\nبقول امام بخاری رضی اللہ عنہ(2) انہیں شرف صحابیت حاصل ہے، اور ابن حبان(3) فرماتے ہیں: بعض کا قول ہے کہ یہ صحابی ہیں اور عسکری لکھتے ہیں: کسی نے کہا ہے کہ شرف صحابیت سے مشرف ہیں۔ علامہ ابن عبد البر(4) ربیعہ الجرشی کے سوانح کے آخر میں لکھتے ہیں: ربیعہ بن یزید اسلمی تو وہ ایک تابعیت تھا جو سیدنا علی رضی اللہ عنہ پر سب و شتم کرتا تھا۔ ابو حاتم(5) فرماتے ہیں: ان سے کچھ بھی مروی نہیں اور نہ کوئی کرامت و عزت کے مالک ہیں جس نے ان کا شمار صحابہ میں کیا ہے۔ اس نے کوئی اچھا کام نہیں کیا۔ ابن فحون، ابو علی الغسانی اور ابن معوز نے ابو عمری کتاب کے استدراک میں امام بخاری رضی اللہ عنہ(6) کے قول پر اعتماد کرتے ہوئے ان کا ذکر کر دیا ہے۔","",{"fn":"(1) استیعاب (۲۶۹)\n(2) التاریخ الکبیر (۲۸۰/۱)\n(3) الثقات (۱۲۹/۱)\n(4) استیعاب (۷۴/۲)\n(5) الجرح والتعدیل (۴۷۲/۳)\n(6) التاریخ الکبیر (۲۸۰/۲)"}],[2631,"§۲۶۳۸ ۔ ربیعہ الاجذم الثقفی(1)\nابن شاہین نے ان کا ذکر کیا اور بطریق ابو معشر اپنے راویوں سے کئی مختلف سندوں سے نقل کیا ہے کہ ثقیف کے وفد میں بنی مالک کا ایک ربیعہ الاجذم نامی شخص تھا۔ لوگ آپ سے بیعت کر رہے تھے اور آپ کے ہاتھوں پر ہاتھ پھیر رہے تھے۔ جب ربیعہ بیعت کرنے کے لیے پہنچے، آپ نے فرمایا: “ہم نے تم سے بیعت لے لی واپس چلے جاؤ”۔ چنانچہ وہ واپس آ گئے۔(2)","",{"fn":"(1) اسد الغابہ (۱۶۳۱)\n(2) اسد الغابہ (۵۲/۲)"}],[2632,"§۲۶۳۹ ۔ ربیعہ الجرشی\nابن عمرو میں تذکرہ ہوا ہے۔"],[2633,"§۲۶۴۰ ۔ ربیعہ السعدی\nبغوی نے ان کا ذکر کیا اور بطریق ضحاک بہانی بحوالہ ربیعہ السعدی روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “اے اللہ! دین ابو الجمل بن ہشام یا عمر بن خطاب (میں سے کسی ایک) کے ذریعہ مضبوطی عطا فرما”۔(1)","",{"fn":"(1) کنز العمال (۳۲۷۲۵) جمع الجوامع (۹۷۲۷)"}],[2634,"§۲۶۴۱ ۔ ربیعہ القرشی(1)\nابن ابی خیثمہ نے ان کا ذکر کیا اور کہا: مجھے معلوم نہیں ان کا تعلق کون سے قریش سے ہے؟ حسن بن سفیان، بغوی اور باوردی بطریق جریر بواسطہ عطا، بن السائب بحوالہ ابن ربیعہ وہ اپنے والد سے نقل کرتے ہیں کہ میں نے جاہلیت میں رسول اللہ صلی اللہ علیہ وسلم کو عرفات میں مشرکین کے ساتھ کھڑے دیکھا، وہاں دیکھ کر میں سمجھ گیا کہ اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو اس کی توفیق دی ہے۔ بغوی فرماتے ہیں: ان سے یہ روایت اسی سند سے مروی ہے۔ اس کے ضبط میں اختلاف ہے۔ بعض نے کہا: جادہ کی طرح ہے بعض نے کہا تغییر اور تشدید کے ساتھ ہے۔ ابو نعیم لکھتے ہیں: میرے خیال میں یہ ربیعہ بن عباد ہیں اور سند میں وہ روایت پیش کی ہے جو ابن اسکن نے بطریق مسعود بن سعد بواسطہ عطا، بن السائب، ابن عباد سے انہوں نے اپنے والد سے نقل کی ہے۔ پھر اسی جیسی حدیث ذکر کی۔ میں کہتا ہوں: عطا، کو اختلاط اور وہم ہو گیا تھا، جزم اور مسعود دونوں نے ان سے اختلاط کے بعد سنا ہے۔ ابن جریر نے یہی حدیث ربیعہ بن الحارث بن عبد المطلب کے سوانح میں نقل کر کے کوئی کارنامہ سر انجام نہیں دیا۔ ابن فحون نے نقل کیا ہے کہ انہیں ربیعہ بن قریش بھی کہا جاتا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۵۸) استیعاب (۸۶۳)"}],[2635,"§۲۶۴۲ ۔ رجاء بن الجلاس(1)\nزید بن الجلاس میں ان کا تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۱۶۶۷) استیعاب (۷۷۱)"}],[2636,"§۲۶۴۳ ۔ رجاء الغنوی(1)\nامام بخاری رضی اللہ عنہ نے ان کا ذکر کیا اور ساکنہ بنت الجعد کی بحوالہ ان کے روایت نقل کی ہے کہ جنگ جمل میں ان کا ہاتھ کٹ گیا تھا۔ فرماتے ہیں: نبی صلی اللہ علیہ وسلم نے فرمایا: “اللہ تعالیٰ نے اپنی کتاب یاد کرنے کی توفیق دی ہے اور وہ یہ سمجھے کہ کوئی اور اس سے بڑی فضیلت رکھتا ہے تو اس نے سب سے بڑی نعمت کی ناقدری کی”۔(2) ابن مندہ نے اسی سند سے ایک اور حدیث نقل کی ہے۔ ابن ابی حاتم نے ان کا ذکر کر کے لکھا ہے نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں اور ان سے ساکنہ بنت الجعد روایت کرتی ہیں۔ البتہ ابن حبان(3) نے الثقات التابعین میں ان کا ذکر کیا ہے کہ یہ مرسل روایتیں نقل کرتے تھے۔ ابو عمر(4) لکھتے ہیں: “ان کی حدیث صحیح نہیں ان سے سلامہ بنت الجعد روایت لیتی ہیں”۔ یوں ان سے لفظی غلطی ہو گئی۔","",{"fn":"(1) اسد الغابہ (۱۶۶۸) استیعاب (۷۷۲)\n(2) الدر المنثور (۲۴۹/۱) کنز العمال (۲۳/۷) جامع المسانید (۲۶۹/۴)\n(3) الثقات (۲۳۷/۴)\n(4) اسد الغابہ (۱۶۶۹)"}],[2637,"§۲۶۴۴ ۔ رجاء (بے نسبت)(1)\nابو موسیٰ کی روایت ہے کہ رجاء سے مروی ہے، نبی صلی اللہ علیہ وسلم نے ارشاد فرمایا: “تھوڑی بہت دین کی سمجھ زیادہ عبادت سے افضل ہے”۔ “یہ سند مجہول ہے۔”(2)","",{"fn":"(1) استیعاب (۷۵/۲)\n(2) التاریخ الکبیر (۲۳۱/۲/۴) کنز العمال (۲۸۷۹۴) کشف الخفاء (۲۴۱/۲)"}],[2638,"§۲۶۴۵ ۔ رجل بن بلقین\nابن حزم نے ان کا ذکر کیا ہے کہ یہ ایک صحابی کا اسم علم ہے۔ میں نے قسم رابع میں ان کا شمار کیا ہے۔"],[2639,"§۲۶۴۶ ۔ زحفہ(1)\nابن عمر بن الغفاری ایمام کے والد جن کا تذکرہ حرف (الف) ہمزہ میں ہو چکا ہے اور خفاف کے دادا جن کا ذکر حرف خاء میں پہلے ہوا ہے۔ خفاف کے حالات میں ابو عمر فرماتے ہیں: بقول بعض: یہ ان کے والد اور ان کے دادا صحابہ ہیں۔ اسی بنا پر ابو علی الغسانی اور ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: ابو عمر کی مجھے رحفہ اور ان کے بیٹے اور آگے ان کے بیٹے خفاف کے صحابی ہونے کی ثبوت کی کوئی مستند روایت نہیں ملی۔ جبکہ صحیح بخاری میں سیدنا عمر رضی اللہ عنہ سے مروی ایک روایت میں ہے جس سے خفاف کے بیٹے کا صحابی ہونا معلوم ہوتا ہے۔ اگر ابو عمر کی روایت صحیح ثابت ہو جائے تو یہ چاروں یکے بعد دیگرے صحابہ ہیں۔ رحفہ، ان کا بیٹا ایمام، ان کا بیٹا خفاف، جیسے اسامہ بن زید اور سلمہ بن عمرو بن اکوع کا بیٹا ہے۔ یوں موسیٰ بن عقبہ اور ان کے تابعین کی بات پر اعتراض ہو سکتا ہے کہ سلمہ اور زار چار صحابہ ابو بکر الصدیق رضی اللہ عنہ کے گھرانے کے افراد ہیں۔","",{"fn":"(1) اسد الغابہ (۱۶۷۰)"}],[2640,"§۲۶۴۷ ۔ زحیلہ (تغیر ہے)(1)\nابن شبلہ بن خالد بن شبلہ بن عامر بن بیاضہ انصاری زرقی۔ ابن اسحاق اور موسیٰ بن عقبہ نے ان کا تذکرہ شرکاء بدر میں کیا ہے۔ ابن ہشام لکھتے ہیں: ابن اسحاق نے یہ نام جحم سے بتایا ہے جبکہ درست خام ہے، ایسا ہی انہوں نے مطلقاً نے خام سے یہ نام قلبند کیا ہے۔ پہلے گزر چکا ہے کہ ابو نعیم نے ان کا تذکرہ حرف جیم میں بنام “جبلہ” کیا ہے اور ان کے نام کا پہلا حرف سا ذکر دیا۔","",{"fn":"(1) اسد الغابہ (۱۶۷۲) استیعاب (۷۹۷)"}],[2641,"§۲۶۴۸ ۔ زحنی العنبری\nابن فحون نے ان کا یہاں ذکر کیا ہے جبکہ اوروں نے زام سے یہ نام لکھا ہے، تذکرہ ہوتا ہے۔"],[2642,"§۲۶۴۹ ۔ رداد اللیثی\nابو داؤد نے ان کی حدیث نقل کی ہے۔ کتبوں میں ان کے حالات کی تفصیل بیان ہوگی۔ جو حرف راہ میں ہے۔"],[2643,"§۲۶۵۰ ۔ رداد (دوسرے، بے نسبت)\nعلامتی نے “الوشی” میں باب اوّل کی فصل ثانی میں ان کا ذکر کیا کہ بشیر بن سلمہ بن محمد بن رداد ابن ام مکتوم کی اولاد سے ہیں۔ وہ اپنے والد کے واسطہ سے صحابہ اپنے دادا مرفوع روایت کرتے ہیں: “ہفتے کے روز اگر پہاڑ بھی مشرق سے مغرب کی طرف چلے تو اللہ تعالیٰ اسے واپس اس کے مقام پر لوٹا دے گا”۔ ابن قانع، احمد بن زکریا سے بواسطہ ابراہیم بن ولید بحوالہ بشیر یہ روایت نقل کرتے ہیں۔ اسی طرح یہ روایت ابن قانع نے رداد کے حالات میں درج کی ہے۔ ابن عبد البر اور ابن مندہ نے ان کا ذکر نہیں کیا۔ ان کی اولاد کے نام معلوم ہیں۔ اور یہ حدیث یا منکر ہے یا موضوع۔ میں کہتا ہوں: ابن الاثیر نے اسد الغابہ میں ان کا تذکرہ نہیں کیا ہے اور نہ ذہبی نے اپنی تجرید میں ان کا نام لکھا ہے۔ باوجود یکہ وہ ابن قانع کی، مجمع سے اکثر نقل کرتے ہیں، کیونکہ ان کا نام سنا نہیں گیا، مجھے اس پر تعجب ہوا، میں نے ابن قانع کی مجمع کی مراجعت کی تو راہ میں تو یہ نام نہیں ملا۔ البتہ ترغیب میں انہوں نے “عمرہ” نامی لوگوں میں ان کا تذکرہ کیا ہے۔ چنانچہ عمرو بن ام مکتوم کے حالات کے آخر میں لکھتے ہیں: احمد بن زکریا نے ہم سے بیان کیا۔ پھر وہ روایت ذکر کی۔ اسی طرح “الفردوس” کے مصنف نے جب یہ حدیث نقل کی کہ یہ ابن ام مکتوم کی حدیث ہے اس پر بھروسا کیا ہے۔ البتہ ان کی اولاد کی انہوں نے اپنی کتاب میں کوئی سند نہ ذکر نہیں کی۔ جو ان ام مکتوم کے نام میں اختلاف کی وجہ سے ہے۔ جیسا کہ ان کے حالات میں آ رہا ہے۔ اس بنا پر حدیث سلمہ بن محمد بن رداد کی روایت سے بحوالہ ان کے جد اعلیٰ ابن ام مکتوم مروی ہے۔ واللہ اعلم۔ میں نے یہاں احتمال کی وجہ سے اپنے شیوخ کے شیخ علامتی کا اتباع کرتے ہوئے ان کا نام لکھوا دیا ہے۔"],[2644,"§۲۶۵۱ ۔ ردیح(1)\nتصغیر ہے۔ ابن ذؤیب العنبری، ذؤیب بن شثم العنبری میں نام میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۷۳) تجرید (۱۸۲/۱)"}],[2645,"§۲۶۵۲ ۔ زرعہ بن عبد اللہ انصاری\nابن اسکن کی کتاب میں رباح نامی لوگوں سے پہلے ان کا نام ایسا ہی درج ہے۔ اور فرمایا: ان کی حدیث ابن لہیعہ نے احمد بن حازم سے بواسطہ ابو الحویت زرعہ بن عبد اللہ انصاری روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “تم میں سے کسی کو زندہ رہنا پسند ہوتا ہے حالانکہ فتنوں کی وجہ سے اس کے لیے موت بہترین ہے”۔ (الحدیث)(1) ابو موسیٰ نے یہی حدیث بطریق ابن جرتح، بواسطہ ابو الحویت زرعہ سے انہی الفاظ میں نقل کی ہے اور لکھا ہے کہ یہ زرعہ اسامہ بنت عمیس اور تابعین سے بھی روایت لیتے ہیں۔ انہوں نے حرف زاء میں ان کا تذکرہ کیا ہے۔ واللہ اعلم","",{"fn":"(1) جامع المسانید (۳۶۸/۴)"}],[2646,"§۲۶۵۳ ۔ رزین (بروزن عظیم)(1)\nابن انس بن عامر سلمی۔ ابن حبان(2) فرماتے ہیں، بعض کا قول ہے کہ انہیں شرف صحابیت حاصل ہے۔ ابن اسکن کہتے ہیں: “یہ صحابی ہیں”۔ ابو یعلیٰ، ابن اسکن(3) اور طبرانی نے بطریق نمر بن عوف، نائل بن مطرف بن رزین بن انس سلمی سے مروی ہے کہ مجھ سے میرے والد نے بیان کیا کہ رزین بن انس نے فرمایا: اللہ تعالیٰ نے جب اسلام کو ظاہر کیا، اس وقت ہمارا ایک توان تھا ہمیں خدشہ ہوا کہ کہیں آس پاس کے لوگ اس پر قبضہ نہ جما لیں تو میں نبی صلی اللہ علیہ وسلم کے پاس آیا آپ نے مجھے ایک تحریر لکھوا دی۔ (الحدیث) محمد بن خیر، نائل بن مطرف بن عباس سے وہ اپنے والد کے واسطہ سے اپنے دادا کے حوالہ سے روایت کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم سے ایک کنواں(4) جاگیر میں طلب کیا۔ پھر وہ حدیث ذکر کی۔ مجھے معلوم نہیں، نائل ایک شخصیت ہے یا دو شخص ہیں؟ ابن مندہ فرماتے ہیں: اسی روایت کو عبد السلام بن عمیر الکعبی نے بواسطہ نائل بن عبد الرحمن بن عبد اللہ بن حزم بن انس بن عامر سلمی نقل کیا کہ مجھے میرے والد نے اپنے آبا و اجداد کے حوالہ سے بیان کیا کہ وہ تو حمر رسول اللہ صلی اللہ علیہ وسلم نے “رزین بن انس” کے لیے قلبند کروائی تھی۔ میں کہتا ہوں: اس سے پہلے ان کے والد انس بن عباس کا ذکر ہو چکا ہے جبکہ ان کے دادا عباس کا تذکرہ ان شاء اللہ ابھی ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۷۴) استیعاب (۷۹۹) تجرید (۱۸۲/۱)\n(2) الثقات (۱۳۰/۳)\n(3) المعجم الکبیر (۴۶۳۰) مسند ابی یعلیٰ (۷۱۷۸) کنز العمال (۱۱۴۵۵)\n(4) رکیۃ پانی کا کنواں۔"}],[2647,"§۲۶۵۴ ۔ رزین بن مالک(1)\nبن سلمہ بن ربیعہ بن حارث بن سعد بن عوف الحارثی۔ ابن کلبی، طبری اور الدار قطنی کا بیان ہے کہ انہیں شرف آمد حاصل ہے۔ ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۷۵)"}],[2648,"§۲۶۵۵ ۔ رسیم العبدی الہجری(1)\nابن ماکولا کی کتاب میں یہ نام بروزن عظیم ہے۔ ابن یقط لکھتے ہیں: یہ تصغیر ہے اور فرماتے ہیں: انہوں نے ابو ہثم کے قلم سے نقل کیا ہے۔ میں کہتا ہوں: میں نے بھی اسی طرح ابن اسکن اور ابن ابی حاتم کی کتابوں کی اصل میں دیکھا ہے۔ ان کی حدیث ابن ابی شیبہ(2) اور امام احمد(3) نے بطریق یحییٰ بن غسان، بواسطہ سلطان رحمہ اللہ ان کے والد نقل کی ہے کہ ہم لوگ نبی صلی اللہ علیہ وسلم کی خدمت میں وفد کی صورت میں پہنچے، آپ نے ہمیں برتنوں سے منع فرما دیا تھا، پھر جب ہم آئندہ سال آپ کے پاس آئے تو آپ نے فرمایا: “(اب) جس میں چاہو پیو”۔ (حدیث) ابن مندہ کے سیاق میں ان کے والد کے بارے میں لکھتے ہیں: وہ اہل ہجر میں سے دین کی سمجھ بوجھ رکھنے والے شخص تھے۔ جبکہ ابن اسکن کا قول ہے اس کی سند مجہول ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۷۶) استیعاب (۸۰۰)\n(2) المصنف لابن ابی شیبہ (۱۶۰/۸) (۱۶۱/۸)\n(3) مسند احمد (۴۸۱/۳)"}],[2649,"§۲۶۵۶ ۔ رشدان الجہنی(1)\nبقول امام بخاری انہیں شرف صحابیت حاصل ہے۔ ابن اسکن نے بطریق ابو اویس ان کی یہی حدیث نقل کی ہے کہ جاہلیت میں انہیں شیطان کہا جاتا تھا۔ جب نبی صلی اللہ علیہ وسلم کے ہاں آمد ہوئی، آپ نے پوچھا: تمہارا کیا نام ہے؟ انہوں نے بتایا: “غیان”۔ آپ نے فرمایا: تمہارا گھر کہاں ہے؟ بتایا: وادی غوی میں۔ آپ علیہ السلام نے فرمایا: “نہیں، بلکہ تم رشدان ہو اور تمہارے اہل خاندان وادی رشاد میں ہیں”۔ فرماتے ہیں: یہ علاقہ ابھی تک رشاد ہی کہلاتا ہے۔ ابن اسکن فرماتے ہیں: اس کی سند مجہول ہے۔ ادھر ابن الاثیر کا قول ہے: اس شخص کا صحابہ میں ذکر ہی نہیں۔ ابو نعیم اور ابو عمر کی بات سے یہی پتہ چلتا ہے۔ جہاں تک میرے گمان ہے اس میں کسی راوی کو وہم ہوا ہے۔ جہینہ کے بارے میں جو صحیح روایت ہے وہ یہ ہے کہ بنی غیان بن قیس بن جہینہ کا کوئی وفد گیا تو آپ علیہ السلام نے ان سے پوچھا: تم لوگ کون ہو؟ انہوں نے عرض کی: بنو غیان۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “نہیں بلکہ تم لوگ بنو رشدان ہو”۔(2) میں کہتا ہوں: اس قصہ کو ابن کلبی نے ذکر کیا ہے اور یہی مشہور ہے لیکن اس سے یہ لازم نہیں آتا کہ قبیلہ کے کسی ایک نام میں اس کا اتفاق نہ ہو۔ خصوصاً جبکہ اس کی سند موجود ہے۔ رہی ان کی بات کہ ابو نعیم اور ابو عمر کی بات سے اس کا پتہ چلتا ہے، سو اس کی بات نہیں۔ اس لیے کہ ابو نعیم کے الفاظ ہیں: “متاخرین میں سے کسی نے حدیث ابو اویس سے ان کا ذکر کیا ہے پھر انہوں نے سند اور حدیث نقل کی”۔ اور ابو عمر کے الفاظ ہیں: “رشدان ایک نامعلوم شخص ہیں۔ کسی نے ان کا ذکر ان صحابہ میں کر دیا ہے جو نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔ سو کسی کی عبارت سے وہ بات ثابت نہیں ہوتی جس کا انہوں نے گمان کر رکھا ہے، حالانکہ یہ واضح ہے۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۱۶۷۷) استیعاب (۸۰۱)\n(2) جامع المسانید (۲۷۳/۴)"}],[2650,"§۲۶۵۷ ۔ رشید (تصغیر ہے)(1)\nالغفاری، بنی معاویہ جو انصار سے ہیں ان کے مولا۔ جس نے انہیں رشید الجہر کی کہا ہے وہم ہوا ہے کیونکہ وہ دوسرے ہیں جن کا تعلق مظاہر تابعین سے اور تبح تابعین سے ہے۔ ان کی حدیث بغوی نے بطریق خالد بن مخلد بواسطہ اسماعیل بن ابی حبیب، عبد الرحمن بن ثابت، بحوالہ رشید الغفاری مولا بنی معاویہ نقل کی ہے۔ جبکہ ابن مندہ فرماتے ہیں: ان کی حدیث ابو عامر العقدی بواسطہ ابن ابی حبیب، عبد الرحمن بن ثابت سے بحوالہ رشید الجہر کی مولا بنی معاویہ روایت کرتے ہیں کہ انہوں نے احد میں ایک کافر پر حملہ کر کے کہا: لے میں فارسی تو جوان ہوں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: “تمہیں انصاری کہنے سے کس نے روکا تھا، کیونکہ قوم کا مولا انہیں میں شامل ہے”۔ ان کی روایت میں رشید الجہر کی لکھا ہے۔ فرماتے ہیں: رشید مرسل حدیث روایت کرتے ہیں، واقدی نے بھی یہ قصہ ذکر کیا ہے اور کہا: رشید الغفاری مولا بنی معاویہ تھے، ایک مشرک سے ان کا آمنا سامنا ہوا تو فرمایا، پھر وہ قصہ ذکر کیا۔ فرماتے ہیں: نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: “ابو عمر و اللہ! تم نے اچھا کیا”۔(2) آپ نے اس دن ان کی کنیت رکھی حالانکہ اس وقت ان کی اولاد نہ تھی۔ اسی مفہوم کا قصہ ابن اسحاق نے بھی نقل کیا ہے لیکن انہوں نے “عقبہ الغفاری” کہا، جس کی تفصیل حرف عین میں آئے گی۔ بعض نے اس پر اعتراض کیا ہے کہ وہ ابو عمر رشید ہیں۔ واللہ اعلم","",{"fn":"(1) استیعاب (۸۵/۲) اسد الغابہ (۱۶۷۸) استیعاب (۷۷۲)\n(2) ابو داؤد کتاب الادب باب فی العصبیہ (۵۱۲۳) ابن ماجہ کتاب الجہاد باب النیۃ فی القتال (۲۷۸۴) مسند احمد (۲۹۵/۵)"}],[2651,"§۲۶۵۸ ۔ رشید بن علاج الثقفی\nرشید تصغیر میں تذکرہ ہوتا ہے۔"],[2652,"§۲۶۵۹ ۔ رشید ابو عمیرہ المزنی\nابو یونس فرماتے ہیں: اہل مصر میں ان کا ذکر ہے، مصر میں ان کی ایک حدیث ہے جو ابن لہیعہ نے بکر بن سوادہ سے بحوالہ شیبان خفانی مزینہ کے ایک ابو عمیرہ نامی صحابی رسول اللہ صلی اللہ علیہ وسلم سے نقل کی ہے کہ “جب بھی یہ کسی غزوہ میں شریک ہوتے جب تک یہ نہ پوچھ لیتے کہ کس کے لیے امان ہے تب تک جنگ نہیں کرتے تھے؟”"],[2653,"§۲۶۶۰ ۔ رشید بن مالک(1)\nابو عمیرہ العبدی ازی تیم۔ بقول بعض اسدی از بنی اسد بن خزیمہ۔ بقول دولابی: انہیں شرف صحابیت حاصل ہے۔ امام بخاری نے التاریخ میں، ابن اسکن، باوردی، طبرانی(2) اور ابو احمد الحاکم سب نے بطریق معروف بن واصل روایت کی ہے کہ مجھ سے قبیلہ کی ایک خاتون حفصہ بنت طلق نے بیان کیا کہ مجھے ابو عمیرہ (جو رشید بن مالک ہیں) نے حدیث سنائی کہ ایک دن میں رسول اللہ صلی اللہ علیہ وسلم کے پاس تھا، ایک شخص ایک بڑے لایا جس میں کھجوریں تھیں، کہنے لگا: یہ صدقہ ہے اور اسے لوگوں کے سامنے پیش کر دیا۔ اس وقت سیدنا حسن رضی اللہ عنہ آپ کے سامنے مٹی میں کھیل رہے تھے۔ انہوں نے ایک کھجور اٹھالی، آپ نے ان کے منہ میں انگلی ڈال کر کھجور نکال لی اور فرمایا: ہم آل محمد (صلی اللہ علیہ وسلم) صدقہ نہیں کھاتے”۔ اس اسناد پر ابو نعیم، عبد اللہ بن نمیر اور دوسرے حضرات کا اس سند پر اتفاق ہے جبکہ اسحاق بن محمد نے ان کے مخالف بحوالہ معروف سند نقل کی ہے جیسا کہ اس کی تفصیل قسم اخیر میں عمیر کے ذیل میں بیان ہوگی۔","",{"fn":"(1) اسد الغابہ (۱۶۷۹) استیعاب (۷۷۴) تجرید (۱۸۲/۱)\n(2) المعجم الکبیر (۴۶۳۳)"}],[2654,"§۲۶۶۱ ۔ رعیہ(1)\nبقول طبری تصغیر ہے السحیمی۔ ابن اسکن فرماتے ہیں: ان کی حدیث بہتر سند سے مروی ہے۔ امام احمد(2) اور ابن ابی شیبہ نے بطریق اسرائیل بواسطہ ابو اسحاق، شعبی سے بحوالہ رعیہ کی روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کی طرف چہرے کے ٹکڑے پر خط بھیجا جسے انہوں نے اپنے ڈول پر پیوند بنا کر لگا لیا۔ تو نبی صلی اللہ علیہ وسلم نے ان کی طرف ایک لشکر روانہ کیا، جس نے ان کا ایک مویشی بھی نہ چھوڑا۔ ایسی حدیث ہے۔ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس مسلمان ہو کر آ گئے۔ آپ نے ان کے اہل و عیال کو تو واپس کر دیا اور مال کے بارے میں فرمایا: تمہارا مال تقسیم ہو چکا ہے۔ ان کے بارے میں جو دوم واقع ہوا ہے وہ خفیفہ کے حالات میں بیان ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۸۰) استیعاب (۸۰۲) تجرید (۱۸۳/۱)\n(2) مسند احمد (۲۸۵/۵)"}],[2655,"§۲۶۶۲ ۔ رفاعہ بن اوس(1)\nبن غفرہ بن عبد اللہ انصاری۔ ابو الاسود نے بحوالہ عمرہ ان کا تذکرہ شرکاء احد میں کیا ہے۔ طبرانی(2) اور ان کے متبعین نے انہی کے طریق سے ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۸۱)\n(2) المعجم الکبیر (حدیث: ۴۵۶۱)"}],[2656,"§۲۶۶۳ ۔ رفاعہ بن تابوت انصاری(1)\nایک مرسل حدیث میں ان کا ذکر آتا ہے جسے عبد بن حمید نے اپنی تفسیر میں نقل کیا ہے جو بطریق قیس بن جبیر نہشلی سے مروی ہے کہ لوگ جب احرام باندھتے تھے تو گھر میں دروازے کے بجائے پچھواڑے سے آتے تھے۔ جبکہ جس اس کے برخلاف کرتے تھے۔ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم کسی باغ میں داخل ہوئے اور پھر اسی کے دروازے سے باہر تشریف لے گئے تو رفاعہ نامی شخص آپ کے پیچھے ہو لیے۔ حالانکہ وہ جس میں سے نہ تھے۔ لوگوں نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! رفاعہ منافق ہو گیا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے ایسا کیوں کیا۔ انہوں نے عرض کی: میں نے آپ صلی اللہ علیہ وسلم کی پیروی کی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ہم تو جس میں سے ہیں۔ ہمارا دین تو ایک ہے۔ جس پر یہ آیت نازل ہوئی: “نیکی نہیں کہ تم گھروں میں ان کے پچھواڑے سے آؤ”۔(2)(3) صحیح میں اس کا شاہد موجود ہے جو حدیث براء سے مروی ہے۔ لیکن ان کا نام نہیں لیا۔ اسی سے ملتا جلتا قصہ عطیہ بن عامر کے حوالہ سے بھی پیش آیا ہے۔ ہو سکتا ہے دونوں کے ساتھ یہ واقعہ پیش آیا ہو۔ رہی وہ حدیث جو مسلم(4) میں حدیث جابر رضی اللہ عنہ سے منقول ہے کہ بہت تیز ہوا چلی تو نبی صلی اللہ علیہ وسلم نے فرمایا: “یہ ہوا بہت بڑے منافق کی موت کی وجہ سے چلی ہے”۔ اور وہ شخص رفاعہ بن تابوت تھا سو وہ ان کے علاوہ کوئی اور شخص تھا، وہ دوسری سند سے یہ نام رافع بن ثابت بھی منقول ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۱۶۸۲)\n(2) سورۃ البقرۃ (۱۸۹)\n(3) تفسیر طبری (۱۰۹/۲) الدر المنثور (۲۰۴/۱)\n(4) مسلم کتاب صفات المنافقین (۲۶۹۷۲)"}],[2657,"§۲۶۶۴ ۔ رفاعہ بن حارث(1)\nبن رفاعہ انصاری۔ یہی رفاعہ بن عمرو ہے ہیں۔ ابن اسحاق نے بدر میں انہیں ان کا ذکر کیا ہے جبکہ امام واقدی وغیرہ نے اس بات کا انکار کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۸۴) استیعاب (۷۷۵)"}],[2658,"§۲۶۶۵ ۔ رفاعہ بن رافع انصاری(1)\nمعاذ بن عفراء کے بھتیجے۔ ان سے ان کے بیٹے معاذ روایت کرتے ہیں، ان کی حدیث زید بن حباب کے ہاں ہشام بن ہارون سے بواسطہ معاذ بن رفاعہ۔ بحوالہ ان کے مروی ہے۔ ایسا ہی ابن مندہ نے اور ان کے اتباع میں ابو نعیم نے لکھا ہے دونوں نے ان کے حالات میں ایک حدیث بروایت رفاعہ بن مالک الزرقی نقل کی ہے۔ اور ترمذی کے سیاق میں ابن رفاعہ بن رافع بن عفراء لکھا ہے شاید رافع کی والدہ یا دادی کا نام عفراء تھا، میں نے زید بن حباب کی حدیث بہت تلاش کی لیکن مجھے معلوم نہ ہو سکا اسے کس نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۸۵)"}],[2659,"§۲۶۶۶ ۔ رفاعہ بن رافع(1)\nبن مالک بن العجلان بن عمرو بن عامر بن زریق انصاری خزرجی زراقی۔ ابو معاذ، ان کی والدہ ام مالک بنت ابی بن سلول مشہور ہیں۔ امام بخاری(2) وغیرہ نے ان کی حدیث نقل کی ہے یہ بدری صحابی ہیں جیسا کہ اس کا ثبوت صحیح بخاری میں ہے وہ اور ان کے والد بیعت عقبہ میں اور بقیہ معرکوں میں شریک رہے۔ نبی صلی اللہ علیہ وسلم اور ابو بکر صدیق رضی اللہ عنہ اور عبادہ بن الصامت رضی اللہ عنہ سے روایت کرتے ہیں۔ ان سے ان کے دونوں بیٹے عبید اور معاذ، ان کے بھتیجے بن خلا، اور بھتیجے کے بیٹے علی بن یحییٰ بن یحییٰ روایت کرتے ہیں۔ ضرار بن صرد عبد اللہ بن ابو رافع تک کی اپنی اسناد سے یہ سمجھتے ہیں کہ یہ جنگ صفین میں شریک تھے۔ اس روایت کو طبرانی نے لکھا ہے۔ ابو عمر(3) نے ایک قصہ نقل کیا ہے جس میں ہے کہ یہ جنگ جمل میں شریک تھے۔ بقول ابن قانع: ان کی وفات ۴۱ھ یا ۴۲ھ میں ہوئی۔","",{"fn":"(1) اسد الغابہ (۱۶۸۶) استیعاب (۷۷۶) تجرید (۱۸۴/۱)\n(2) بخاری کتاب المغازی باب شہود الملائکۃ بدراً (۳۹۹۴، ۳۹۹۲)\n(3) استیعاب (۷۷/۲)"}],[2660,"§۲۶۶۷ ۔ رفاعہ بن زنبر\nبروزن جعفر۔ ابن ماکولا(1) نے ان کا ذکر کیا کہ انہیں شرف صحابیت حاصل ہے۔ ابن الاثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔ میرے خیال میں یہ رفاعہ بن عبد اللہ بن زنبر ہیں جن کا تذکرہ ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۸۷)"}],[2661,"§۲۶۶۸ ۔ رفاعہ بن زید(1)\nبن عامر بن سواد بن کعب۔ جو ظفر بن خزرج بن عمرو بن مالک بن اوس انصاری ظفری ہیں۔ قتادہ بن نعمان کے چچا ہیں۔ ترمذی(2) اور طبری میں بطریق حاصم بن عمر بن قتادہ بواسطہ اپنے والد بحوالہ اپنے دادا قتادہ بن نعمان روایت کرتے ہیں: ہم میں سے ایک کمر ان تھا جو جو امیر تک کہلاتا تھے۔ میرے چچا رفاعہ بن زید نے امید کے کاندھا ایک اونٹ خریدا جو انہوں نے اپنے ایک کمرہ میں رکھ دیا جس پر رات کے وقت ڈاکہ پڑا پھر وہ بھی حدیث ذکر کی جس میں اللہ تعالیٰ کا یہ ارشاد نازل ہونے کا واقعہ ہے: “اے نبی! خیانت کرنے والوں کی طرف سے جھگڑنے والا نہ بنو”۔ اسی کے آخر میں ہے، قتادہ نے کہا: میں اپنے چچا کے پاس ان کے ہتھیار لے کر آیا وہ جاہلیت میں ہی رتو ندہ کی بیماری کا شکار تھے، میں سمجھتا تھا کہ ان کے دل میں اسلام کی قدر و منزلت ہے۔ فرماتے ہیں: “جب میں وہ ان کے پاس لے کر آیا، مجھ سے کہنے لگے: کہنے لگے: یہ اللہ کی راہ میں صدقہ ہے۔ سو مجھے علم ہو گیا کہ اس کا اسلام صحیح ہے”۔ ترمذی فرماتے ہیں: غریب روایت ہے، جس میں محمد بن سلمہ موصول بیان کرنے میں منفرد ہیں۔ ان کے علاوہ لوگوں نے اسے مرسل روایت کیا ہے۔ جبکہ امام واقدی نے کئی طرق سے بحوالہ محمود بن لبید ان کی سے اور قصہ گو لکھا پنڈھا کے طویل ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۸۸) استیعاب (۷۷۷)\n(2) ترمذی کتاب تفسیر القرآن باب سورۃ النساء (۳۰۶۳) سورۃ النساء (۱۰۵)"}],[2662,"§۲۶۶۹ ۔ رفاعہ بن زید(1)\nبن وہب انجدی۔ ابن اسحاق مغاز میں فرماتے ہیں: وہ خیبر سے پہلے صلح حدیبیہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ رفاعہ بن زید انجدی ایخ نبی صلی اللہ علیہ وسلم۔ اسلام لے آئے اور خوب اسلام لایا۔ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ایک غلام کا ہدیہ بھی پیش کیا۔ ابن مندہ بطریق حیدر بن روان روایت کرتے ہیں کہ رفاعہ بن زید اپنی قوم(2) کے دس آدمیوں سمیت آئے تھے۔ (حدیث) سحیحین میں حدیث ابو ہریرہ رضی اللہ عنہ سے خبر کے واقعہ میں مروی ہے کہ رفاعہ بن زید نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بدم نامی سیاہ فام ایک غلام ہدیہ پیش کیا پھر مالی غنیمت میں خیانت کا قصہ ذکر کیا۔ خلیفہ بن امیہ کے حالات میں ان کا تذکرہ ہوا ہے اور معبد انجدی کے حالات میں بھی ان کا ذکر ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۸۹) استیعاب (۷۷۸)\n(2) المعجم الکبیر (۴۵۶۲)"}],[2663,"§۲۶۷۰ ۔ رفاعہ بن سہل\nنودی کی شرح مسلم میں لکھا ہے کہ یہ ان میں سے ایک ہیں جن کے نام کے متعلق کہا گیا ہے کہ انہوں نے ایک صاحب کھجور صدقہ میں دیں تو منافقین ان کی طرف اشارہ کرنے لگے۔ وہ ابو عقیل ہیں کنیت سے شہرت پائی ہے، کتبوں میں تذکرہ ہوتا ہے۔"],[2664,"§۲۶۷۱ ۔ رفاعہ بن سموال القرظی(1)\nصحیح میں حدیث عائشہ رضی اللہ عنہا سے ان کا ذکر ملتا ہے۔ فرماتی ہیں: رفاعہ کی بیوی نبی صلی اللہ علیہ وسلم کے پاس آئی، کہنے لگی: اللہ کے رسول! مجھے رفاعہ نے طلاق دے دی ہے۔ تو آپ صلی اللہ علیہ وسلم نے میری طلاق کو نافذ قرار دیا۔ (حدیث)(2) امام مالک رضی اللہ عنہ نے سورۃ بن رفاعہ سے بحوالہ زبیر بن عبد الرحمن بن زبیر روایت کی ہے کہ رفاعہ بن سموال نے اپنی ابلیہ تمیمہ بنت وہب کو طلاق دی، پھر حدیث ذکر کی۔ موطا کے سب راویوں کے نزدیک یہ روایت مرسل ہے۔ جبکہ ابن وہب، ابراہیم بن طہمان، ابو بکر بن عیاش، شیبہ نے امام مالک سے موصولا روایت کی ہے۔ فرماتے ہیں: زبیر بن عبد الرحمن بن الزبیر سے بواسطہ ان کے والد مروی ہے، زبیر جو جد اعلیٰ ہیں ان کا نام زا کے زبرے سے اور چھوٹے کاف کا نام تصغیر ہے۔ ابن شاہین نے تفسیر ابن مقاتل بن حیان کے طریق سے ارشاد باری تعالیٰ: “پس اگر خاوند اس (عورت) کو طلاق دے دے تو پھر یہ عورت اس کے لیے حلال نہیں یہاں تک کہ اس کے علاوہ کسی اور خاوند سے نکاح کر لے”۔(3) پھر وہ طلاق دے دے تو پہلے کے لیے حلال ہے۔) میں فرماتے ہیں: عائشہ بنت عبد الرحمن بن عتیق ابن عفر کی کے بارے میں نازل ہوئی جو رفاعہ بن وہب بن عتیق کے نکاح میں تھیں۔ جو ان کے چچا زاد تھے۔ انہوں نے انہیں طلاق باقی باتیں دی، بعد میں انہوں نے عبد الرحمن بن زبیر سے شادی کر لی تھی پھر لمبا قصہ ذکر کیا۔ ابو موسیٰ فرماتے ہیں: بظاہر واقعہ ایک ہے۔ میں کہتا ہوں: دونوں سیاقوں کا ظاہر بتاتا ہے کہ دو واقعے ہیں، لیکن مشکل دوسرے خاوند عبد الرحمن بن زبیر کے نام کا اتحاد ہے (یعنی دونوں کا نام عبد الرحمن تھا)۔ رہی خاتون تو ان کے نام میں کافی سارا اختلاف ہے جیسا کہ خواتین کے حصہ میں بیان ہوگا۔","",{"fn":"(1) اسد الغابہ (۱۶۹۰) استیعاب (۷۷۹) تجرید (۱۸۴/۱)\n(2) بخاری کتاب الشہادات (۲۶۳۹) مسلم کتاب النکاح (۳۵۱۲) ترمذی کتاب النکاح (۱۱۸) ابن ماجہ کتاب النکاح (۱۹۳۲)\n(3) سورۃ البقرۃ (۲۳۰)"}],[2665,"§۲۶۷۲ ۔ رفاعہ بن عبد المنذر(1)\nبن رفاعہ بن زنبر بن زید بن امیہ انصاری اوسی۔ ابو لبابہ کے بھائی۔ ابو الاسود نے بحوالہ عروہ اہل عقبہ میں جبکہ موسیٰ بن عقبہ اور ان ابن اسحاق نے اہل بدر میں ذکر کیا ہے۔ ابن کلبی فرماتے ہیں: یہ ابو لبابہ اور مبشر کے بھائی ہیں۔ تینوں بدر(2) کے لیے نکلے۔ مبشر نے شہادت پائی اور نبی صلی اللہ علیہ وسلم نے ابو لبابہ کو واپس کر دیا جبکہ رفاعہ اصل میں شریک ہوئے۔ فرماتے ہیں: یہ بیعت عقبہ میں شریک تھے اور خبیر میں شہید ہوئے۔ عدی نے اس پر اعتماد ظاہر کیا ہے کہ ابو لبابہ کا نام مبشر تھا اسی کو رشاطی نے راجح قرار دیا ہے۔ البتہ ابن اسکن لکھتے ہیں: ابن نمیر، امام احمد بن حنبل اور علی بن المدینی نے ذکر کیا ہے کہ ابو لبابہ کا نام رفاعہ تھا۔ ابن اسحاق فرماتے ہیں: رفاعہ، ابو لبابہ کے بھائی ہیں۔","",{"fn":"(1) اسد الغابہ (۱۶۹۲) استیعاب (۷۸۰) تجرید (۱۸۴/۱)\n(2) المعجم الکبیر (۴۴۹۷/۵)"}],[2666,"§۲۶۷۳ ۔ رفاعہ بن عبد المنذر\nابو لبابہ کا ایک نام، کتبوں میں بیان ہوتا ہے۔"],[2667,"§۲۶۷۴ ۔ رفاعہ بن عرابہ(1)\nبقول بعض: عروہ انجدی المدنی۔ ترمذی فرماتے ہیں: عرادہ وہم ہے، ابن حبان لکھتے ہیں: عرادہ ان کے دادا ہیں جس نے انہیں عرادہ کہا تو دادا کی نسبت سے کہہ دیا۔ امام مسلم کا بیان ہے کہ عطاء بن یسار ان سے روایت کرنے میں منفرد ہیں۔ ان کی حدیث نسائی(2) میں صحیح سند سے ملتی ہے، ابن ابی حاتم کا بیان ہے، اور ابن مندہ نے بھی ان کا احتجاج کیا ہے کہ ان کی کنیت ابو نزامہ تھی، لگتا ہے یہ دوم ہے یہ تو بعد والے شخص کی کنیت ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۹۳) استیعاب (۷۸۲) تجرید (۱۸۴/۱)\n(2) عمل الیوم واللیلۃ للنسائی (۴۷۵)"}],[2668,"§۲۶۷۵ ۔ رفاعہ بن عرادہ العذری (دوسرے)\nخلیفہ بن خیاط نے صحابہ میں ان کا تذکرہ کیا ہے۔ ابو حاتم فرماتے ہیں: ابو نزامہ بنی حارث بن سعد بن ہم کے ایک فرد ہیں۔ بقول بعض ان کا نام رفاعہ بن عرادہ ہے، ان سے ان کے بیٹے روایت کرتے ہیں، یہ بات عسکری نے نقل کی ہے۔"],[2669,"§۲۶۷۶ ۔ رفاعہ بن عمرو(1)\nبن زید بن عمرو بن ثعلبہ بن مالک بن سالم خزرجی سامی ابو الولید۔(2) ابن اسحاق وغیرہ نے اہل بدر میں ان کا ذکر کیا ہے۔ ابو الاسود کی، بحوالہ عروہ روایت میں: رفاعہ بن عمرو بن قیس لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۹۵) استیعاب (۷۸۱)\n(2) السیرۃ النبویہ (۹۸/۳)"}],[2670,"§۲۶۷۷ ۔ رفاعہ بن عمرو الجہنی(1)\nابو محشر نے بدر میں ان کا تذکرہ کیا ہے کہ یہ احد میں شریک ہوئے۔(2) ابو عمر فرماتے ہیں: درست وہ ربیعہ بن عمرو ہے، اپنی جگہ بیان ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۹۶) استیعاب (۷۸۳)\n(2) استیعاب (۸۰/۲)"}],[2671,"§۲۶۷۸ ۔ رفاعہ بن عمرو\nبن نوفل بن عبد اللہ بن نان انصاری۔ موسیٰ بن عقبہ نے شرکاء بدر میں اور شہداء احد میں جبکہ ابن اسحاق کے ہاں ہے کہ شرکاء احد میں رفاعہ بن عمرو وازنی بھی ہیں۔"],[2672,"§۲۶۷۹ ۔ رفاعہ بن قرظہ القرظی(1)\nبقول ابو حاتم(2) انہیں دیدار حاصل ہے۔ باوردی اور طبرانی(3) نے بطریق عمر بن دینار، یحییٰ بن جعدہ بن روایت کی ہے کہ رفاعہ بن قرظہ نے فرمایا یہ آیت جن دس افراد کے بارے میں نازل ہوئی، ان میں سے ایک میں ہوں: “اور نصیحت کی بات ہم مسلسل انہیں پہنچا چکے ہیں تاکہ وہ نصیحت حاصل کریں”۔(4) (حدیث) بغوی نے بھی ان کا ذکر کیا ہے لیکن ان کے ہاں رفاعہ انجدی لکھا ہے اور فرماتے ہیں: مجھے اس کے علاوہ کوئی حدیث معلوم نہیں۔ بقول بعض: یہ رفاعہ بن سموال ہیں، اسی پر ابن مندہ نے احتمال کیا ہے۔ البتہ باوردی اور ابن اسکن کا قول ہے کہ وہ قرظہ کے قیدیوں میں سے تھے، وہ اور عطیہ بچوں میں شامل تھے اس بنا پر یہ ابن سموال کے علاوہ ہوئے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۱۶۹۶) تجرید (۱۸۵/۱)\n(2) الجرح والتعدیل (۴۹۷/۳)\n(3) المعجم الکبیر (۴۵۶۲)\n(4) سورۃ القصص (۵۱)"}],[2673,"§۲۶۸۰ ۔ رفاعہ بن مبشر(1)\nبن حارث انصاری ظفری۔ احد میں اپنے والد کے ہمراہ شریک ہوئے۔ ابو عمر(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۹۷) استیعاب (۷۸۴)\n(2) استیعاب (۸۰/۲)"}],[2674,"§۲۶۸۱ ۔ رفاعہ بن مسروح(1)\nیا ابن مشمرخ الاسدی، اسد بن خزیمہ، بنی عبد شمس کے حلیف۔ ابن اسحاق نے شہداء خیبر میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۹۸) استیعاب (۷۸۵)"}],[2675,"§۲۶۸۲ ۔ رفاعہ بن نعمان الدارانی\nطیب بن عبداللہ میں ان کا تذکرہ ہوتا ہے۔ بقول امام واقدی: یہی فاکہ بن نعمان ہیں۔"],[2676,"§۲۶۸۳ ۔ رفاعہ بن وقش(1)\nابن زغبہ بن زعوراء بن عبد الاشہل الاشہلی۔ ابن اسحاق(2) نے شہداء اُحد میں ان کا ذکر کیا ہے۔ یہ ثابت کے بھائی اور سلمہ بن سلامہ اور ان کے بھائی کے چچا ہیں۔ خالد بن ولید جو ابھی مشرف با اسلام نہیں ہوئے تھے ان کے ہاتھوں شہید ہوئے۔ بعض اہل مغازی کا بیان ہے کہ یہ ٹیلوں پر عورتوں کے ساتھ اور ان کے ساتھ حسل بن جابر مامور تھے۔ مشہور یہ ہے کہ اس کا اتفاق ان کے بھائی ثابت کو ہوا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۱۶۹۹) استیعاب (۷۸۶)\n(2) السیرۃ النبویہ (۹۶/۳)"}],[2677,"§۲۶۸۴ ۔ رفاعہ بن وہب القرظی\nرفاعہ بن سموال میں ذکر ہوا ہے۔"],[2678,"§۲۶۸۵ ۔ رفاعہ بن یثربی\nبقول بعض: یہ ابو رمثہ کا نام ہے۔ ایک قول ہے: ان کا نام میثربی بن عوف ہے، تذکرہ ہونا ہے۔"],[2679,"§۲۶۸۶ ۔ رفاعہ الانصاری\nعبایہ بن رافع بن خدیج کے دادا۔ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں فوت ہوئے۔ عبایہ کے نسب نامہ میں سوائے ان کے والد کے کوئی ایسا نہیں جس کا نام رفاعہ ہو۔ صحابی نہیں ہیں۔ نبی صلی اللہ علیہ وسلم کے بعد عرصہ دراز زندہ رہے، ہو سکتا ہے یہ ان کے نانا وغیرہ ہوں۔ خاء میں خدیج کے تحت ان کا تذکرہ ہوا ہے۔"],[2680,"§۲۶۸۷ ۔ رفاعہ (بے نسبت)(1)\nابن مندہ بطریق وازع بن نافع بواسطہ ابو سلمہ، رفاعہ سے روایت کرتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ میں لوگوں میں گھوم پھر کر یہ اعلان کروں: “کوئی بھی کھجور کے خول میں ہرگز نبیذ نہ بنائے۔”(2) اس کی سند ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۰۳)\n(2) جامع المسانید (۲۹۳/۴) اسد الغابہ (۱۹۸/۲)"}],[2681,"§۲۶۸۸ ۔ رقاد بن ربیعہ العقیلی(1)\nبقول ابن حبان:(2) انہیں شرف صحابیت حاصل ہے۔ طبرانی(3) بطریق یعلی بن الاشدق بحوالہ رقاد بن ربیعہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم سے سو بکریوں میں سے ایک بکری (زکوۃ میں) وصول کی۔ (حدیث)","",{"fn":"(1) اسد الغابہ (۱۷۰۵) تجرید (۱۸۵/۱)\n(2) الثقات (۱۲۶/۳)\n(3) المعجم الکبیر (۴۶۲/۵)"}],[2682,"§۲۶۸۹ ۔ رقیبہ بن عقیبہ(1)\nیا عقیبہ بن رقیبہ۔ اسی طرح شک سے یہ نام منقول ہے۔ ان کی حدیث ابن مندہ اور خطیب نے “الجامع” میں بطریق مکی بن ابراہیم روایت کی ہے۔ البتہ خطیب فرماتے ہیں: حسن بن ہارون بن حسن سے مروی ہے جبکہ ابن مندہ کا قول ہے: مکی سے بحوالہ ہارون مروی ہے۔ واسطہ ذکر نہیں کیا۔ خطیب کی روایت میں رقیبہ بن عقیبہ یا عقیبہ بن رقیبہ سے مرفوع روایت ہے۔ اور ابن مندہ بواسطہ عبداللہ بن عمر، بحوالہ یزید بن حبیبہ روایت کرتے ہیں کہ رقیبہ آئے پھر مرفوع حدیث نقل کی “چاند نکلتے قیام کرنا سوموار یا جمعرات کے روز نکلنا”۔(2) (حدیث)","",{"fn":"(1) اسد الغابہ (۱۷۰۶) تجرید (۱۸۵/۱)\n(2) جامع المسانید (۲۹۵/۴)"}],[2683,"§۲۶۹۰ ۔ رقیم بن ثابت(1)\nبن ثعلبہ بن زید بن لوذان بن معاویہ انصاری۔ ابو ثابت انصاری، ابن مندہ نے ان کا یہی نسب بیان کیا ہے جبکہ ابن کلبی ثعلبہ کے بعد ابن اتکال بن حارث بن امیہ بن معاویہ بن مالک بن عوف انصاری اوسی کا اضافہ کرتے ہیں۔ ابوالاسود نے بحوالہ عروہ ان کا ذکر شہداء طائف میں کیا ہے۔ ایسا ہی موسیٰ بن عقبہ، ابن اسحاق اور ابن کلبی نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۰۷) استیعاب (۸۰۳)"}],[2684,"§۲۶۹۱ ۔ رکانہ بن عبد یزید(1)\nبن ہاشم بن المطلب بن عبد مناف المطلمی۔ بلاذری لکھتے ہیں: عباس بن ہشام نے مجھے بحوالہ اپنے والد انہوں نے ابن خربوز وغیرہ سے نقل کیا کہ رکانہ کسی سفر سے واپس آئے، نبی صلی اللہ علیہ وسلم کے متعلق انہیں بتایا گیا، مکہ کے کسی پہاڑ پر ان کی آپ سے ملاقات ہوئی۔ وہ کہنے لگے: بھتیجے! مجھے تمہارے بارے میں پتہ چلا ہے، سو اگر تم نے مجھے پچھاڑ لیا تو تم سچے، چنانچہ انہوں نے آپ سے مقابلہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں پچھاڑ دیا۔ رکانہ فتح مکہ کے موقعے پر مسلمان ہوئے۔ بقول بعض: پچھڑنے کے بعد اسلام لے آئے تھے۔ ابن حبان(2) لکھتے ہیں: ان کی کشتی والی روایت کی سند میں رد ہے۔ ان کا اشارہ اس کی طرف ہے جو حدیث ابوداؤد اور ترمذی نے بروایت ابوالحسن عسقلانی بواسطہ ابو جعفر بن محمد بن رکانہ بحوالہ ان کے والد نقل کی ہے کہ رکانہ نے نبی صلی اللہ علیہ وسلم سے کشتی کا مقابلہ کیا تو نبی علیہ السلام نے انہیں پچھاڑ دیا۔(3) (حدیث) ترمذی فرماتے ہیں: غریب ہے اور اس کی سند پائیدار نہیں۔ زبیر کا قول ہے: رکانہ بن عبد یزید جنہوں نے رسول اللہ صلی اللہ علیہ وسلم سے مکہ میں اسلام سے پہلے کشتی لڑی وہ سب لوگوں میں مضبوط تھے۔ کہنے لگے: محمد (صلی اللہ علیہ وسلم)! اگر آپ نے مجھے پچھاڑ لیا تو میں آپ پر ایمان لے آؤں گا۔ تو نبی صلی اللہ علیہ وسلم نے انہیں پچھاڑ دیا، تو وہ کہنے لگے: میں گواہی دیتا ہوں کہ آپ جادوگر ہیں۔ پھر بعد میں اسلام بھی لے آئے اور رسول اللہ صلی اللہ علیہ وسلم نے انہیں پچاس وسق کھجور کھانے کے لیے دیں۔ ترمذی(4) میں بطریق زبیر بن سعید بواسطہ عبداللہ بن یزید بن رکانہ بواسطہ ان کے والد بحوالہ ان کے دادا مروی ہے کہ میں نے عرض کی: اللہ کے رسول! میں نے اپنی بیوی کو طلاق دی ہے، آپ نے فرمایا: تمہارا کتنی طلاقوں کا ارادہ تھا؟ عرض کی: ایک۔ (حدیث) اس حدیث میں ابوداؤد وغیرہ سے آگے اختلاف ہے۔ ان سے نافع بن جبیر اور پوتے علی بن یزید بن رکانہ روایت کرتے ہیں۔ بقول زبیر: خلافت معاویہ کے دور میں مدینہ میں فوت ہوئے۔ اور ابو نعیم لکھتے ہیں: خلافت عثمانی میں وفات پائی۔ بقول بعض: ۴۱ھ تک زندہ رہے۔ ان کا تذکرہ ان کے بیٹے یزید کے حالات میں ہوگا۔","",{"fn":"(1) اسد الغابہ (۱۷۰۸) استیعاب (۸۰۴) تجرید (۱۸۶/۱)\n(2) الثقات (۱۳۰/۳)\n(3) ابوداؤد کتاب اللباس باب فی العمائم (۴۰۷۸) ترمذی کتاب اللباس باب العمائم علی القلانس (۱۷۸۴)\n(4) ترمذی کتاب الطلاق واللعان باب ما جاء فی الرجل یطلق امرأته البتۃ (۱۱۷۷)"}],[2685,"§۲۶۹۲ ۔ رکب المصری(1)\nبقول عباس دوری: انہیں شرف صحابیت حاصل ہے۔(2) ابو عمر کہتے ہیں: یہ کندی ہیں، ان کی ایک حسن حدیث ہے جس میں آداب کا ذکر ہے۔ یہ صحابہ میں مشہور شخصیت کے مالک نہیں۔ البتہ مؤرخین کا صحابہ میں ان کا ذکر کرنے پر اتفاق ہے جسے ان سے روایت کرتے ہیں۔\nمیں کہتا ہوں: ان کی حدیث کی سند ضعیف ہے ابن عبدالبر کے “حسن” سے مراد حسن الفاظ ہے۔ امام بخاری(3) نے اپنی تاریخ میں نیز بغوی، باوردی، ابن شاہین اور طبرانی(4) وغیرہ نے ان کا ذکر کیا ہے۔ ابن مندہ فرماتے ہیں: ان کا صحابی ہونا مشہور نہیں۔ بغوی فرماتے ہیں: مجھے معلوم نہیں انہوں نے نبی صلی اللہ علیہ وسلم سے سماع کیا ہے یا نہیں۔ جبکہ ابن حبان لکھتے ہیں: بقول بعض: یہ صحابی ہیں، البتہ ان کی اسناد پر اعتماد نہیں کیا جا سکتا۔","",{"fn":"(1) اسد الغابہ (۱۷۱۰) استیعاب (۸۰۵) تجرید (۱۸۶/۱)\n(2) استیعاب (۸۷/۲)\n(3) التاریخ الکبیر (۳۳۸/۲)\n(4) المعجم الکبیر (۴۶۱۵، ۴۶۱۶)"}],[2686,"§۲۶۹۳ ۔ رہم العدوی\nاز آل عمر بن خطاب، وثیمہ نے کتاب “الردہ” میں ان کا ذکر کیا ہے اور زید بن الخطاب کی شہادت کے بارے ان کا مرثیہ نقل کیا جس میں وہ کہتے ہیں: “اے زید! زید بنی نفیل آپ نے ہمارے لیے غم و پریشانی کے بدلہ غم وراثت میں چھوڑا ہے۔” پھر وہ قصہ ذکر کیا جسے سیف نے “الفتوح” میں نقل کیا ہے۔ اس میں وہ لکھتے ہیں: رہم العدوی جو آل خطاب سے ہیں، انہوں نے فرمایا: ابن فتحون کی “ذیل” کے بعض نسخوں میں رہم بن رہم بن عمر بن خطاب لکھا ہے۔ درست رہم ابن عم عمر بن خطاب ہے۔ واللہ اعلم"],[2687,"§۲۶۹۴ ۔ رہین\nبقول بعض: زہیر۔ ان شاء اللہ تعالیٰ حرف زا میں ذکر ہوگا۔"],[2688,"§۲۶۹۵ ۔ روح بن سیار\nیا سیار بن روح۔ بقول ابن ابی حاتم(1) شامی ہیں۔ اور مجھے ان کے حالات کا پتہ نہیں۔ امام بخاری رحمہ اللہ فرماتے ہیں: انہیں شرف صحابیت حاصل ہے۔ کنیتوں میں ابو نجیب میں تذکرہ ہونا ہے۔","",{"fn":"(1) الجرح والتعدیل (۴۹۷/۳)"}],[2689,"§۲۶۹۶ ۔ روح (بے نسبت)\nابن الحذاء کا بیان ہے کہ یہ اس یتیم کا نام ہے جس کے بارے سیدنا انس رضی اللہ عنہ نے فرمایا: “پھر میں نے اور یتیم نے آپ کے پیچھے صف بنائی۔” مشہور یہ ہے کہ اس کا نام ضمیرہ تھا۔"],[2690,"§۲۶۹۷ ۔ رومان\n“شام میں رہتے تھے۔ نبی صلی اللہ علیہ وسلم سے روایت کی ہے۔” یہ بات ابو القاسم بغوی نے بحوالہ امام بخاری رحمہ اللہ نقل کی اور ان کی حدیث ذکر نہیں کی۔ میرے خیال میں یہ رومان بن بعجہ بن زید بن عمیرہ الجذامی ہیں۔ ابن شاہین نے بطریق یحیی بن سعید اموی، بواسطہ ابن اسحاق حمید بن رومان بن بعجہ بحوالہ ان کے والد ان کی حدیث نقل کی ہے کہ رفاعہ بن زید الجذامی نبی صلی اللہ علیہ وسلم کے پاس آئے آپ نے ان کے لیے ایک تحریر لکھوائی۔ پھر حدیث(1) ذکر کی۔ اسی روایت کو اسمعیل بن عیاش نے بواسطہ حمید بن رومان روایت کیا تو کہا: زیاد بن سعد بن رفاعہ بن زید بحوالہ اپنے والد روایت کرتے ہیں کہ رفاعہ بن زید وفد میں آئے پھر اس کا ذکر کیا۔","",{"fn":"(1) المعجم الکبیر (۴۵۶۲/۵) مجمع الزوائد (۳۱۰/۵) جامع المسانید (۳۰۰/۴)"}],[2691,"§۲۶۹۸ ۔ رومان الرومی(1)\nبقول بعض: یہ سفینہ کا نام ہے۔ ابو نعیم لکھتے ہیں: کسی متاخر کا گمان ہے کہ یہ بلخ کے قیدی ہیں جبکہ عہد نبوی میں بلخ فتح نہیں ہوا تو وہاں کے قیدی کیسے آسکتے ہیں؟","",{"fn":"(1) اسد الغابہ (۱۷۱۳) استیعاب (۸۰۶)"}],[2692,"§۲۶۹۹ ۔ روید (تصغیر ہے) الثقفی\nبنی عدی بن نوفل بن عبد مناف کے داماد۔ عمرو بن شبہ نے “اخبار مدینہ” میں لکھا ہے کہ بنی عدی کے دیگر لوگوں کی طرح مدینہ میں انہوں نے بھی حویلی بنائی۔ شراب نوشی میں سیدنا عمر رضی اللہ عنہ کے ساتھ پیش آمدہ ان کا ایک قصہ بھی ہے۔ موطا(1) میں بطریق سعید بن المسیب وغیرہ سے مروی ہے کہ طلیحہ ثقفیہ رشید ثقفی کے نکاح میں تھیں، جنہیں انہوں نے طلاق دے دی تو انہوں نے اپنی عدت میں ہی دوسرا نکاح کر لیا، جس پر سیدنا عمر رضی اللہ عنہ نے انہیں آہستہ سے کوڑا مارا۔ ہم نے ابراہیم بن سعید کے نسخہ میں لیث کے کاتب کی ان سے بحوالہ ان کے والد روایت نقل کی ہے کہ سیدنا عمر رضی اللہ عنہ نے روید کا گھر جلا دیا تھا۔ وہ شراب نوشوں کی دوکان بن گیا تھا، سعد بن ابراہیم بحوالہ اپنے والد نقل کرتے ہیں کہ مجھے اب بھی وہ گھر یوں جلتا دکھائی دے رہا ہے جیسے وہ دہکتا ہوا انگارہ ہو، ایسا ہی دولابی نے “الکنیٰ” میں بطریق عبد اللہ بن جعفر بن المسور بن مخرمہ بواسطہ سعد بن ابراہیم انہوں نے بحوالہ اپنے والد نقل کیا ہے کہ میں نے دیکھا سیدنا عمر رضی اللہ عنہ نے روید ثقفی کا گھر جلا دیا جو انگارہ یا کوئلہ ہو گیا تھا، وہ شراب کی دوکان تھی جس میں “دارو” بکتا تھا۔ ابن ابی ذویب نے سعد بن ابراہیم بن عبدالرحمن بن عوف سے اس روایت کا مفہوم نقل کیا ہے۔ میں نے انہیں صحابہ میں اس لیے ذکر کر دیا ہے کیونکہ جو عہد فاروقی میں اس عمر کا ہوگا وہ زمانہ نبوی میں یقیناً ممتاز ہو گا۔ قریش اور ثقیف میں سے جو بھی بچا وہ اسلام لا کر حجۃ الوداع میں نبی صلی اللہ علیہ وسلم کے ساتھ شریک ہوا ہے۔","",{"fn":"(1) موطا مالک کتاب النکاح باب جامع ما لا یجوز من النکاح (۱۱۶۰)"}],[2693,"§۲۷۰۰ ۔ رویفع بن ثابت البلوی\nطبری نے وفد بلی میں ان کا ذکر کیا کہ یہ لوگ آپ کے پاس ۹ھ میں آئے۔ یہ رویفع بن ثابت انصاری کے علاوہ ہیں۔ یہ ابن فتحون کا قول ہے۔\nمیں کہتا ہوں: کنیتوں میں حرف ضاد میں ابو الضبیب کے حالات میں ان کے قصہ میں بیان ہوگا۔"],[2694,"§۲۷۰۱ ۔ رویفع بن ثابت(1)\nبن السکن بن عدی بن حارثہ از بنی مالک بن النجار، مصر فروکش ہوئے اور امیر معاویہ رضی اللہ عنہ نے انہیں طرابلس کا گورنر مقرر کیا۔ یہ ۴۶ھ کی بات ہے، پھر انہوں نے افریقاء پر حملہ کیا۔ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں اور ان سے بشر بن عبید اللہ الحضرمی، حنش الصنعانی اور ابو الخیر وغیرہ حضرات روایت کرتے ہیں۔ ابن البرقی کا قول ہے کہ برقہ میں جہاں کے یہ گورنر تھے فوت ہوئے۔ اور ابن یونس لکھتے ہیں: ۵۶ھ میں جبکہ یہ مسلمہ بن مخلد کی جانب سے وہاں کے امیر تھے، فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۷۱۷) استیعاب (۷۹۰)"}],[2695,"§۲۷۰۲ ۔ رویفع مولاہ نبی(1)\nابو احمد العسکری نے موالی النبی صلی اللہ علیہ وسلم میں ان کا ذکر کیا ہے۔ مفضل غلابی بحوالہ مصعب زبیری ان کا ذکر کرتے ہیں، اور ابن ابی خیثمہ کا قول ہے کہ ابن رویفع حضرت عمر بن عبد العزیز رضی اللہ عنہ کے پاس آئے آپ نے ان کے لیے حصہ مقرر کیا۔ ان کی نرینہ اولاد نہیں۔ یہ بات ابن عساکر نے نقل کی ہے، اور فرماتے ہیں: مجھے معلوم نہیں کہ ان کے علاوہ کسی نے ان کا ذکر کیا ہو۔ ابو عمر(2) لکھتے ہیں: مجھے ان کی روایت کا علم نہیں۔","",{"fn":"(1) اسد الغابہ (۱۷۱۸) استیعاب (۷۹۱)\n(2) استیعاب (۸۳/۲)"}],[2696,"§۲۷۰۳ ۔ رئاب بن حنیف(1)\nبن رئاب بن حارث بن امیہ بن زید انصاری۔ عدوی نے نسب اوس میں ان کا ذکر کیا ہے کہ بدر میں شریک ہوئے اور بئر معونہ کے روز شہادت پائی۔ ابو علی غسانی وغیرہ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۲۰)"}],[2697,"§۲۷۰۴ ۔ رئاب بن عمرو\nبن عوف بن کعب اللیثی۔ ابن السکن نے ان کا ذکر کیا ہے کہ ان کی حدیث ان کی اولاد میں سے کسی سے مروی ہے جسے نصر بن قدید لیثی نے مسلم بن حجاج بن مسلم سے انہوں نے بواسطہ اپنے والد بحوالہ اپنے دادا انہوں نے رئاب سے نقل کی ہے کہ وہ بیعت رضوان میں نبی صلی اللہ علیہ وسلم کے ساتھ تھے۔"],[2698,"§۲۷۰۵ ۔ رئاب بن مہشم(1)\nبن سعید (تصغیر ہے) ابن سہم قرشی سہمی۔ ابو علی الجیانی لکھتے ہیں: عمرو بن شعیب عن ابیہ عن جدہ کی حدیث میں ان کا ذکر آتا ہے۔\nمیں کہتا ہوں: ان کا اشارہ اس روایت کی طرف ہے جو دار قطنی نے نقل کی ہے جیسا کہ وائل بن رئاب کے حالات میں تذکرہ ہونا ہے اور معمر بن رباب کا ذکر ہوگا۔","",{"fn":"(1) اسد الغابہ (۱۷۲۱)"}],[2699,"§۲۷۰۶ ۔ ریاح بن حارث التمیمی\nالمجاشعی۔ ابن سعد نے بنی تمیم کے وفد میں اور ان کا اتباع کرتے ہوئے طبری نے ان کا ذکر کیا ہے جس کی تفصیل عطارد بن حاجب کے حالات میں بیان ہوگی۔"],[2700,"§۲۷۰۷ ۔ ریاح بن ربیع\nابن ابی حاتم(1) اور دارقطنی نے یاء میں ان کا ذکر کیا ہے، اکثر کا اس پر اتفاق ہے کہ یہ نام باء سے رباح ہے، پہلے تذکرہ ہو چکا ہے۔","",{"fn":"(1) الجرح والتعدیل (۵۱۱/۲)"}],[2701,"§۲۷۰۸ ۔ ریبال الثقفی\nمجھے ان کا ذکر ماسوائے حافظ صلاح الدین العلائی کی کتاب “اوشی المعلم” سے کہیں اور نہیں ملا۔ چنانچہ وہ بطریق ثوری، عمران ثقفی سے بواسطہ ان کے والد وہ اپنے دادا سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ان کے ہاتھ میں سونے کی انگوٹھی دیکھ کر فرمایا: “اسے چھوڑ دو۔” انہوں نے کہا: نہیں۔ (حدیث) علائی فرماتے ہیں: عمران ثقفی وہی ابن مسلم بن ریاح ثقہ راوی ہیں، رہے ان کے والد تو مجھے ان کا حال معلوم نہیں۔\nمیں کہتا ہوں: میں جانتا ہوں کہ انہیں یہ غلطی کہاں سے پیش آئی؟ میرے خیال میں انہوں نے سفیان ثوری کے حالات کی مراجعت کی اور ان کے شیوخ میں عمران نامی صرف یہی نظر آئے۔ لیکن طبرانی کا انداز اس کی تردید کرتا ہے، کیونکہ انہوں نے یہ حدیث یعلی بن مرہ ثقفی کے سوانح میں نقل کی ہے، یوں عمران ان کے نزدیک یعلی کے پوتے ہوئے۔ جس کی تائید اس سے بھی ہوتی ہے کہ ولید بن مسلم نے اس روایت کو ثوری سے بحوالہ ابو یعلی اور انہوں نے اپنے والد سے پھر اس کا مفہوم نقل کیا ہے۔"],[2702,"§۲۷۰۹ ۔ ریبال بن عمرو\nسیف نے “الفتوح” میں ان کا ذکر کیا اور اس میں ان کے مشہور مقالات کا بھی تذکرہ کیا ہے۔ طبرانی کا بیان ہے کہ وہ قادسیہ میں سیدنا سعد بن ابی وقاص کے امراء میں سے تھے، ہم بارہا یہ بیان کر چکے ہیں کہ اس دور میں صحابہ ہی امیر مقرر ہوتے تھے۔"],[2703,"§۲۷۱۰ ۔ رافع بن ابی رافع\nمولا نبی صلی اللہ علیہ وسلم، باوردی نے صحابہ میں ان کا ذکر کیا ہے لیکن ان کے صحابی ہونے کی کوئی دلیل ذکر نہیں کی۔"],[2704,"§۲۷۱۱ ۔ ربیعہ بن شرحبیل(1)\nابن حسنہ، انہیں دیدار نصیب ہوا۔ ان کے والد کا تذکرہ ہوتا ہے۔ ابن یونس لکھتے ہیں: فتح مصر(2) میں شریک تھے۔ بقول بعض: سیدنا عمرو بن العاص رضی اللہ عنہ ان کے سپرد کوئی کام کر دیتے تھے۔ ان سے ان کا بیٹا جعفر اور مولا بیناق روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۱۶۴۶)\n(2) التاریخ الکبیر (۲۹۰/۱)"}],[2705,"§۲۷۱۲ ۔ ربیعہ بن شرحبیل\nابن حسنہ محمد بن سلیمان جیزی نے مصر داخل ہونے والے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ اور فتح مصر کے شرکاء میں سے ہیں۔ لڑکپن میں نبی صلی اللہ علیہ وسلم کا دور پایا ہے، ان کے بھائی عبد الرحمن بن شرحبیل نے بھی یہ مبارک دور دیکھا ہے۔"],[2706,"§۲۷۱۳ ۔ ربیعہ بن عبد اللہ(1)\nبن الھدیر (تصغیر ہے) ابن عبدالعزیٰ بن عامر بن حارث بن حارثہ بن سعد بن تمیم بن مرہ تیمی۔ نبی صلی اللہ علیہ وسلم کی حیات میں پیدا ہوئے، ابو بکر صدیق رضی اللہ عنہ اور عمر رضی اللہ عنہ سے روایت کرتے ہیں۔ اکابر تابعین میں شمار ہوتے ہیں۔ یہ تو ابو عمر کا قول تھا۔ بعض نے عبداللہ اور ہدیہ کے درمیان ایک اور ربیعہ کا اضافہ نقل کیا ہے۔ ابن سعد نے ان کا ذکر کیا کہ عہد نبوی میں پیدا ہوئے۔ ابن حبان(2) نے کہا ہے کہ یہ صحابی ہیں، پھر ثقات تابعین میں ان کا ذکر کیا ہے۔ صحیح بخاری میں ہے ان کا سیدنا عمر رضی اللہ عنہ کے ساتھ ایک قصہ رونما ہوا ہے۔ دار قطنی فرماتے ہیں: بڑے تابعی ہیں جن کی سند تھوڑی ہے، عجلی کا قول ہے: ثقہ ہیں، اکابر تابعین میں سے ہیں۔ ابو بکر بن ابی ملیکہ کا قول ہے، سب سے بہتر انسان تھے۔ ابن ابی عاصم لکھتے ہیں: ۹۳ھ میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۶۵۰) استیعاب (۷۶۲)\n(2) الثقات (۱۲۹/۳)"}],[2707,"§۲۷۱۴ ۔ ربیعہ بن نوفل\nبن حارث بن عبد المطلب دار قطنی نے “الاخوۃ” نامی کتاب میں ان کا ذکر کیا کہ ان کی نرینہ اولاد نہ تھی۔ ان کے والد اور بھائی صحابہ ہیں۔ لہذا یہ بات بعید نہیں کہ انہیں دیدار نصیب ہوا ہو لیکن یہ ضروری نہیں، مثلاً محمد بن ابی بکر کے والد اور بھائی صحابہ ہیں لیکن انہیں رویت نصیب نہیں ہوئی۔"],[2708,"§۲۷۱۵ ۔ روح بن زنباع(1)\nبن روح بن سلامہ الجذامی ابو زرعہ۔ کسی نے صحابہ میں ان کا ذکر کیا ہے حالانکہ ان کا صحابی ہونا صحیح ثابت نہیں۔ البتہ اتنی گنجائش ہے کہ یہ عہد نبوی میں پیدا ہوئے ہوں، اس واسطے کہ ان کے والد کو شرف صحابیت اور رویت حاصل ہے جیسا کہ بیان ہوگا۔ امام مسلم کی کتاب الکنی میں لکھا ہے: یہ صحابی ہیں۔ ابو احمد الحاکم لکھتے ہیں: بقول بعض یہ صحابی ہیں، لیکن میں اسے صحیح نہیں سمجھتا۔ ابن مندہ فرماتے ہیں: دور نبوی پایا ہے۔ محمد بن ایوب نے صحابہ میں ان کا ذکر کیا ہے (لیکن) ان کا صحابی ہونا صحیح نہیں۔ ابو عروبہ اور حسین المقبانی لکھتے ہیں: بقول بعض یہ صحابی ہیں۔ ابو عمر(2) فرماتے ہیں: یہ قول ابو نعیم اور ابن مندہ کا ہے۔ ان کا صحابی ہونا صحیح نہیں ابن ابی خیثمہ کا قول ہے نبی صلی اللہ علیہ وسلم سے روایت کرنے والوں میں “روح بن زنباع” ہیں۔ ابو زرعہ دمشقی ہے اور ابن سمیع نے اہل شام کے دوسرے درجہ کے تابعین میں ان کا ذکر کیا ہے اور دونوں فرماتے ہیں: وہ فلسطین کے امیر تھے۔ ابن مندہ نے بطریق بکر بن سوادہ، بواسطہ عبیدہ بن عبدالرحمن، بحوالہ روح بن زنباع ان کی حدیث نقل کی ہے: “ایمان یمنی ہے اللہ تعالیٰ جذام میں برکت دے”۔(3)\nمیں کہتا ہوں: روح کے عبدالملک بن مروان وغیرہ کے ساتھ بڑے اچھے قصے ہیں۔ عبد الملک بن مروان کہتے تھے: روح نے اہل شام کی طاعت کی عبادت، اہل عراق کی عمدہ رائے اور اہل حجاز کی دینی سمجھ کے جامع ہیں۔ امام شافعی رحمہ اللہ سے مروی ہے کہ روح فرمایا کرتے تھے: میں نے خیر کا جو دروازہ بھی تلاش کیا وہ مجھے میسر ہو گیا اور نہ میں نے برائی کا کوئی دروازہ ڈھونڈا اور نہ مجھے اس کی سہولت ملی۔ ضمرہ بن ربیعہ بواسطہ ولید بن ابی عون روایت کرتے ہیں کہ روح جب حمام سے نکلتے تو ایک غلام آزاد کر دیتے۔ ان کی عبادہ بن الصامت سے اور ایک تمیم الداری رضی اللہ عنہ سے مروی حدیثیں ہیں۔ دونوں ابن عساکر نے ان کے حالات میں نقل کی ہیں۔ ابو سلیمان بن زبر کا قول ہے: ۸۴ھ میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۷۱۱) استیعاب (۷۸۸)\n(2) استیعاب (۸۱/۲)\n(3) تاریخ دمشق (۳۴۰/۸)"}],[2709,"§۲۷۱۶ ۔ راشد بن عبدالرحمن الازدی\nانہوں نے دور نبوی پایا اور جنگ یرموک میں شریک ہوئے۔ ابو عبیدہ بن الجراح رضی اللہ عنہ سے روایت کرتے ہیں۔ ابن عساکر نے ان کا ذکر کیا ہے۔"],[2710,"§۲۷۱۷ ۔ رافع الاشجعی\nبقول بعض: ابو الجعد کا نام ہے، سالم کے والد ہیں کنیتوں میں تذکرہ ہوتا ہے۔"],[2711,"§۲۷۱۸ ۔ رافع الاشجعی\nبقول بعض: ابو ہند کا نام ہے، ایک قول ہے ان کا نام نعمان ہے کنیتوں میں تذکرہ ہوتا ہے۔"],[2712,"§۲۷۱۹ ۔ رافع (بے نسبت)\nمیں نے فاکہی کی کتاب مکہ میں بطریق ابو بکر بن عبداللہ، بواسطہ عثمان بن عبید اللہ بن رافع وہ اپنے والد سے بحوالہ اپنے دادا روایت کرتے ہیں۔ انہوں نے قریش کے دو سفر کیے۔ فرماتے ہیں: مقام ابراہیم پر جو نشان ہے وہ اسمعیل علیہ السلام کی اہلیہ کا ہے۔ وہ ابراہیم علیہ السلام کے پاس مقام پر آئی آپ اس وقت سواری پر تھے۔ (حدیث)\nمیں کہتا ہوں: میرے خیال میں ابو رافع مشہور صحابی ہیں۔"],[2713,"§۲۷۲۰ ۔ رافع بن سالم\nبقول بعض: ابن سلیمان الفزاری، دور جاہلیت پایا ہے اور سیدنا عمر رضی اللہ عنہ سے سماع کیا۔ ان سے محمد بن ابراہیم تیمی روایت کرتے ہیں۔ امام بخاری(1) اور ابن ابی حاتم(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) التاریخ الکبیر (۳۰/۴/۱)\n(2) الجرح والتعدیل (۴۸۱/۳)"}],[2714,"§۲۷۲۱ ۔ رباب بن رمیلہ\nباب کے آخر میں تذکرہ ہوگا۔"],[2715,"§۲۷۲۲ ۔ رباح بن قصیر اللخمی(1)\nعلی کے والد قسم اول میں ان کا ذکر ہو چکا ہے۔ اصل میں صحیح وہ اس قسم سے ہیں۔","",{"fn":"(1) اسد الغابہ (۱۶۱۳) استیعاب (۷۴۶)"}],[2716,"§۲۷۲۳ ۔ ربعی(1)\nنسب کے لفظ میں نام ہے۔ ابن خراش بن جحش بن عمرو بن عبداللہ العبسی ثم الکوفی جلیل القدر مشہور تابعی ہیں، جن کی کنیت ابو مریم ہے۔ سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت کرتے ہیں۔ شام میں آپ کا خطبہ سنا۔ یہ بات خیثمہ نے “فضائل صحابہ رضی اللہ عنہم” میں درج کی ہے جو بطریق حیدہ، علی و ابن مسعود وغیرہ حضرات سے مروی ہے۔ ان سے تابعین کی ایک جماعت روایت کرتی ہے جن میں شعبی، ابو مالک اشجعی، عبدالملک بن عمیر اور منصور وغیرہ حضرات سرفہرست ہیں۔ عجلی لکھتے ہیں: ثقہ تابعی ہیں۔ نیک انسان تھے، کبھی جھوٹ نہیں بولا۔ لالکائی کا قول ہے: ان کے ثقہ ہونے پر اتفاق ہے۔ ابو موسیٰ لکھتے ہیں: بقول بعض: انہوں نے دور نبوی پایا ہے۔ ابن کلبی کا بیان ہے، حضور نبی محمد صلی اللہ علیہ وسلم نے ان کے والد کی طرف خط(2) بھیجا تو انہوں نے چاک کر دیا، اس سے پتہ چلتا ہے کہ ربعی کو دور نبوی نصیب ہوا ہے۔ ۱۰۰ھ میں فوت ہوئے۔ بقول بعض: ایک سال بعد اور ایک قول ہے اس کے چار سال بعد فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۶۱۶)\n(2) من مختصر تاریخ دمشق (۲۷۰/۸)"}],[2717,"§۲۷۲۴ ۔ ربعی الحنظلی\nشبیث کے والد۔ سیف بحوالہ اپنے راویوں کے نقل کرتے ہیں کہ ربعی سیدنا عمر رضی اللہ عنہ کے پاس آئے، آپ نے انہیں مثنی بن حارثہ کی امداد کے لیے عراق بھیج دیا۔ جب ان کا انتقال ہوا تو ان کے بیٹے شبیث کو سردار بنا دیا۔"],[2718,"§۲۷۲۵ ۔ ربعی الاہلی\nدعیل بن علی نے طبقات الشعراء میں ان کا ذکر کیا ہے کہ قادسیہ میں شریک ہوئے اور ان کے وہ اشعار نقل کیے جو انہوں نے بنی سوس میں سے اپنی قوم کے بارے میں کہے تھے۔"],[2719,"§۲۷۲۶ ۔ الربیع بن بن ربیعہ\nقسم اول میں تذکرہ ہو چکا۔"],[2720,"§۲۷۲۷ ۔ الربیع بن اوس\nبن امور بن شیبان بن عمرو بن جابر بن عقیل بن مالک بن مح بن فزارہ فزاری، خضری شاعر ہیں۔ مرزبانی نے ان کا ذکر کیا ہے اور ان کے اشعار نقل کیے ہیں: “تمہارے والد بلا شک و شبہ مزینہ سے ہیں۔ بھلا دن کی نشانیاں (جیسے سورج کا نکلنا مخفی اور پوشیدہ رہ سکتی ہیں)۔”"],[2721,"§۲۷۲۸ ۔ الربیع بن ربیعہ\nبن عوف بن قتال بن انف الناقہ بن قریع بن عوف بن کعب بن سعد بن زید مناۃ بن تمیم ثم سعدی ثم قریعی “مخبل” نام سے شہرت پانے والے شاعر ہیں، کنیت ابو یزید تھی۔ ابن کلبی نے ان کا یہی نام نقل کیا ہے۔ ابن داب لکھتے ہیں: ان کا نام کعب بن ربیعہ تھا جبکہ ابن حبیب کا قول ہے: ان کا نام ربیعہ بن مالک ہے۔ فرزدق کے شعر میں یہی مراد ہیں: “زمانہ کی نابغہ شخصیات جب چل بسیں تو انہوں نے مجھے قصائد کا ہدیہ دیا جن میں ابو یزید، ذو القروح اور جرول شامل ہیں۔” “الاغانی” میں ابو الفرج اصبہانی نے لکھا ہے: انہوں نے دور جاہلیت اور اسلام میں لمبی عمر پائی ہے، میرے خیال میں ان کا انتقال خلافت فاروقی یا عثمانی میں ہوا ہے۔ جب وہ بے حد عمر رسیدہ ہو چکے تھے، ان کا ذکر ان کے بیٹے “شیبان” حرف شین میں ہوگا۔ ابن حبیب کا قول ہے: مخبل نے زبرقان کے ہاں ان کی بہن خلیدہ کا ہاتھ مانگا تو انہوں نے انکار کر دیا اور اس کی شادی بنی جشم بن عوف کے “ہزال” نامی ایک شخص سے کر دی۔ جس کی مخبل نے ہجو کی۔ ابن حبیب وغیرہ مؤرخین نے ابو الفرج کی اپنی اسانید سے بیان کردہ قول میں لکھا ہے کہ زبرقان بن بدر رضی اللہ عنہ، سعدی عبدہ بن الطیب، عمرو بن الاہتم اور علقمہ بن عبدہ اسلام لانے سے پہلے اور آپ صلی اللہ علیہ وسلم کی بعثت سے پہلے اکٹھے ہوئے۔ اونٹ ذبح کیے اور ایک اونٹ کے بدلہ میں شراب خریدی، پھر بیٹھ کر گوشت بھون کر کھانے لگے۔ پھر شعراء کا تذکرہ ہونے لگا کہ کون سب سے اچھا شاعر ہے؟ انہوں نے اتفاق کیا کہ جو سب سے پہلے ان کے روبرو ہوگا وہی ان کا فیصل ہوگا۔ چنانچہ ربیعہ بن حذار اسدی ادھر آنکلا، انہوں نے اس سے پوچھا، وہ کہنے لگا: مجھے خدشہ ہے تم لوگ ناراض ہو جاؤ گے۔ انہوں نے اسے اطمینان دلایا، تو وہ بولا: مخبل تمہارے اشعار تو آگ کے انگارے ہیں، اللہ تعالیٰ اپنے بندوں میں سے جس پر چاہتا ہے گراتا ہے، پھر باقی واقعہ ذکر کیا۔"],[2722,"§۲۷۲۹ ۔ الربیع بن زیاد\nبن سلامہ بن قیس قضائی ثم تویلی (واؤ اور لام کے درمیان یاء ہے)۔ مشہور شہسوار ہیں جو “اعرج” کے نام سے جانے پہچانے جاتے ہیں۔ انہوں نے دور نبوی پایا ہے اور ان کے دور جاہلیت کے اشعار بھی ہیں۔ خلافت عثمان تک زندہ رہے۔ یہ ابن کلبی کا بیان ہے۔"],[2723,"§۲۷۳۰ ۔ الربیع بن ضبیع(1)\nبن وہب بن بغیض بن مالک بن سعد بن عدی بن فزارہ فزاری جاہلی دور کے ہیں۔ ابن ہشام نے “التیجان” میں لکھا ہے: ان کی اتنی عمر ہو گئی تھی کہ ہوش و حواس کھو بیٹھے تھے۔ اسلام کا زمانہ پایا ہے۔ بقول بعض تین سو(۳۰۰) سال زندہ رہے، جن میں سے ساٹھ سال اسلام میں گزارے ہیں، پھر اس کے ساتھ اس کا قصہ ذکر کیا۔ وہی اس زبان زد عام شعر کے شاعر ہیں: “جب سردیاں آئیں تو مجھے گرمی کا سامان بہم پہنچانا کیونکہ سردی بوڑھے آدمی کو ہلاک کر دیتی ہے۔” مرزبانی نے اس کے بعد یہ شعر پڑھا ہے: “جب ہر طرح کی ٹھنڈک رخصت ہو چکی ہوتی ہے تو پھر ہلکی پھلکی شلوار یا (تہبند کے طور باندھی) چادر کافی ہے۔”","",{"fn":"(1) تجرید (۱۷۷/۱)"}],[2724,"§۲۷۳۱ ۔ الربیع بن مطرف\nبن بلغ تمیمی۔ دور نبوی پایا ہے، سیف نے الفتوح میں ان کے بہت سے اشعار نقل کیے ہیں جو فتح دمشق، قادسیہ اور طبریہ کے موقعہ کے ہیں۔ فتح طبریہ میں ان کا یہ شعر ہے: “ہم لوگ پھیلی ہوئی سرحد پر فروکش ہو رہے ہیں۔ ہم ان لوگوں جیسے نہیں جنہیں دہشت کی وجہ سے جنگیں ناپسند ہوں۔ ہم نے انہیں آب حیات سے روکا جب گھبراہٹ ان کے لشکر میں سامنے ہوتے ہی پھیل گئی۔” بقول ابن عساکر: نبی صلی اللہ علیہ وسلم کی حیات مبارکہ کا دور پایا ہے۔"],[2725,"§۲۷۳۲ ۔ ربیعہ بن ابی الضبی\nمرزبانی نے معجم الشعراء میں ان کا ذکر کیا ہے کہ مخضرمی ہیں۔ انہوں نے جاہلیت میں بسطام کا دن پایا ہے۔ اتنا عرصہ زندہ رہے کہ جنگ جمل میں سیدہ عائشہ رضی اللہ عنہا کا ساتھ دیا، وہی یہ اشعار کہتے ہیں: “میں جب کسی قوم کے بھاؤ تاؤ کرتا ہوں تو میں اونٹوں والوں بنی ختبہ کے ذریعہ ان پر ظلم کرتا ہوں۔”"],[2726,"§۲۷۳۳ ۔ ربیعہ بن حوط\nبن رکاب الاشتر بن کعب بن فقعس بن طریف بن عمرو بن قعین بن ثعلبہ بن دودان بن اسد بن خزیمہ اسدی ثم فقعسی ابو المہرش۔ مرزبانی کا بیان ہے: مخضرمی شاعر ہیں، جنگ ذی قار میں موجود تھے پھر کوفہ فروکش ہوئے۔ ذی قار کے روز ان کے یہ اشعار نقل کیے ہیں: “ہر بیلے گھوڑے نے ایاد اور غم کو بچا لیا جبکہ ٹٹوؤں والوں کو موت نے دبوچ لیا۔” حافظ ابن عساکر لکھتے ہیں: حیات نبوی صلی اللہ علیہ وسلم کا دور پایا ہے۔ ابن کلبی نے ان کا نسب بیان کیا تو شاعر سے زیادہ ان کے بارے کچھ نہیں کہا۔ اس کے بعد ذکر کیا کہ مذکورہ ربیعہ بن ثعلبہ بن رکاب کے چچا جن کی کنیت ابو ثور تھی، انہوں نے ہی صحر بن عمرو سیدنا خضاء رضی اللہ عنہ کے بھائی کو قتل کیا تھا۔ لیکن ان کے اسلام کا دور پانے کے بارے میں کوئی دلیل ذکر نہیں کی۔ خنساء کے چچا زاد حبیب بن مظہر بن رکاب کا تذکرہ ہو چکا ہے۔"],[2727,"§۲۷۳۴ ۔ ربیعہ بن زرارہ العتکی\nابو الکحل دور جاہلیت دیکھا ہے، پھر بصرہ فروکش ہوئے۔ ابن الجارود نے روایت نقل کی ہے کہ انہوں نے اپنے گھرانے کے لوگوں کو پتھروں (کے بنے بتوں) کو پوجتے دیکھا ہے۔ بقول بعض: جب ان کی وفات ہوئی تو ان کی عمر حجاج کے دور میں ایک سو بیس(۱۲۰) سال تھی۔ امام احمد رحمہ اللہ نے کتاب الزہد عبید اللہ بن ثور بن عون سے بحوالہ ابن ابی الکحل جن کا نام ربیعہ بن زرارہ تھا روایت کی ہے کہ میری والدہ نے مجھے بحوالہ اپنی پھوپھی عیناء بنت ابی الکحل بتایا ہے کہ ابو الکحل کی ایک چٹائی تھی جس پر وہ سجدہ کرتے تھے۔ بڑھاپے کی وجہ سے وہ اٹھ نہ سکتے تھے، وہ یہ دعا کرتے تھے: “اللہ! مجھ سے قرآن سلب نہ کرنا۔”(1) عیناء فرماتی ہیں، ان کی وفات ایک سو بیس(۱۲۰) سال میں ہوئی۔","",{"fn":"(1) التاریخ الکبیر (۲۸۵/۱)"}],[2728,"§۲۷۳۵ ۔ ربیعہ بن سلمہ\nبقول بعض ابن عبداللہ بن حارث بن سوم بن عدی بن اشرس بن شبیب بن السکون، سکونی شاعر ہیں جو “ابن غزالہ” سے اپنا شہرہ رکھتے ہیں۔ ابن کلبی کا بیان ہے: جاہلی شاعر ہیں اور ان کے والد کا نام سلمہ بتایا ہے۔ “الاشتقاق” میں ابن درید لکھتے ہیں: اسلام کا دور پایا تو اسلام لے آئے، ان کے والد کا نام انہوں نے عبداللہ بتایا ہے۔"],[2729,"§۲۷۳۶ ۔ ربیعہ بن الکؤود\nمخضرمی شاعر ہیں۔ مرزبانی نے ان کا ذکر کیا ہے۔ ان کے نسخہ میں میں نے دیکھا ہے ابن الکؤود لکھا ہے، پھر ان کے اشعار نقل کیے۔"],[2730,"§۲۷۳۷ ۔ ربیعہ بن مالک\nبقول بعض: مخبل سعدی کا نام ہے۔"],[2731,"§۲۷۳۸ ۔ ربیعہ بن مقروم\nبن قیس بن جابر بن خالد بن عمرو بن غیظ بن السید بن مالک بن بکر بن سعد بن ضبہ الضبی۔ مرزبانی کا قول ہے وہ دور جاہلیت اور زمانہ اسلام میں مصر کے شاعر رہے ہیں۔ پھر اسلام لے آئے تو ان کا اسلام خوب نکھرا۔ قادسیہ وغیرہ فتوحات میں شریک ہوئے۔ سو سال تک زندہ رہے۔ یہی ان اشعار کے قائل ہیں: “میری زندگی میں سوں سال گزر چکے ہیں جنہیں میں سال سال کر کے گن رہا ہوں، ان کی آزمائش میں میں جتلا ہوں۔” ابو عبید نے شرح الامانی میں یہی الفاظ ذکر کیے ہیں۔ ابو الفرج اصبہانی لکھتے ہیں: جاہلیت میں کسری کے پاس گئے تھے۔ پھر اتنا زندہ رہے کہ اسلام کا دور پایا اور اسلام لے آئے۔ کافی عرصہ زندہ رہے، دعبل نے طبقات الشعراء میں ان کا تذکرہ کیا ہے کہ مخضرمی ہیں، کسری نے انہیں مستقر میں قید کیا تھا۔ پھر قادسیہ کا زمانہ پایا، جس میں ان کے اشعار ذکر کیے۔"],[2732,"§۲۷۳۹ ۔ ربیعہ بن النمر بن تؤلب\nابن قتیبہ نے ان کا ذکر کیا ہے جس کی تفصیل ان کے والد کے حالات میں بیان ہوگی۔"],[2733,"§۲۷۴۰ ۔ رحیل(1)\nالجحفی۔ ابو عمر(2) نے ان کا ذکر کیا ہے، چنانچہ دارقطنی بطریق زہیر بن معاویہ بھی بواسطہ استر بن رحیل روایت کرتے ہیں کہ ان کے والد اور سوید بن غفلہ مدینہ پہنچے تو لوگ رسول اللہ صلی اللہ علیہ وسلم کی تدفین سے فارغ ہو چکے تھے۔ تو سوید سیدنا عمر رضی اللہ عنہ کے ہاں اور رحیل سیدنا بلال رضی اللہ عنہ کے ہاں ٹھہرے۔ ابو نعیم بطریق حارث بن مسلم بھی زہیر بن معاویہ کے چچا زاد سے روایت کرتے ہیں کہ رحیل اور سوید اس وقت مدینہ آئے جب آپ صلی اللہ علیہ وسلم کی قبر پر مٹی ڈالی جا چکی تھی۔","",{"fn":"(1) اسد الغابہ (۱۶۷۱)\n(2) استیعاب (۶۹/۲)"}],[2734,"§۲۷۴۱ ۔ رشید بن ربیض العذری\nمشہور شاعر ہیں۔ مرزبانی نے ذکر کیا ہے کہ مخضرمی ہیں، یہی محرز بن مکعبر الضبی کے متعلق لکھتے ہیں: “اے ابن مکعبر تیری آنکھیں ایسی نیلی ہیں جیسے ہر ختمی کی آنکھیں کمینہ پن کی وجہ سے نیلی ہوتی ہیں۔” جنگ شیطین کے موقع پر ان کے اشعار بھی ہیں، اس روز بکر بن وائل نے بنی تمیم پر عہد رسول میں حملہ کیا تھا۔"],[2735,"§۲۷۴۲ ۔ رفیع بن مہران(1)\nابو العالیہ الریاحی۔ مشہور تابعی ہیں۔ انہیں دور نبوی نصیب ہوا۔ بقول بعض: یہ سیدنا ابو بکر رضی اللہ عنہ کے ہاں گئے اور سیدنا عمر رضی اللہ عنہ کی اقتدا میں نماز پڑھی ہے۔ ابو احمد الحاکم نے بطریق ابو خلدہ روایت کی ہے کہ میں نے ابو العالیہ سے کہا: کیا آپ نے نبی صلی اللہ علیہ وسلم کا زمانہ پایا ہے؟ وہ کہنے لگے: نہیں۔ میں آپ کی وفات کے دو یا تین سال بعد آیا۔ قتادہ ان سے روایت کرتے ہیں، فرمایا: میں نے تمہارے نبی صلی اللہ علیہ وسلم کے بعد دس سالوں میں قرآن پڑھا۔ ابن المدینی بطریق حفصہ بنت سیرین، بحوالہ ابو العالیہ روایت کرتے ہیں:(2) میں نے عہد فاروقی میں تین بار قرآن پڑھا۔ ابن ابی حاتم بطریق عاصم روایت کرتے ہیں کہ میں نے ابو العالیہ سے پوچھا: بڑے لوگوں میں سے آپ نے کسے دیکھا؟ فرمایا: ابو ایوب، البتہ میں نے ان سے کچھ حاصل نہیں کیا۔ اس کی سند صحیح ہے۔ اس میں اور پہلے والے میں فرق ظاہر ہے۔ دوسرے کی سند صحیح ہے۔ واللہ اعلم عجلی کہتے ہیں: یہ اکابر تابعین میں سے ہیں۔ الاثرم کا قول ہے کہ ابو داود سے مروی ہے: ابو العالیہ کا علم (ان کے ساتھ) چلا گیا، ان سے روایت کرنے والے کوئی نہ تھے۔ جبکہ ان سے روایت کرنے والے لوگوں میں خالد الحذاء، داؤد بن ابی ہند، محمد اور حفصہ جو سیرین کی اولاد ہیں۔ ربیع بن انس، بکر بن عبداللہ المزنی، ثابت البنانی، قتادہ، منصور بن زادان اور دوسرے لوگ شامل ہیں۔ شاید ابو داود کی مراد یہ ہے کہ ان سے قصہ اور جو تفسیر کی روایت کرنے والے ہیں وہ نہیں۔ عجلی اور ابن حبان وغیرہ نے انہیں ثقہ قرار دیا ہے۔ رہی وہ بات جو امام شافعی سے مروی ہے کہ ریاحی کی حدیث ہوا (کی طرح بے وقعت) ہے تو اس سے مراد ان کی وہ خاص حدیث ہے جو حدیث قہقہہ کہلاتی ہے۔ اسی طرح ابن عدی نے اس سے خبر دار کیا ہے، پھر لکھا کہ ان کی بقیہ احادیث ٹھیک ہیں۔ مؤرخین کا کہنا ہے: نوے (۹۰ھ) میں بقول بعض اس کے تین سال بعد فوت ہوئے۔ ایک قول ہے: ایک سو چھ (۱۰۶ھ) میں فوت ہوئے۔ پہلا قول مضبوط ہے۔","",{"fn":"(1) اسد الغابہ (۷۰۴)\n(2) اسد الغابہ (۱۹۸/۲)"}],[2736,"§۲۷۴۳ ۔ روح بن حبیب التغلبی\nابن عساکر(1) نے اپنی تاریخ میں ان کا ذکر کیا ہے کہ انہوں نے زمانہ نبوی پایا ہے۔ اور سیدنا ابو بکر و عمر رضی اللہ عنہما سے روایت کی ہے سیدنا عمر رضی اللہ عنہ کے خطبہ جابیہ میں شریک ہوئے، پھر بطریق حکم بن خطاب بواسطہ زہری، ابو واقد سے بحوالہ روح بن حبیب روایت کی ہے کہ ایک دفعہ میں صدیق اکبر رضی اللہ عنہ کے پاس تھا۔ اتنے میں ایک کوا لایا گیا۔ آپ نے جب اس کے دونوں پروں کو دیکھا تو فرمایا: “جو پرندہ وغیرہ شکار کیا جاتا ہے تو تسبیح کے کم کرنے کی وجہ سے اور جو کسی ناپسندیدہ کام میں شامل ہو تو کسی گناہ کی وجہ سے جبکہ اللہ تعالیٰ تو اس سے زیادہ معاف کر دیتا ہے۔” پھر اس کوے کو چھوڑ دیا۔","",{"fn":"(1) مختصر تاریخ دمشق (۲۴۰/۵)"}],[2737,"§۲۷۴۴ ۔ رناب\nبعض نے یہ نام زباب بتایا ہے۔ ابن رمیلہ، اشہب بن رمیلہ کے بھائی، انہیں دور نبوی نصیب ہوا۔ سیدنا عثمان رضی اللہ عنہ کے دور میں (جب آپ کی شہادت کا سانحہ عظیمہ پیش آیا، اس کے بعد) ان کے بھائی (اشہب) کے حالات میں ان کا ذکر ہوا ہے (وہاں یہ نام رباب ہے)۔"],[2738,"§۲۷۴۵ ۔ رفاب\nابن حارث شخصی، دور نبوی پایا ہے اور عہد فاروقی میں فتوحات میں شریک رہے۔ امام بخاری رحمہ اللہ بطریق صدقہ بن اسمٹی بحوالہ اپنے دادا ریاح بن حارث روایت کرتے ہیں کہ انہوں نے سیدنا عمر رضی اللہ عنہ کے ساتھ دو حج کیے تھے۔ اور بطریق سماک، جریر بن ریاح سے بحوالہ ان کے والد مروی ہے کہ انہیں مدائن میں ایک قبر ملی جس پر زربافت کپڑا اور مال پڑا ہوا تھا۔ سیدنا عمار نے سیدنا عمر رضی اللہ عنہ کو تفصیل لکھی۔ آپ نے فرمایا کہ اسے نہ اتاریں۔ امام بخاری رحمہ اللہ(1) نے دونوں میں فرق کیا ہے، جبکہ ابن ابی حاتم نے دونوں یکجا کیے ہیں، یہی زیادہ درست ہے۔","",{"fn":"(1) التاریخ الکبیر (۳۳۳/۱)"}],[2739,"§۲۷۴۶ ۔ رافع بن بدیل(1)\nبن ورقاء خزاعی۔ ابن مندہ نے ان کا ذکر کیا ہے کہ یہ بئر معونہ کے روز شہید ہوئے اور بطریق ابن اسحاق(2) ان کی شہادت کا واقعہ لکھا ہے۔ ابو نعیم نے ان کا تعاقب کرتے ہوئے لکھا ہے کہ دوسرے نام کو غلط لکھ دیا ہے۔ یہ نام رافع کی بجائے نافع ہے۔ جس میں کوئی اختلاف نہیں اور اہل تاریخ اور مغازی کا اس پر اتفاق ہے۔","",{"fn":"(1) اسد الغابہ (۱۵۷۱)\n(2) السیرۃ النبویۃ (۱۴۷، ۱۴۶/۳)"}],[2740,"§۲۷۴۷ ۔ رافع بن بشر السلمی(1)\nکسی راوی نے اسے الٹ دیا۔ یہ نام یوں تھا: “بشر بن رافع”۔ حشر کے بارے ان کی ایک حدیث ہے جیسا کہ ابو عمر(2) نے کہا ہے۔ ابن شاہین کا بیان ہے کہ علی بن ثابت نے یہ نام الٹ دیا ہے۔\nمیں کہتا ہوں: انہی کے طریق سے بقی بن مخلد نے ان کا ذکر کیا ہے۔ صحیح نام پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۱۵۷۲)\n(2) استیعاب (۷۲۶)"}],[2741,"§۲۷۴۸ ۔ رافع بن ثابت(1)(2)(3)\nمصر فروکش ہوئے۔ ابن مندہ نے ان میں اور رولفع بن ثابت میں فرق کیا ہے، جبکہ دونوں ایک ہیں۔ یہ ابو نعیم کا قول ہے۔","",{"fn":"(1) تجرید (۱۷۲/۱)\n(2) استیعاب (۵۹/۲)\n(3) اسد الغابہ (۱۵۷۵)"}],[2742,"§۲۷۴۹ ۔ رافع بن معبد انصاری(1)\nابو الحسن، حمص فروکش ہونے والے۔ ان سے محمد بن زیاد وغیرہ روایت کرتے ہیں۔ ابن الاثیر(2) نے ان کا ذکر کیا ہے اور سابقہ لوگوں سے پہلے اپنے استدراک میں ان کا ذکر کیا ہے۔ اور ابو علی الجیانی کی طرف اس کی نسبت کی۔ ان کے والد کا نام انہوں نے غلط لکھ دیا ہے۔ اسے انہوں نے حرف میم میں ذکر کیا حالانکہ وہ “سعد” ہے۔ میں نے قسم اول میں صحیح نام ذکر کر دیا ہے جس کی نسبت ابن شاہین کی طرف ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۰۰)\n(2) اسد الغابہ (۱۵۸/۲)"}],[2743,"§۲۷۵۰ ۔ الربیع بن زیاد\nبن عبد اللہ بن سفیان بن ناشب بن ہرم بن عوذ بن غالب بن قطیعہ بن عبس العبسی۔ جاہلیت کی مشہور شخصیت۔ نعمان بن منذر کے ندیم تھے۔ بقول بعض: وہ ایک کامل انسان تھے۔ میری نظر سے نہیں گزرا کہ سوائے رشاطی کے کسی نے لکھا ہو کہ انہوں نے اسلام کا زمانہ پایا ہے۔ چنانچہ وہ اشعری کے حالات میں ربیع بن زیاد حارثی کے سیدنا عمر رضی اللہ عنہ کے ساتھ پیش آمدہ ایک واقعہ لکھتے ہیں۔ رشاطی نے کہا: یہ ربیع بن زیاد عبسی ہیں، جبکہ قصہ حارثی کے حوالہ سے مشہور ہے۔ یوں رشاطی کو کھلا وہم ہو گیا۔"],[2744,"§۲۷۵۱ ۔ الربیع بن عمرو\nبن ابی زہیر خزرجی انصاری۔ سعد بن ربیع کے والد۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا اور مکی بن ابی طالب سے روایت نقل کی ہے کہ جب ربیع کی اُحد میں شہادت ہوئی تو ان کے دو بیٹے یتیم رہ گئے۔ جس کے بارے میں یہ آیت نازل ہوئی: “اللہ تعالیٰ تمہیں تمہاری اولاد کے بارے میں ہدایت کرتا ہے۔”(1) مشہور یہ ہے کہ ان بچوں کا مال سمیٹنے والا انہی کا چچا تھا، یہی درست ہے۔ ابن مندہ بطریق عنبہ بن عبد الرحمن، محمد بن زادان سے بواسطہ ام سعد بنت الربیع وہ اپنے والد کے حوالہ سے مرفوع روایت کرتے ہیں کہ عورتوں کی فرمانبرداری ندامت و شرمندگی کا باعث ہے۔ درست سند ام سعد بنت سعد بن ربیع ہے۔","",{"fn":"(1) سورۃ النساء (آیت ۱۱)"}],[2745,"§۲۷۵۲ ۔ الربیع بن کعب انصاری\nیہ وہم ہے اسی طرح ابن مندہ نے ان کا تذکرہ کر دیا ہے۔ درست ربیعہ بن کعب ہے جو اسلمی ہیں، انصار کے حلیف ہیں۔"],[2746,"§۲۷۵۳ ۔ الربیع بن محمود الماردینی\nصوفیاء کے مشائخ میں سے تھے جنہوں نے صحابی ہونے کا دعوی کیا تھا۔ ذہبی نے میزان میں اسی طرح ذکر کیا ہے۔ بقول بعض: یہ شخص بڑا فریبی دجال تھا جس نے صحابیت کا دعوی کیا تھا، اور کہا کہ اس کی عمر پانچ سو ننانوے(۵۹۹) سال ہے۔ اس نے ابن عساکر سے ۶۰ھ کی دہائی میں سماع کیا تھا۔\nمیں کہتا ہوں: مجھے اس کے صحابی ہونے کے بارے میں معلوم ہوتا ہے وہ یہ ہے کہ اس نے خواب میں نبی صلی اللہ علیہ وسلم کو دیکھا اس وقت وہ مدینہ میں تھا، آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: “تو دنیا و آخرت میں کامیاب ہوا۔” جب بیدار ہوا تو یہ کہنے لگا کہ اس نے نبی صلی اللہ علیہ وسلم سے سنا ہے۔ آپ صلی اللہ علیہ وسلم یہ فرما رہے تھے۔ یہی اس کی مراد تھی جو اس نے صحابی ہونے کا دعوی کر دیا۔ میں نے علامہ تقی الدین بن دقیق العید کے قلم سے لکھا دیکھا ہے کہ کمال بن العدیم نے انہیں یہ بات لکھ کر بھیجی کہ ان کے چچا محمد بن ہبتہ اللہ بن ابی جرادہ نے انہیں بتایا کہ میں مسجد نبوی میں تھا، آپ کے (روضہ کے) پاس آپ سے مشورہ لینے حاضر ہوا، وہیں آنکھ لگ گئی۔ میں نے دیکھا آپ صلی اللہ علیہ وسلم مجھ سے فرما رہے ہیں: “تم دنیا و آخرت میں کامیاب ہو گئے۔” پھر میں بیدار ہو گیا تو بھی(1) آپ صلی اللہ علیہ وسلم مجھ سے یوں ہی فرما رہے تھے (یعنی مجھے محسوس ہو رہا تھا کہ آپ صلی اللہ علیہ وسلم فرما رہے ہیں، الفاظ ذہن میں گردش کر رہے تھے)۔ پھر لمبا واقعہ ذکر کیا جس میں اسی قسم کی باتیں ہیں۔\nمیں کہتا ہوں: میں نے محمد بن حافظ زکی الدین المنذری کے قلم سے لکھا دیکھا کہ میں نے عبد الواحد بن عبد اللہ بن عبد الصمد بن ابی جرادہ کو فرماتے سنا: میں نے اپنے دادا کو فرماتے سنا: میں نے ۶۰۱ھ میں حج کیا۔ شیخ رتن سے ملاقات ہو گئی، حلب تک ساتھ رہنے کی درخواست کی تو وہ مجھ سے کہنے لگے: میرا تو بیت المقدس مرنے کا ارادہ ہے۔ فرماتے ہیں: تو میں بیت المقدس تک ان کے ساتھ ہو لیا۔ وہ بیمار پڑ گئے اور بیماری میں شدت آتی گئی۔ پھر ہمیں اطلاع ملی کہ وہ بیت المقدس میں فوت ہو چکے ہیں۔ یہ ۶۰۲ھ کا واقعہ ہے اور یہ بات مجھے فوائد ابی بکر بن محمد العربی میں ملی ہے۔","",{"fn":"(1) لسان المیزان (۱۸۲۹/۲)"}],[2747,"§۲۷۵۴ ۔ ربیعہ بن امیہ(1)(2)\nبن خلف بن وہب بن حذافہ بن حج قرشی جمحی، صفوان کے بھائی۔ فتح مکہ کے روز اسلام لائے۔ حجتہ الوداع میں شریک تھے جس کے متعلق ان کی ایک مسند حدیث ہے جس کی وجہ سے ان لوگوں نے انہیں صحابہ میں ذکر کر دیا جنہوں نے ان کے بارے میں غور نہیں کیا۔ ان میں بغوی اور ان کے احباب ابن شاہین، ابن السکن، باوردی اور طبرانی(3) ہیں۔ جبکہ ابن مندہ اور ابو نعیم نے بھی ان کا اتباع کیا ہے۔ ابن شاہین کی کتاب میں بحوالہ ربیعہ بن امیہ مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے یہ حکم دیا کہ میں ان کی سواری کے نیچے کھڑا رہوں اس وقت آپ صلی اللہ علیہ وسلم عرفہ میں ٹھہرے ہوئے تھے ان کی آواز بڑی بلند تھی، آپ علیہ السلام نے فرمایا: ربیعہ! لوگوں سے کہو کہ رسول اللہ صلی اللہ علیہ وسلم تم سے فرما رہے ہیں: “تمہیں معلوم ہے یہ کون سا شہر ہے؟” (حدیث) ان کے علاوہ لوگوں نے اسے ابن اسحاق سے نقل کیا ہے کہ نبی صلی اللہ علیہ وسلم نے امیہ کو حکم دیا، یہی درست ہے۔ یحیی بن ہانی والی روایت جو ابن شاہین نے نقل کی ہے وہم پر مبنی ہے۔ یحیی بن عباد نے امیہ کا دور نہیں پایا ہے، یہ روایت مغازی ابن اسحاق میں درست لکھی ہے۔ ابن خزیمہ اور حاکم نے دوسری سند سے ابن اسحاق سے بواسطہ ابن ابی شیخ عطاء سے بحوالہ ابن عباس نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے ربیعہ کو حکم دیا، پھر اسے ذکر کیا۔ اگر ان کے بارے میں صرف یہی روایت ہوتی تو ان کا شمار صحابہ میں ہونا درست تھا۔ لیکن ان کے بارے میں آتا ہے کہ وہ دور فاروقی میں مرتد ہو گئے تھے (نعوذ باللہ من ذلک) چنانچہ یعقوب بن شیبہ نے اپنی مسند میں بطریق حماد، محمد بن عمرو سے بحوالہ یحیی بن عبد الرحمن بن حاطب روایت نقل کی ہے۔ سیدنا ابو بکر صدیق رضی اللہ عنہ سب سے زیادہ فن تعبیر خواب کے ماہر تھے۔ ربیعہ بن امیہ ان کے پاس آ کر کہنے لگا: میں نے خواب میں دیکھا ہے کہ میں سرسبز و شاداب زمین پر ہوں، وہاں سے نکل کر قحط زدہ بنجر زمین میں چلا گیا ہوں اور آپ کو لوہے کے ایک خول میں تخت کے پاس حشر کی طرف جاتے دیکھا ہے۔ آپ نے فرمایا: اگر تمہارا خواب سچا ہے تو تم ایمان چھوڑ کر کفر اختیار کر لو گے، جہاں تک میرا تعلق ہے تو میرا دین حشر کے دن تک میرے لیے مضبوط کر دیا گیا ہے۔ راوی کا بیان ہے: ربیعہ نے دور فاروقی میں شراب پینا شروع کر دی تو سیدنا عمر رضی اللہ عنہ کے ڈر سے شام بھاگ گیا، وہاں سے قیصر کی طرف بھاگ نکلا جہاں اس نے نصرانیت اختیار کر لی اور اسی کے پاس مرا۔ ابن عبد البر نے “استیعاب” میں یہ قصہ مختصر ذکر کیا ہے اور تعبیر سیدنا عمر رضی اللہ عنہ نے اسے بتائی تھی۔ عبد الرزاق عبد الرحمن بن عوف کی روایت نقل کرتے ہیں کہ ایک رات وہ مدینہ میں سیدنا عمر رضی اللہ عنہ کے ساتھ پہرہ دے رہے تھے، ایک گھر میں چراغ جلتا دکھائی دیا، تو یہ اس کی خبر لینے ادھر گئے۔ دیکھا گھر میں کچھ لوگ دروازہ بند کیے اونچی آواز میں خوش گپیوں میں مصروف ہیں، سیدنا عمر رضی اللہ عنہ نے سیدنا عبد الرحمن سے فرمایا: جانتے ہو یہ کس کا گھر ہے؟ انہوں نے کہا: نہیں۔ آپ نے فرمایا: یہ ربیعہ بن امیہ کا گھر ہے، اس وقت یہ لوگ شراب پی رہے ہیں، تمہاری کیا رائے ہے؟ انہوں نے کہا: ہم اس چیز کا ارتکاب کر بیٹھے ہیں جس سے اللہ تعالیٰ نے منع فرمایا ہے: “اور تجسس و ٹوہ نہ لگایا کرو۔”(4) فرماتے ہیں: سیدنا عمر رضی اللہ عنہ واپس ہو گئے۔ اسی سند سے زہری تک بحوالہ سعید بن المسیب مروی ہے کہ سیدنا عمر رضی اللہ عنہ نے ربیعہ بن امیہ کو شراب نوشی کی وجہ سے خیبر میں نظر بند کر دیا تو وہ ہرقل سے جا ملا اور نصرانیت قبول کر لی۔ سیدنا عمر رضی اللہ عنہ فرمانے لگے: اب میں کبھی کسی کو نظر بند نہیں کروں گا۔ نسائی نے یہ روایت بطریق معتمر بن سلیمان عبد الرزاق سے نقل کی ہے۔ سیدنا عمر رضی اللہ عنہ کے ساتھ اس کا ایک اور قصہ بھی ہے جسے امام مالک رحمہ اللہ نے موطا میں ابن شہاب سے بحوالہ عروہ نقل کیا ہے کہ خولہ بنت حکیم رضی اللہ عنہا سیدنا عمر رضی اللہ عنہ کے پاس تشریف لائیں اور ان سے کہنے لگیں کہ ربیعہ بن امیہ نے ایک موحدہ عورت سے متعہ کیا ہے جس سے وہ ماں بن گئی ہے۔ سیدنا عمر رضی اللہ عنہ گھبراہٹ سے اپنی چادر گھسیٹتے اٹھے اور فرمایا: یہ تو متعہ ہے اگر مجھے پہلے معلوم ہو جاتا تو میں اسے سنگسار کر دیتا۔","",{"fn":"(1) اسد الغابہ (۱۶۳۳)\n(2) تجرید (۱۷۸/۱)\n(3) المعجم الکبیر (۴۶۰۳/۵)\n(4) سورۃ الحجرات (آیت ۱۲)"}],[2748,"§۲۷۵۵ ۔ ربیعہ بن حارث\nبن مالک ابو فراس اسلمی، از اہل صفہ، ذہبی نے تجرید میں اپنے استدراک میں ان کا ذکر کیا ہے اور ان کے والد کے نام میں لفظی غلطی کر بیٹھے ہیں۔ وہ حارث نہیں بلکہ کعب ہے، صحیح پہلے گزر چکا ہے۔"],[2749,"§۲۷۵۶ ۔ ربیعہ بن حصین(1)\nوہ جریر کی طرف سے رسول اللہ صلی اللہ علیہ وسلم کے پاس قاصد بن کر آئے۔ ایسا ہی ابن شاہین نے بحوالہ ابن کلبی نقل کیا ہے یہ نام الٹ گیا ہے، درست حصین بن ربیعہ ہے، پہلے تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۳۶)"}],[2750,"§۲۷۵۷ ۔ ربیعہ بن مالک ساعدی(1)\nبعض نے ایسا ہی سمجھا ہے کہ یہ ابو اسید کا نام ہے جسے الٹ دیا۔ درست مالک بن ربیعہ ہے ابو موسیٰ نے اس سے خبردار کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۶۴)"}],[2751,"§۲۷۵۸ ۔ ربیعہ بن لقیط(1)\nمشہور تابعی جو مرسل حدیث نقل کرتے ہیں، جس کی وجہ سے ابو علی العسکری نے ان کا ذکر کیا ہے اور بطریق لیث، یزید بن ابی حبیب بحوالہ ربیعہ بن لقیط روایت نقل کی ہے کہ جب آپ کے پاس رومی قاصد آیا تو اس نے آپ سے گھوڑا مانگا، آپ نے اسے عطا کر دیا۔ کسی صحابی نے اس بارے میں عرض کی، آپ صلی اللہ علیہ وسلم نے فرمایا: “اس سے کوئی مسلمان چھین لے گا۔”(2) چنانچہ ایسا ہی ہوا۔ ابو موسیٰ فرماتے ہیں: ان کا صحابی ہونا معلوم نہیں۔ یہ عبداللہ بن حوالہ وغیرہ سے روایت کرتے ہیں۔\nمیں کہتا ہوں: امام بخاری(3)، یعقوب بن شیبہ، ابو حاتم، علی(4) اور ابن یونس وغیرہ نے انہیں تابعین میں شمار کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۶۲)\n(2) جامع المسانید (۲۶۲/۴)\n(3) التاریخ الکبیر (۲۸۳/۱)\n(4) الجرح والتعدیل (۴۷۵/۳)"}],[2752,"§۲۷۵۹ ۔ ربیعہ خادم النبی\nابن الاثیر نے اپنے استدراک میں ان کا ذکر کیا ہے، ابو عمر نے اپنے مقام پر ان کا درست تذکرہ کیا ہے کہ ربیعہ بن کعب خادم النبی صلی اللہ علیہ وسلم ہیں جن کا ذکر ہوا ہے۔"],[2753,"§۲۷۶۰ ۔ ربیعہ الکلابی(1)\nابو موسیٰ نے بطریق ابو مسلم الکجی، سلیمان بن داؤد، سعید بن خیثم، ربیعہ بنت عیاض، بواسطہ عیاض بحوالہ ربیعہ کلابی روایت کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو وضو کرتے دیکھا آپ صلی اللہ علیہ وسلم نے پوری طرح وضو کیا۔ (حدیث)(2) اسی روایت کو یحیی بن جثمانی وغیرہ نے سعید سے نقل کیا تو یوں نقل کیا ربیعہ سے بواسطہ عبیدہ بن عمرو کلابی مروی ہے یہی درست ہے، عنقریب تذکرہ ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۶۱)\n(2) جامع المسانید (۲۶۶/۴)"}],[2754,"§۲۷۶۱ ۔ رتن بن عبد اللہ الہندی\nثم البترندی۔ بقول بعض: المرندی۔ رتن تاء کے بجائے طاء سے بھی ہے، بن ساہوک بن جکندریو۔ میں نے قابل اعتماد لوگوں کے قلم سے ایسا ہی لکھا پایا ہے۔ بعض نے واؤ کے بجائے قاف نقل کیا ہے۔ بقول بعض: رتن بن نصر بن کربال، ایک قول ہے: رتن بن میدن بن مندی۔ ایک بوڑھا شخص جس کے گمان میں اس کا حال عرصہ دراز تک مخفی رہا اور چھٹی صدی کے آخر میں ظاہر ہوا پھر اس نے صحابی ہونے کا دعویٰ کیا۔ اس سے اس کے دونوں بیٹوں محمود اور عبد اللہ، موسیٰ بن مجلی ابن بندار دنیسیری، حسن بن محمد الحسینی، خراسانی کمال شیرازی، اسمعیل بارقی، ابو الفضل عثمان بن ابی بکر بن سعید الاربلی، داؤد بن اسعد بن حامد القفال الحروری والشریف علی بن محمد خراسانی ہروی، المعمر ابو بکر المقدسی تمام سہرکندی، ابو مروان عبد الملک بن بشر المغربی نے روایت کی ہے لیکن اس کا نام نہیں لیا۔ وہ لکھتے ہیں: میں عمر رسیدہ شخص سے ملا پھر اس کے وہی حالات بیان کیے جو دوسرے لوگوں نے رتن کے بارے میں بیان کیے ہیں۔ متقدمین میں سے مجھے کسی کی اس بارے کوئی تحریر نہیں ملی جنہوں نے صحابہ کے متعلق کتب لکھی ہیں۔ اور نہ دوسرے لوگوں کے ہاں ہی اس کا ذکر ملا ہے۔ لیکن ذہبی نے اپنی “تجرید” میں اس کا ذکر کیا ہے کہ رتن الہندی ایک بزرگ تھا جو چھٹی صدی کے بعد مشرق میں ظاہر ہوا، جس نے صحابیت کا دعویٰ کیا اور جاہلوں نے اس سے سماع کیا، اس کا کوئی وجود نہیں۔ بلکہ جھوٹوں نے اس کا نام گڑھ لیا ہے، میں نے بطور تعجب اس کا ذکر کیا ہے جیسے ابو موسیٰ نے سرباتک ہندی کا ذکر کیا ہے، بلکہ یہ ابلیس ملعون بھی ہے جس نے نبی صلی اللہ علیہ وسلم کو دیکھا اور آپ سے سنا وہ اس سے زیادہ صحابی بلکہ مطلقا افضل صحابی بن سکتا ہے۔ پھر انہوں نے عیسیٰ علیہ السلام کا ذکر کیا، جیسا کہ ان کے حالات میں ان شاء اللہ بیان ہوگا۔\nانہوں نے “میزان” میں اس کا ذکر کیا ہے کہ رتن ہندی، تمہیں کیا معلوم رتن کیا ہے؟ بلا شک و شبہ ایک دجال بزرگ ہے جو چھٹی صدی کے بعد ظاہر ہوا اور صحابی ہونے کا دعویٰ کیا جبکہ صحابہ جھوٹ نہیں بولا کرتے تھے۔ اور یہ تو اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کے خلاف جرات ہے۔ میں نے اس کے متعلق ایک رسالہ بھی لکھا ہے۔ بعض کا قول ہے کہ وہ چھ سو بتیس (۶۳۲ھ) میں فوت ہوا۔ اس کے باوجود وہ بڑا جھوٹا ہے۔ ناقدین نے اس کے بہت سے جھوٹ پکڑے ہیں، جو ایسے جھوٹ ہیں جن کا ہونا ہی محال ہے۔\nمیں کہتا ہوں: اربلی کا گمان ہے کہ اس نے اس سے چھ سو پچپن کے بعد سماع کیا ہے۔ پھر مسلسل اس جزء کی تلاش میں رہا بالآخر وہ مجھے اس کے مؤلف کے قلم سے تحریر کردہ نسخہ مل گیا جسے میں نے یہاں اس کے قلم سے اس کے الفاظ میں تحریر کیا ہے اس کی ابتداء اس طرح ہے: بسم اللہ الرحمن الرحیم، سبحانک ھذا بہتان عظیم شیخ الشیوخ کا قول ہے اور میں نے اسی کے قلم سے نقل کیا ہے، مؤلف کا نام محمد ابو القاسم بن عبد الرحمن بن عبد اللہ بن عبد الکریم الحسینی الکاشغری ہے کہ مجھ سے شیخ رہنما، اسرار ربانیہ کے اترنے کی جگہ انوار سبحانیہ کا سر چشمہ ہمام الدین سہرکندی نے بواسطہ ایک عمر رسیدہ بزرگ جو سید البشر کے صحابہ میں سے باقیماندہ ہیں خواجہ رتن بن ساہوک بن جگندریق بترندی نقل کرتے ہیں، فرمایا: ہم لوگ پت جھڑ کے موسم میں نبی صلی اللہ علیہ وسلم کے ساتھ تھے، ہوا چلنے سے درخت کے پتے جھڑنے لگے اور اس پر ایک پتہ بھی نہ رہا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “مومن جب جماعت کے ساتھ فرض نماز پڑھتا ہے تو اس کے گناہ ایسے ہی جھڑتے ہیں جیسے اس درخت کے پتے جھڑ رہے ہیں۔ اور آپ علیہ السلام نے فرمایا: “جس نے مالداری کی وجہ سے اس کی عزت کی اور فقیر کی فقر و فاقہ کی وجہ سے اہانت کی تو وہ ہمیشہ کے لیے اللہ تعالیٰ کی لعنت میں رہے گا، ہاں اگر وہ توبہ کر لے۔(1) اور آپ علیہ السلام نے فرمایا: “جو آل محمد سے بغض رکھ کر مرا وہ کافر مرا۔ اور آپ علیہ السلام نے فرمایا: “جس نے ہر رات اپنی آبروؤں پر کنگھی کی اور مجھ پر درود بھیجا اس کی آنکھیں کبھی نہ دکھیں گی”۔\nمیں کہتا ہوں: اس نے آٹھ اور احادیث بھی بیان کی ہیں۔ پھر ذہبی بحوالہ کاشغری لکھتے ہیں: مجھ سے سردار رہنما تاج الدین محمد بن احمد بن محمد خراسانی نے مدینہ النبی علی صاحبھا الصلواۃ والسلام میں ذوالحجہ سات سو سات (۷۰۷ھ) میں بیان کیا۔ اما بعد! یہ چالیس مختلف رتنی احادیث ہیں جو میں نے شیخ المسلک ابو الفتح موسیٰ بن مجلی صوفی سے چھ سو تہتر (۶۷۳ھ) میں سمنان کی سابقہ خانقاہ میں ان کے سامنے پڑھیں، بحوالہ صحابی رسول صلی اللہ علیہ وسلم امام ابو الرضا رتن بن نصر کی روایت کردہ ان احادیث کو منتخب کیا ہے کہ آپ علیہ السلام نے فرمایا: “اعمال باطن کا ذرہ اعمال ظاہر سے بہتر جسے مضبوط پہاڑ۔(2) اور آپ علیہ السلام نے فرمایا: “فقیر اپنے فقر کے بارے میں تم سے زیادہ غیرت مند ہوتا ہے جتنی غیرت تمہیں اپنی اہلیہ کے بارے میں ہوتی ہے۔(3) پھر اور احادیث ذکر کیں۔ اس کے بعد کہا کہ رتن نے فرمایا: میں اور صحابہ کی ایک جماعت سیدہ فاطمہ رضی اللہ عنہا کی رخصتی میں تھی۔ وہاں ایک گوتیا بھی تھا جس سے ہمارے دل خوش ہوئے اور ہم لوگ ناچنے لگے۔ اگلے روز ہم نے رسول اللہ صلی اللہ علیہ وسلم سے گزشتہ رات کے بارے میں پوچھا آپ نے ہمیں دعا دی اور ہمارے اس کام پر نکیر نہیں کی۔ آپ نے فرمایا: “کھردرا کپڑا پہنو، ننگے پیر چلو، اللہ تعالیٰ کو رو برو دیکھو گے۔ ذہبی فرماتے ہیں: مجھے اس کا ایک اور نسخہ بھی معلوم ہے جسے عبید اللہ بن محمد بن عبد العزیز سمرقندی روایت کرتا ہے کہ مجھ سے امام صفوۃ الاولیاء جلال الدین موسیٰ مجتبی بن بندار دیسیری نے بیان کیا کہ ہمیں شیخ کبیر بے نظیر و بے مثال رتن بن نصر بن کربال الہندی نے بحوالہ نبی علیہ السلام یہ بتایا کہ آپ نے فرمایا: “خبردار! بازاری افراد اور عورتوں کو رفیق سفر بنانے سے بچنا کیونکہ یہ اللہ تعالیٰ سے دوری کا سبب ہے۔ اور آپ نے فرمایا: “اگر کسی یہودی کو ابو جہل سے کوئی کام پڑے جو وہ مجھ سے کروانا چاہ رہا ہو تو میں ابو جہل کے دروازے پر سو بار بھی جانے کے لیے تیار ہوں۔(4) اور فرمایا: “عالم کا قلم چھیلنا اللہ تعالیٰ کو مجاہد کا اللہ کی راہ میں کسی کا پیٹ چاک کرنے سے زیادہ پسند ہے۔ اور فرمایا: “عالم یا طالب علم کی دوات کا اس کے کپڑے پر لگا نقطہ مجھے شہید کے سو کپڑوں کے داغ سے زیادہ محبوب ہے۔ اور فرمایا: جس نے کسی بھوکے کو باوجود اسے سیر کرنے کی قدرت کے واپس کر دیا اللہ تعالیٰ اسے عذاب دے گا اگر چہ وہ نبی مرسل ہو۔ اور فرمایا: “جو شخص میرے بیٹے حسین کی شہادت کے دن رویا تو وہ قیامت کے روز بڑے مرتبہ والے انبیاء کے ساتھ ہوگا۔(5) اور آپ نے فرمایا: جس نے نماز چھوڑنے کو ایک لقمہ کے ذریعہ بھی تقویت دی تو اس نے تمام انبیاء کو قتل کرنے میں قاتل کی امداد کی۔ پھر تقریباً تین سو احادیث ذکر کیں۔ نسخہ کے آخر میں ایک طبقہ ہے جو اس صورت میں ہے، یہ تمام احادیث میرے سامنے شیخ ابو القاسم محمد بن عبد الرحمن بن عبد اللہ بن عبد الرحیم الحسینی الکاشغری نے پڑھیں جو میں نے امام ابو عبد اللہ احمد بن ابی المحاسن، یعقوب بن ابراہیم الطبیعی الاسدی سے سنیں، انہوں نے امام حافظ جلال الدین موسیٰ بن مجتبی دنیسیری سے خوارزم میں چھ سو پینسٹھ (۶۶۵ھ) میں سنی تھیں اور موسیٰ نے رتن سے سنی تھیں۔ اور محمد بن ابی بکر بن اسمعیل بن علی انصاری نے ربیع الاول کے مہینہ ۶۱۰ھ میں لکھیں۔ پھر ذہبی لکھتے ہیں: میرے خیال میں یہ تمام خرافات اس جاہل موسیٰ بن مجلی کی وضع کردہ ہیں یا اس نے وضع کی ہیں جس نے رتن کا نام ایجاد کیا ہے اور یہ ایسی چیز ہے جو پیدا ہی نہیں ہوئی۔ اگر ہم اس کے وجود اور ظہور کو چھٹی صدی کے بعد صحیح تسلیم کر لیں، تو وہ یا تو شیطان ہے جو کسی انسانی صورت میں رونما ہوا اور صحابی ہونے کا دعویٰ کر ڈالا۔ اور ساتھ ہی اتنی طویل عمر کا شوشہ چھوڑ دیا جس کی آڑ میں اس نے یہ مصیبتیں گھڑیں، یا پھر یہ کوئی گمراہ بزرگ ہے جس نے نبی علیہ السلام کے بارے جھوٹ بول کر جہنم میں اپنا گھر بنا لیا۔ اگر اس طرح کی باتیں سلف کی کسی شخصیت کی نسبت سے بیان ہوتیں پھر بھی ہمارے لئے ان سے بچنا ضروری تھا۔ چہ جائیکہ وہ سید البشر کی جانب سے بیان ہوں۔ لیکن جب صوفیاء کے عامی لوگ اس طرح کی واہیات نقل کرنے لگے اور اس میں کاشغری، طیبی، موسیٰ بن مجلی اور رتن جیسے لوگوں کا سلسلہ اسناد ہے، تو یہ سلسلۃ الذہب نہیں بلکہ سلسلۃ الکذب ہے (سونے کی لڑی نہیں بلکہ جھوٹ کی کڑی ہے)۔ پھر ذہبی نے ان مرویات کی تعداد پر بحث کی جو ان کے دور میں کم سے کم بیان کی جاتی تھیں اور پھر ان میں سے خاص اصطلاح کی عالی سندوں میں سے چند ایک ذکر کیں کہ وہ عالی جھوٹی روایت اور جو اپنا وجود نہیں رکھتی دونوں برابر ہیں۔ پھر غالی صوفیوں کا تذکرہ شروع کر کے لکھا ہے: ان میں سے کوئی کہتا ہے: مجھ سے میرے دل نے بیان کیا کہ میرے رب نے یوں کہا۔ پھر اتحادیہ کا تذکرہ کیا کہ ان میں سے کوئی یہ کہتا ہے کہ وہ اللہ کی آنکھ ہے، پھر فرماتے ہیں: آپ کو معلوم ہونا چاہیے کہ لوگوں کو عجیب و غریب باتیں بیان کرنے پر مختلف اسباب اکساتے ہیں۔ سو یہ ہندی چھٹی صدی میں کہاں چھپا ہوا تھا؟ کیا آس پاس کے ممالک کے لوگوں کو اس کی اور اس کی لمبی عمر کی کوئی شنید نہ تھی کہ وہ منصور اور مہدی کے دور حکومت میں چل کر اس کے پاس آ جاتے۔ کیا ہندوستان کا بادشاہ اس عجوبے کو مامون کے پاس تحفہ نہیں بھیج سکتا تھا؟\nمیں کہتا ہوں: یعنی مامون کو اس طرح کی انوکھی چیزوں سے خاص دلچسپی تھی۔ اس کے کافی عرصہ بعد جب محمود بن سبکتگین نے ہندوستان فتح کیا اور ہندو کے معزز بت بدھ تک جا پہنچا جس کا قصہ مشہور اور تاریخ کا جزو ہے تو کم از کم محمود کو اس کا پتہ ہوتا، اور نہ کسی تاریخ کے قلم کار نے ہی اس رتن کا ذکر کیا ہے۔ اس کے بعد ذہبی فرماتے ہیں: پھر اس سب کے باوجود کہ اس نے اتنی لمبی عمر پائی، رات دن کی گردش اس پر آئی تا آنکہ چھٹی صدی کا آغاز ہو گیا۔ پھر بھی کوئی تاریخ اس کا وجود بتانے سے مہر بلب اور خاموش ہے نہ کسی سیاح نے اس کا ذکر کیا اور نہ کسی مسافر نے۔ اس جیسے شخص کے دعویٰ قبول کرنے کے لیے “خبر واحد” (ایک شخص کی اطلاع) کافی نہیں، لہذا اگر وہ ہوتا تو اس کے متعلق ہر تاجر کو خبر ہوتی اور جس کا یہ گمان ہے کہ اس نے اسے دیکھا ہے تو وہ اگر ان (بناوٹی) احادیث میں سے کچھ بھی نقل نہ کرتا تو یہ معاملہ زیادہ سنگین نہ ہوتا۔ پھر فرماتے ہیں: مجھے اپنی زندگی کی قسم! رتن کو وہی صحابی مانتا ہے جس کا غار میں روپوش محمد بن حسن پر ایمان ہے کہ وہ دنیا کی طرف نکل کر اسے عدل و انصاف سے بھر دیں گے۔ یا وہ شخص اس کے صحابی ہونے کا قائل ہوگا جو سیدنا علی میں اللہ کی رجعت پر ایمان رکھتا ہے، سو ایسے لوگوں کا کوئی علاج نہیں۔ ادھر محدثین کا اس پر اتفاق ہے کہ سب سے آخر میں جس صحابی نے وفات پائی اور انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہوا تھا وہ ابو الطفیل عامر بن واثلہ ہیں۔ اور صحیح کی یہ روایت ثابت ہے کہ آپ صلی اللہ علیہ وسلم نے وفات سے مہینہ پہلے فرمایا: “تمہیں بتاؤں تمہاری آج کی یہ رات کیسی ہے؟ آج رات جو شخص موجود ہے وہ اس صدی کی انتہاء تک زمین پر باقی نہیں رہے گا۔ تو بات ختم ہوئی۔ اب حق کے بعد گمراہی ہی رہ جاتی ہے۔ یہاں تک ذہبی کی رتن کی خبر کے بت توڑنے کی بات مختصر مکمل ہوئی۔\nمجھے وہ جز مل گیا ہے جس کی طرف انہوں نے اشارہ کیا ہے، اس میں تین سو سے زائد (من گھڑت) احادیث ہیں۔ اس کے بعد مجھے اس کا ایک اور طریق معلوم ہوا، ہمیں کئی لوگوں نے مدینہ منورہ فروکش ہونے والے سیاح اور کثرت سے روایات بیان کرنے والے محدث جمال الدین اقشہری کے حوالہ سے بتایا انہوں نے علی بن عمران صنعانی سے انہوں نے رفیع الدین سے انہوں نے عمر بن محمد بن ابی بکر سمرقندی سے کہ انہوں نے صنعاء کی جامع مسجد میں چوراسی (۸۴ھ) میں بحوالہ ابو الفتح موسیٰ بن مجتبی اپنے الفاظ میں بیان کیا، پھر پورا نسخہ ذکر کیا۔ اربلی مذکور کے نسخہ میں ہے کہ رتن نے کہا: میں سیدہ فاطمہ رضی اللہ عنہا کی رخصتی میں کئی صحابہ کے ساتھ تھا، وہاں ایک گویا تھا، جس سے ہمارے دل خوش ہوئے اور ہم لوگ ان کے دف بجانے پر ناچنے لگے۔ انہوں نے شعر بھی کہے: اگلے روز ہم نے رسول اللہ صلی اللہ علیہ وسلم سے اپنی رات کے بارے میں پوچھا کہ ہم فاطمہ رضی اللہ عنہا کی رخصتی میں تھے۔ آپ نے ہمیں دعا دی اور ہم پر نکیر نہیں کی۔\nمیں نے مورخ شمس الدین محمد بن ابراہیم جزری کی تاریخ میں انہی کے قلم سے لکھا دیکھا ہے کہ میں نے نجیب عبد الوہاب بن اسمعیل فارسی صوفی سے مصر میں سات سو بارہ (۷۱۲ھ) میں سنا کہ چھ سو پچھتر (۶۷۵ھ) میں ہمارے پاس شیراز میں بابا رتن کا بیٹا محمود آیا اس نے ہمیں بتایا کہ اس کے باپ نے شق قمر کی رات دیکھی ہے، یہی اس کی ہجرت کا سبب بنا اور وہ خندق کی کھدائی میں شریک تھا۔ اس کے پاس ایک زنبیل تھی جس میں املی تھی جو رسول اللہ صلی اللہ علیہ وسلم کو ہدیہ میں پیش کی۔ آپ صلی اللہ علیہ وسلم نے وہ املی کھائی اور رتن کی پیٹھ پر ہاتھ رکھا اور اسے لمبی عمر کی دعا دی۔ اس وقت اس کی عمر سترہ(۱۷) سال تھی پھر اپنے علاقہ میں واپس آ گیا اور چھ سو بتیس (۶۳۲ھ) تک زندہ رہا اور اسی سال وفات ہوئی۔ پھر اس کے حوالہ سے اس نے احادیث ذکر کیں جو اس نے اپنے والد سے بحوالہ نبی صلی اللہ علیہ وسلم سے سنی تھیں۔ پھر نجیب نے کہا کہ محمود نے ذکر کیا تھا کہ اس کی عمر ایک سو ستر(۱۷۰) سال ہے۔ نجیب کہتا ہے: پھر ہمارے پاس شیراز سے قاہرہ کچھ لوگ آئے اور مجھے بتایا کہ وہ ابھی زندہ ہے، اس کی کئی اولاد ہے۔ اس کا قصہ میں نے ایک اور سند سے طویل لکھا ہوا فاضل ادیب صلاح الدین صفدی کے قلم سے اس کے تذکرہ میں پڑھا ہے کہ مجھے کئی لوگوں نے بالمشافہ (زبانی) بتایا کہ انہوں نے فاضل ادیب علاء الدین الوداعی کے تذکرہ میں پڑھا ہے۔\nمیں کہتا ہوں: ہمیں علی بن محمد بن ابی المجد نے بالمشافہ بحوالہ الوداعی بتایا کہ ہمیں جلال الدین محمد بن سلیمان دمشق کے دار السعادہ کے کاتب نے بتایا کہ ہمیں قاضی القضاۃ نور الدین علی بن محمد الحسینی الحنفی نے قاہرہ میں سات سو ایک (۷۰۱ھ) میں خبر دی، فرماتے ہیں: ہمیں کئی لوگوں نے بالمشافہ امام علامہ شمس الدین محمد بن عبد الرحمن بن الصائغ الحنفی کی ہمیں قاضی معین الدین عبد المحسن بن قاضی جلال الدین عبد اللہ بن ہشام نے سات سو سینتیس (۷۳۷ھ) بتایا کہ مجھے قاضی نور الدین بتاتے ہیں کہ مجھے میرے دادا حسین بن محمد نے یہ روایت سنائی کہ بچپن میں جب میری عمر سترہ سال تھی، اس وقت میں نے اپنے والد اور چچا کے ہمراہ خراسان سے ہندوستان کا تجارتی سفر کیا۔ جب ہم ہندوستان کے ابتدائی شہروں میں پہنچے چلتے چلتے ہم ایک جاگیر میں جا نکلے، اس کی جانب لوگ پلٹ رہے ہیں اور وہاں جا کر پڑاؤ کر لیا۔ قافلہ والوں نے چیخ کر کہا، ہم نے لوگوں سے اس کے متعلق دریافت کیا وہ بتانے لگے: یہ عمر رسیدہ رتن کی جاگیر ہے۔ جب ہم لوگوں نے جاگیر سے باہر پڑاؤ کیا تو ہمیں اس کے صحن میں ایک بڑا درخت نظر آیا جس کا سایہ بہت سے لوگوں پر پڑ رہا تھا اور اس کے نیچے اسی جاگیر کے بہت سے افراد تھے، اتنے میں سب لوگ اس درخت کی طرف بڑھے ہم بھی ان بھی ان کے ساتھ تھے۔ جب ان لوگوں نے ہمیں آتے دیکھا تو خوش آمدید کہا، ہم نے وہاں ایک بہت بڑی زنبیل درخت کے کسی ڈال سے لٹکی دیکھی، ہم نے ان لوگوں سے پوچھا، انہوں نے بتایا: اس زنبیل میں بابا رتن ہے جس نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ہے اور آپ نے اس کے لیے لمبی عمر کی چھ بار دعا کی ہے۔ ہم نے ان سے کہا: ان بابا جی کو اتاریں تا کہ ہم ان کی گفتگو سن سکیں، ان میں سے ایک بزرگ شخص آگے بڑھا اور زنبیل جو ایک چرخی کے ذریعہ لٹکی ہوئی تھی نیچے اتاری۔ ہم نے جھانک کر دیکھا وہ روئی سے بھری ہوئی تھی اور وہ بابا جی روئی کے بیچ میں پڑے تھے۔ زنبیل کا منہ کھولا، بڑھاپے کی وجہ سے وہ بزرگ چوزہ لگ رہے تھے۔ اس شخص نے ان کے چہرے سے روئی ہٹائی اور اپنا منہ اس کے کان پر رکھ کر کہنے لگا: دادا جان! یہ چند لوگ خراسان سے آئے ہیں، ان میں اولاد نبی صلی اللہ علیہ وسلم کے شریف زادے بھی ہیں ان کی درخواست ہے کہ آپ ان سے بیان کریں کہ آپ نے رسول اللہ صلی اللہ علیہ وسلم کو کیسے دیکھا اور انہوں نے آپ سے کیا فرمایا تھا؟ اس وقت اس نے سانس لی اور شہد کی مکھی کی بھنبھناہٹ کی طرح فارسی میں گفتگو کی، ہم لوگ سن رہے تھے اور سمجھ بھی رہے تھے۔ اس نے کہا: میں نے اپنے والد کے ساتھ جب میری جوانی کی عمر تھی ان شہروں سے حجاز کا تجارتی سفر کیا جب ہم مکہ کی کسی وادی میں پہنچے، بارش اتنی ہوئی کہ وادی لبالب پانی سے بھر گئی۔ مجھے گندمی رنگ، رعنا اور اچھے قد و قامت والا ایک لڑکا نظر آیا جو اونٹ چرا رہا تھا۔ سیلاب اس کے اونٹوں کے درمیان حائل ہو گیا۔ وہ پانی میں گھنے سے ڈر رہا تھا۔ کیونکہ پانی بڑی تیزی سے چھل مارتا بہہ رہا تھا۔ میں نے اس کی کیفیت بھانپ لی۔ اس کے پاس آیا اور اسے اٹھا کر پانی میں گھس گیا اور اس کے اونٹ کی طرف آ گیا، حالانکہ میری اس سے پہلے سے جان پہچان نہ تھی۔ میں نے جب اسے اس کے اونٹوں کے پاس پہنچا دیا تو اس نے میری طرف دیکھ کر کہا: بارک اللہ فی عمرک، بارک اللہ فی عمرک، بارک اللہ فی عمرک۔ اس کے بعد میں اسے چھوڑ کر اپنے راستہ پر چل پڑا اور مکہ داخل ہوئے اور وہاں جو ہماری تجارتی ضروریات تھیں پوری کیں، اور پھر اپنے وطن واپس آ گئے۔ جب اس واقعہ کو کافی عرصہ بیت گیا تو ایک رات ہم اپنی اسی جاگیر میں بیٹھے تھے، چاندنی رات تھی، ہم نے چودھویں کے چاند کو آسمان پر دیکھا کہ وہ یکا یک دولخت ہو گیا، اس کا ایک ٹکڑا مشرق میں اور دوسرا مغرب میں چھپ گیا۔ اسی گھڑی یہ سب کچھ ہوا اور رات پوری طرح تاریک ہو گئی۔ پھر چاند کا ایک ٹکڑا مشرق سے اور دوسرا مغرب سے طلوع ہوا اور آسمان کے درمیان میں دونوں ٹکڑے آ کر جڑ گئے، جیسے پہلے تھے۔ ہمیں اس سے بہت تعجب اور حیرت ہوئی، لیکن ہمیں اس کا سبب معلوم نہ ہو سکا۔ ہم نے مسافروں سے اس کے بارے میں پوچھا، وہ بتانے لگے کہ ایک ہاشمی شخص جو مکہ میں ظاہر ہوا ہے اور نبوت کا دعویٰ کیا ہے کہ وہ کل عالم کے لئے اللہ کا رسول ہے۔ اہل مکہ نے اس سے باقی انبیاء کی طرح معجزہ مانگا ہے، انہوں نے اس سے کہا کہ وہ چاند کے دو ٹکڑے کر کے دکھا دے، جس کا آدھا حصہ مشرق میں اور آدھا مغرب میں غروب ہو جائے، پھر اپنی حالت پر لوٹ آئے۔ چنانچہ اس نے اللہ کی قدرت سے ایسا کر دکھایا۔ ہم نے جب مسافروں سے یہ بات سنی تو مجھے مذکورہ شخص کے دیکھنے کا اشتیاق ہوا، میں نے سامان تجارت تیار کیا اور سفر کرتے کرتے مکہ جا پہنچا، موصوف کے بارے میں میں نے پوچھا تو لوگوں نے مجھے اس کی جگہ بتائی، میں اس کے گھر آیا، اندر آنے کی اجازت مانگی، اس نے مجھے اجازت دے دی۔ میں اس کے پاس پہنچا تو وہ گھر کے درمیان میں بیٹھا ہوا تھا، اس کا چہرہ انوارات سے چمک رہا تھا۔ اور اس کے وہ محاسن ظاہر ہو چکے تھے۔ اور اس کی وہ علامتیں جو میں نے پہلے سفر میں دیکھی تھیں بدل چکی تھیں، میں اسے پہچان نہ سکا، میں نے جب اسے سلام کیا تو اس نے میری طرف دیکھ کر تبسم کیا، اور مجھے پہچان لیا۔ کہنے لگا: تم پر سلام ہو، قریب ہو جاؤ۔ اس کے سامنے کھجوروں کی ایک طشتری پڑی تھی، اور اس کے آس پاس اس کے ساتھیوں کی ایک جماعت تھی، جو اس کی عزت و توقیر کر رہی تھی، میں اس کی یہ کیفیت دیکھ کر ہیبت زدہ ہو کر کھڑا ہو گیا۔ وہ مجھے کہنے لگا: “ہمارے ابا جان! قریب ہو جائیں اور کھائیے۔ موافقت و اتفاق مروت ہے جبکہ منافقت زندقہ کی علامت ہے۔ چنانچہ میں آگے ہو کر بیٹھ گیا اور ان کے ساتھ بیٹھ کر کھجوریں کھانے لگا۔ وہ اپنے مبارک ہاتھ سے مجھے کھجور دینے لگا، اس نے مجھے چھ کھجوریں دیں اس کے علاوہ کئی کھجوریں میں نے خود اپنے ہاتھ سے کھائیں۔ پھر وہ میری طرف دیکھ کر مسکرایا اور کہنے لگا: آپ نے مجھے پہچانا نہیں؟ میں نے کہا: میں پہچان نہیں سکا۔ اس نے کہا: کیا آپ نے مجھے فلاں سال اٹھا کر سیلاب سے پار نہیں کیا تھا، جب پانی میرے اور میرے اونٹوں کے درمیان حائل ہو گیا تھا؟ تو میں نے اسے ایک علامت سے پہچان لیا۔ میں نے کہا: جی ہاں، اے بارونق چہرے والے! پھر اس نے مجھے کہا: اپنا ہاتھ بڑھائیے! تو میں نے اپنا دایاں ہاتھ آگے کیا تو اس نے اپنے دائیں ہاتھ سے مجھ سے مصافحہ کیا اور مجھ سے کہا، کہو: اشہد ان لا الہ الا اللہ و اشہد ان محمدا رسول اللہ، تو جیسا اس نے مجھے سکھایا میں نے کہہ دیا۔ جس سے اسے بہت خوشی ہوئی۔ جب میں اس کے پاس سے واپس آنے لگا تو اس نے مجھے کہا: بارک اللہ فی عمرک، بارک اللہ فی عمرک، بارک اللہ فی عمرک۔ اس کے بعد میں خوشی خوشی اس کی ملاقات اور اسلام کے ساتھ اس سے رخصت ہوا، یوں اللہ تعالیٰ نے اپنے نبی کی دعا قبول کی اور ہر دعا کے بدلہ میری عمر میں سو سال کا اضافہ کیا اور اب میری عمر چھ سو سال سے زیادہ ہے اور اس جاگیر میں جتنے افراد ہیں، میرے بیٹے اور پوتے ہیں جنہیں اللہ تعالیٰ نے ہر طرح کی خیر و برکت، نعمت و سہولت، رسول اللہ صلی اللہ علیہ وسلم کی برکت کے ذریعہ عطا کی ہے۔\nمجھے ذہبی کی رتن سے مروی ذکر کردہ روایات کے علاوہ اور روایات بھی ملی ہیں۔ ان میں سے ایک روایت “کتاب الوحید فی سلوک اہل طریق التوحید” میں ملی ہے، جو شیخ عبد الغفار بن نوح القوصی کی تالیف ہے۔ میری ان کے پوتے شیخ عبد الغفار بن احمد بن عبد الغفار سے ملاقات ہوئی ہے، وہ اپنے والد کے والد کے واسطہ سے بحوالہ اپنے دادا روایت کرتے ہیں کہ مجھ سے شیخ محمد عجمی نے بیان کیا، میں کمال الدین شیرازی کی صحبت میں رہا ہوں، ان کی عمر ایک سو ساٹھ(۱۶۰) سال ہو گئی تھی۔ وہ فرماتے ہیں: میں رتن الہندی کی صحبت میں رہا، انہوں نے بتایا کہ وہ خندق کی کھودائی میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ اس سند سے عبد الغفار بن نوح لکھتے ہیں کہ مجھ سے شیخ عماد الدین السکری خطیب جامع الحاکم نے بواسطہ شیخ اسمعیل فاروقی بحوالہ خواجہ رتن الہندی بیان کیا، پھر ایک حدیث ذکر کی۔\nبھاء الجندی تاریخ یمن میں رقمطراز ہیں، میں نے شیخ حسن بن عمر بن محمد بن علی بن ابی القاسم الحمیری کے قلم سے لکھا دیکھا کہ مجھے شیخ عالم محدث ابو الحسن علی بن شعیب بن اسمعیل بن الحسن الواسطی نے بواسطہ شیخ صالح فقیہ داؤد بن اسعد بن حامد القفال المحروری نے صعید مصر کے گاؤں میں بیان کیا جس کا نام “اسیوط” تھا کہ میں نے عمر رسیدہ رتن بن میدن بن مندی سے سنا جو سندھی صراف زرگر تھے کہ ابتداء میں، میں بت پوجتا تھا، میں نے خواب میں ایک شخص کو کہتے دیکھا: اس کے علاوہ اپنے لیے کوئی دین تلاش کرو۔ میں نے پوچھا: کہاں سے؟ اس نے کہا: شام میں، چنانچہ میں شام چلا گیا، وہاں کے لوگوں کو دین نصرانیت پر کار بند پایا، ایک مدت تک میں نصرانی رہا۔ پھر مدینہ میں نبی صلی اللہ علیہ وسلم کی شنید ہوئی تو ان کے پاس آ کر اسلام لے آیا۔ آپ صلی اللہ علیہ وسلم نے میرے لیے لمبی عمر کی دعا فرمائی، اور میرے سر پر اپنا دست مبارک پھیرا۔ پھر میں نے ان کے ساتھ یہود کے ساتھ جنگ میں شرکت کی۔ واپسی کے بعد میں نے ان سے اپنے شہر جانے کی اجازت چاہی، آپ صلی اللہ علیہ وسلم نے اجازت دے دی کیوں کہ میری والدہ زندہ تھی۔ راوی کا بیان ہے کہ اس کے علاقہ کے لوگوں سے مسلسل یہ اطلاع ملتی رہتی تھی کہ وہ نبی صلی اللہ علیہ وسلم کی دعا کی برکت سے سات سو سال کا ہو گیا ہے اور اس کا انتقال رجب چھ سو آٹھ (۷۰۸ھ) میں ہوا ہے۔ لکھتے ہیں: یمن میں ایک عمر بن محمد بن ابی بکر سمرقندی نامی شخص آیا۔ اس نے بواسطہ ابو الفتح موسیٰ بن مجتبی دنیسیری بحوالہ ابو الرضا رتن بن نصر بن کربال روایت کی۔\nمیں کہتا ہوں: میں نے عمر بن محمد ہاشمی کے قلم سے بحوالہ شیخ حسین بن عبد الرحمن بن محمد بن علی بن ابی بکر یمانی لکھا دیکھا ہے کہ شیخ علی بن ابی بکر الازرق نے اجازہ ہمیں بتایا کہ ابراہیم بن محمد بن عیسی بن مطیر نے اپنے والد سے انہوں نے محمد بن عمرو بن علی التباعی تنقیہ سے انہوں نے اپنے والد سے کہ ہم سے شریف موفق الدین علی بن محمد خراسانی نے جن کا تعلق ہرات سے تھا، ذی قعدہ چھ سو سترہ (۶۱۷ھ) مخلاف میں بیان کیا جو شاور کا ایک شہر ہے کہ میں جمادی الاولی ۲۰۱ھ میں ہندوستان آیا، مجھے دہلی کے قریب ایک گاؤں میں عمر رسیدہ شخص کے بارے میں بتایا گیا جس نے نبی صلی اللہ علیہ وسلم کا زمانہ پایا ہے۔ تو میں ملاقات کی غرض سے اُدھر چل نکلا۔ میرے ساتھ مغرب کا ایک آدمی تھا، جب ہم لوگ اس کے پاس پہنچے اسے سلام کیا تو اس نے مجھ سے پوچھا کہ میں کہاں کا رہنے والا ہوں؟ میں نے کہا: میں حسین بن علی رضی اللہ عنہ کی اولاد سے خراسان کا رہنے والا ہوں اور ہرات سے میرا تعلق ہے، اور یہ صاحب مغرب کے ہیں۔ اس نے کہا: کتنے تعجب کی بات ہے میں نے تمہارے نانا رسول اللہ صلی اللہ علیہ وسلم کو اپنے کندھوں پر اٹھایا تھا۔ میں نے پوچھا: بابا جی! آپ کی کتنی عمر ہے؟ اس نے کہا: سات سو سال، میں نے کہا: تب تو آپ نبی صلی اللہ علیہ وسلم سے بھی پہلے زمانہ کے ہوئے۔ اس نے کہا: ہاں، میں عیسیٰ علیہ السلام کی قوم کا آدمی ہوں۔ میں نے نبوت سے پہلے رسول اللہ صلی اللہ علیہ وسلم کو اٹھایا تھا، جب آپ لڑکپن کے زمانہ میں تھے۔ میں نے پوچھا: اس کا اتفاق کیسے ہوا؟ اس نے کہا: میں نے سنا ہوا تھا کہ حجاز میں محمد نامی نبی ہوں گے جو خاتم النبیین ہوں گے، چنانچہ میں نے تین بار بحری سفر کیا، ہر بار جہاز ٹوٹ کر غرق ہو جاتا، پھر چوتھی بار سوار ہو کر میں جدہ پہنچ گیا، سمندر سے باہر نکلا۔ ابھی جدہ اور مکہ کے درمیانی علاقہ میں تھا کہ بارش ہونے لگی اور اتنی بارش ہوئی کہ وادی بہہ پڑی، مجھے ایک لڑکا ملا جس کے ساتھ اونٹ تھے اونٹ اس وادی سے آگے نکل چکے تھے۔ وہ لڑکا اس وادی کو عبور نہ کر سکا، میں نے اسے اٹھایا اور نہر سے پار چھوڑ دیا اس نے مجھ سے تین بار کہا: “بارک اللہ فی عمرک” پھر میں مکہ میں داخل ہوا اور کچھ مدت وہیں قیام کیا لیکن مجھے نبی صلی اللہ علیہ وسلم کے بارے کوئی خبر نہ ملی۔ واپس اپنے شہر آ گیا، جہاں تین یا اکتالیس برس قیام کیا پھر مجھے نبی محمد صلی اللہ علیہ وسلم کے بارے معلوم ہوا کہ وہ مدینہ منتقل ہو گئے ہیں تو پانچویں بار بحری سفر پر روانہ ہو کر مدینہ پہنچ گیا۔ مسجد میں داخل ہوا اور نبی صلی اللہ علیہ وسلم کو مسجد کی محراب میں بیٹھے دیکھا میں نے سلام کیا اور بیٹھ گیا آپ نے مجھ سے فرمایا: بابا جی! آپ کہاں سے تشریف لائے ہیں؟ میں نے عرض کی: ہندوستان سے، آپ نے فرمایا: آپ نے ہی مجھے جدہ اور مکہ کے درمیان اٹھایا تھا جب بچپن میں، میں اپنے اونٹوں کے ساتھ تھا؟ میں نے عرض کی: جی ہاں۔ آپ نے فرمایا: اللہ تعالیٰ آپ کی عمر میں برکت عطا فرمائے۔ پھر میں مسلمان ہو گیا اور بارہ دن آپ کے پاس مقیم رہا آپ کے ساتھ کھانا کھایا اور اپنے شہر آ گیا اور اس درخت کے نیچے قیام کر لیا یہ قوقل کا درخت ہے۔\nراوی کا بیان ہے کہ پھر اس نے ہمارے لئے کھانے کا حکم دیا اور ہمارے ساتھ تین لقمے کھائے۔ کہنے لگا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے! موافقت مروت کا حصہ ہے جبکہ نفاق باہمی زندقہ کا جزء ہے، راوی کہتا ہے مجھے اس کے دانت گرگٹ کی طرح باریک اور داڑھی کانٹے کی طرح (بال بال) نظر آئی اس میں زیادہ تر بال سفید تھے اس کی ابروئیں اس کی آنکھوں اور رخساروں پر پڑی ہوئی تھیں جنہیں وہ آنکڑے سے اٹھاتا تھا، وہ کہتا ہے میں نے شریف سے پوچھا: کیا بابا جی کی کوئی اولاد ہے؟ اس نے کہا: میں نے بھی ان سے پوچھا تھا۔ انہوں نے کہا: کہ انہوں نے کبھی شادی نہیں کی سوائے ایک بار جاہلیت میں انہیں کبھی احتلام نہیں ہوا۔ شریف نے کہا: میں طلوع شمس سے لے کر عصر تک ان کے ساتھ رہا ہوں ان کے بیٹھنے کی ہیئت کی لمبائی تین ذراع (گز) ہے۔ اور ان کا انتقال چھ سو بارہ (۶۱۲ھ) میں ہوا۔\nمیں نے جندی کی “تاریخ یمن” میں پڑھا ہے۔ ان میں سے ایک واقعہ وہ ہے جو مجھے کثرت سے سفر کرنے والے محدث جمال الدین محمد بن احمد بن امین الشہری نزیل مدینہ کے حوالہ سے ان کے فوائد سے منقول بیان کی گئی ہے کہ ابو الفضل اور ابو القاسم بن ابی عبد اللہ علی بن ابراہیم بن عتق اللوانی جو ابن الخباز محمدی کے نام سے مشہور ہیں ہیں شوال سات سو دس(۷۱۰) میں ملک تیونس میں بتایا کہ میں نے ابو عبد اللہ محمد بن علی بن محمد بن یعلی مغربی تلمسانی سے اسکندریہ کی سرحد پر رمضان کے مہینہ چھ سو چھیاسی (۶۸۲ھ) میں سنا فرمایا: میں نے عمر رسیدہ ابو بکر المقدسی سے سنا۔ اس وقت ان کی عمر تین سو سال ہو گئی تھی۔ ان کے الفاظ میں ہندوستان کے شہر سومنات میں سلطان محمود بن سبکتگین کی مسجد میں رجب چھ سو باون (۶۵۲ھ) کو فرماتے سنا کہ ہم سے عمر رسیدہ بزرگ خواجہ رتن بن عبد اللہ اپنے گھر شہر تو بندہ میں اپنے الفاظ میں بیان کیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: آخری زمانہ میں اللہ تعالیٰ کا عسقلان کی جانب سے ایک لشکر ہوگا جو ترک ہوں گے۔ جو ان سے جنگ کے ارادہ سے لڑنے آئے گا وہ اسے شکست دے دیں گے اور جس کا یہ رخ کریں گے اسے مغلوب کر لیں گے فرماتے ہیں! خواجہ رتن بن عبد اللہ نے بیان کیا: کہ وہ خندق میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے اور ان سے حدیث کا سماع کیا اور پھر ہندوستان کے شہر واپس آ گئے۔ وہیں ان کا انتقال ہوا وہ سات سو سال زندہ رہے اور پانچ سو چھیانوے (۵۹۶ھ) میں انتقال کیا۔ قشری کا قول ہے: اس سند کو بابرکت سمجھا جاتا ہے۔ اگر چہ اس کے صحابی ہونے کا اعتماد نہیں۔ پھر اشعری لکھتے ہیں: ہمیں فقیہ ابو القاسم بن عمر بن عبد العالی کنانی غم تونسی نے بتایا کہ میں نے شیخ نجم الدین عبد اللہ بن محمد بن محمد اصبہانی کو فرماتے سنا کہ میں نے عبد اللہ بن بابا رتن سے سنا وہ فرماتے ہیں: میں نے اپنے والد بابا رتن کو فرماتے سنا: جو لا الہ الا اللہ وحدہ لا شریک لہ کہتا ہوگا وہ جنت میں داخل ہوگا۔ اشعری کی ہی سے مروی ہے کہ ابو زید عبد الرحمن بن علی الجزائری نے ہمیں بتایا کہ مجھے علی بن احمد بن عبد الرحمن بن حدیدی نے بتایا کہ میں نے مالقہ سے غرناطہ کا سفر کیا جہاں میری ملاقات احمد بن محمد بن حسین جذامی سے ہوئی فرمایا: میں محمد بن بکروں بن ابی مروان عبد الملک بن بشر سے ملا فرمایا: مجھ سے محمد بن زکریا بن براطن تمیمی نے کہا: کہ جب عمر رسیدہ شخص کی خبریں اور ابو مروان کی اس سے ملاقات کے حالات کثرت سے سننے میں آئے تو وادی آش سے گزرا جہاں رجب چھ سو اکسٹھ (۶۶۱ھ) میں ابو مروان مل گئے میں نے ان سے عمر رسیدہ شخص کے متعلق پوچھا وہ بتانے لگے: میں اندلس سے چھ سو سترہ (۶۱۷ھ) میں نکلا اور بالآخر مکہ مکرمہ پہنچ گیا۔ جہاں میں نے سات سال قیام کیا ادھر ہی عمر رسیدہ شخص کی اطلاع سنی جو بہت مشہور تھی۔ پھر کسی نے مجھے بتایا کہ وہ فلاں علاقہ میں ہے تو میں کش کی جانب اترا تو اس خبر کے آثار مضبوطی سے ملنے لگے۔ پھر ایک اور شہر پہنچا، لوگوں نے بتایا یہ راستہ ممنوع ہے کیونکہ یہ ایک لق و دق صحرا ہے جس کی مسافت پینتالیس ایام کی ہے۔ میری عادت تھی کہ میں کئی کئی دن بن کھائے پیے گزار دیتا تھا۔ میں نے اس صحرا میں چلنے کا عزم کر لیا۔ پھر کسی نے بتایا کہ ایک راستہ اس سے بھی قریب کا ہے لیکن تاتاریوں کی وجہ سے اس میں کوئی نہیں چلتا مجھے وہ آسان لگا اور میں اس پر چل نکلا۔ مجھ سے کوئی بات کرتا تو میں اس کی بات کا جواب نہ دیتا بلکہ میں پختہ عزم کا اظہار کرتا نہ کھاتا نہ پیتا تھا۔ تاتاریوں کے لشکر میں میں چھ دن اسی حالت میں چلا۔ پھر ان سے علیحدہ ہو گیا۔ دو دن اور چل کر میں اپنے مقام مقصود تک جا پہنچا۔ وہاں کے لوگوں کو مجھ پر بڑا تعجب ہوا۔ انہی میں سے ایک بزرگ نے میری ضیافت و مہمان نوازی کی۔ وہ اپنے گھر لے گیا وہاں ایک عمر رسیدہ شخص روئی میں لپٹا ہوا تھا جو ایک پنگھوڑے میں تھا اس نے اسے آواز دے کر کہا: میرے آقا یہ شخص مغرب اقصی کے دور دراز کے کسی علاقہ سے آیا ہے، اس کا مقصد صرف آپ کی زیارت کرنا ہے اور آپ کی بات سننا ہے۔ پھر اس نے مجھ سے اپنی زبان میں بات کی جس کا ترجمہ اس شخص نے کر کے مجھے بتایا کہنے لگا: خندق کی کھدائی میں، میں مسلمانوں کے ساتھ مل کر کام کر رہا تھا۔ اس وقت میری عمر چودہ سال تھی۔ میں نے جب آپ صلی اللہ علیہ وسلم کو دیکھا تو میرے دل میں کام کی کوئی تھکان نہ رہی آپ نے جب میری کیفیت دیکھی تو فرمایا: اللہ تعالیٰ تمہیں عمر بخشے، اللہ تعالیٰ تمہیں عمر بخشے، اللہ تعالیٰ تمہیں عمر بخشے، پھر وہ بابا جی خاموش ہو گئے۔ اس کے بعد مجھ سے وہ شخص کہنے لگا جو اس کے پاس لے کر گیا تھا: کافی ہے۔ پھر اشعری نے اسی مفہوم کا قصہ دو اور سندوں سے بیان کیا ہے اس میں عمر رسیدہ شخص کا نام عمار بتایا ہے جس کا تذکرہ میں حرف عین میں ان شاء اللہ تعالیٰ کروں گا۔ صلاح صفدی نے اپنے “تذکرہ” میں رتن کے وجود کی تقویت کے لئے کلام کیا ہے اور ان لوگوں پر نکیر کی ہے جو اس کے باوجود اس کے منکر ہیں۔ اور اس سلسلہ میں صرف عقلی جواز پیش کیا ہے حالانکہ اس میں کسی کا اختلاف نہیں۔ اختلاف ہے تو شرعی وہ بھی صحیحین کی صدی والی حدیث ثابت ہونے کے بعد یہ وہی استبعاد اور ناممکن بات ہے جس کا حوالہ ذہبی نے دیا ہے۔\nقاضی برھان الدین بن جماعہ نے اپنی کتابوں کے حاشیہ میں تذکرہ صفدی کا تعاقب کیا ہے لکھا ہے کہ ہمارے شیخ ذہبی کا قول ہی برحق ہے اور جو جواز صفدی نے پیش کیا ہے اس سے لازم نہیں آتا ہے کہ وہ واقعہ حقیقتا ہی ہوا ہو اس لئے کہ ہر جائز چیز کا واقع ہونا اور پیش آنا ضروری نہیں۔\nہمارے شیخ مجد الدین شیرازی جو یمن کے شہر زبید کے شیخ المحدث ہیں سے میری ملاقات ہوئی۔ اس وقت وہ یمن کے شہروں کے چیف جسٹس تھے۔ میں نے دیکھا کہ وہ ذہبی پر رتن کے انکار کی وجہ سے نکیر کر رہے تھے اور مجھ سے ذکر کیا کہ وہ اس کی جاگیر میں داخل ہوئے تھے جب ان کا ہندوستان جانا ہوا تھا وہاں اتنی تعداد میں لوگ اپنے آباء و اجداد سے “رتن” کا قصہ نقل کرتے ہیں جن کا اعداد و شمار نہیں۔ وہ اس کے وجود کو ثابت کرتے ہیں۔ میں نے ان سے کہا: انہوں نے یقین سے اس کے وجود کا انکار نہیں کیا بلکہ انہیں اس کے بارے میں تردد تھا اس لئے وہ معذور ہیں۔ جہاں تک میرا خیال ہے اس کی عمر طویل ہوئی ہوگی جس پر جو دعوے اس نے کیے سو کیے۔ اور انہیں پر ڈٹ گیا یہاں تک کہ اس کی شہرت ہو گئی اگر وہ سچا ہوتا تو اس کی شہرت دوسری، تیسری، چوتھی یا پانچویں صدی میں ہوتی لیکن اس کی جتنی باتیں بھی منقول ہیں وہ چھٹی صدی کے اخیر کی ہیں یا پھر ساتویں صدی کے آغاز کی ہیں وہ بھی اس کی وفات سے پہلے۔ اس کے سن وفات میں اختلاف ہے جیسا کہ پہلے گزر چکا ہے۔ واللہ تعالیٰ اعلم","",{"fn":"(1) تذکرۃ الموضوعات للفتنی (۱۰۳)\n(2) تذکرۃ الموضوعات (۱۹۲)\n(3) تذکرۃ الموضوعات (۱۷۶)\n(4) الفوائد المجموعہ (۲)\n(5) الفوائد المجموعہ (۴۴۰)"}],[2755,"§۲۷۶۲ ۔ بے نام صحابی\nابن حزم کا دعویٰ ہے کہ یہ ان کا علم ہے ان کے گھر والوں نے ان کا یہی نام رکھا ہے۔ پھر لکھتے ہیں، یہ مشہور صحابی ہیں۔ اس بات کو انہوں نے اپنی کتاب المحلی کے اس باب میں ذکر کیا ہے۔ “باب: جو اللہ اور اس کے رسول کو برا کہے” اس سلسلہ میں ان کی معتمد روایت وہ ہے جو بطریق محمد بن عبد الملک بن ایمن بواسطہ حبیب بخاری شاگرد ابو نور محمد بن سہل سے نقل کی فرماتے ہیں: میں نے علی بن المدینی کو فرماتے سنا: پھر انہوں نے مامون کے ساتھ اپنا قصہ ذکر کیا جس میں نبی صلی اللہ علیہ وسلم کو گالی دینے والے کا تذکرہ ہے۔ اس قصہ میں انہوں نے بلقین کے ایک شخص کی حدیث نقل کی علی فرماتے ہیں: وہ شخص اسی نام سے مشہور ہے یہی شخص آپ علیہ السلام کے پاس جا کر بیعت ہوا تھا۔\nمیں کہتا ہوں: محمد بن سہل کو میں نہیں جانتا۔ محمد بن سہل عطار کے طبقہ میں شامل لوگوں پر دار قطنی نے وضع کا الزام لگایا ہے فرماتے ہیں: اس نے ابن حزم سے مباحثہ کیا پھر جہاد میں حدیث عبد اللہ بن شقیق بحوالہ بلقین کے ایک شخص نقل کی کہ میں نے عرض کی: اللہ کے رسول! کیا کوئی مقیم سے بڑھ کر کسی چیز کا زیادہ حقدار ہے؟ آپ نے فرمایا: نہیں۔ حدیث۔ ابن حزم نے کہا: یہ روایت ایک نا معلوم شخص سے مروی ہے ہمیں معلوم نہیں وہ اپنے صحابی ہونے کے دعوئی میں سچا ہے یا نہیں؟"],[2756,"§۲۷۶۳ ۔ رجال ابن عنقوہ الحنفی\nعبد الغنی نے یہ نام حات قلمبند کیا ہے۔ امین لکھتے ہیں: اکثر کا قول یہ ہے کہ یہ نام جیم سے رجال ہی ہے۔ ابن ابی حاتم(1) نے ان کا ذکر کر کے کہا: کہ بنی حنیفہ کے وفد میں نبی علیہ السلام کے پاس آئے۔ وہ لوگ دس سے زیادہ افراد تھے سب کے سب مسلمان ہو گئے، میں نے یہ بات اپنے والد سے سنی ہے۔\nمیں کہتا ہوں: لیکن یہ شخص مرتد ہو گیا تھا اور کفر پر ہی مرا تھا چنانچہ الفتوح میں سیف بن عمر نے مخلد بن قیس بجلی کے حوالہ سے روایت کی ہے نبی صلی اللہ علیہ وسلم کے پاس سے فرات بن حیان، رجال بن عنقوہ اور ابو ہریرہ باہر نکلے، آپ علیہ السلام نے فرمایا: “ان (جہنمیوں) کی جہنم میں داڑھ اُحد سے بڑی ہوگی اور اس کے ساتھ ایک غدار کی گدی ہے، یہ بات انہیں پہنچ گئی اور بالآخر رجال کے قتل ہونے کی خبر ابو ہریرہ اور فرات کو بھی معلوم ہو گئی تو وہ دونوں حضرات سجدہ شکر بجا لانے کے لئے جھک گئے امام واقدی بحوالہ رافع بن خدری رضی اللہ عنہ روایت کرتے ہیں کہ رجال میں قرآن پاک کی تلاوت کا اہتمام خشوع اور خیر کے کام جو رسول اللہ صلی اللہ علیہ وسلم ہم دیکھتے تھے عجیب بات تھی۔ ایک دفعہ آپ ہمارے پاس تشریف لائے۔ اس وقت رجال ہمارے ساتھ بیٹھا تھا آپ نے فرمایا: ان لوگوں میں سے ایک شخص جہنمی ہے۔ سیدنا رافع فرماتے ہیں: میں نے غور سے دیکھا تو وہ یہ لوگ تھے ابو ہریرہ، ابو اروی، طفیل بن عمرو اور رجال میں دیکھ کر تعجب کرنے لگا۔ جب بنو حنیفہ مرتد ہوئے تو میں نے رجال کے بارے میں پوچھا تو لوگوں نے بتایا وہ فتنہ میں پڑ چکا ہے اس نے مسیلمہ کے لئے یہ گواہی دی کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے (نبوت کے) کام میں شریک کر لیا ہے۔ میں نے کہا: جو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: وہ سچ اور برحق ہے۔ لوگ بتا رہے تھے: کہ رجال کہتا تھا: دو دنوں کی فکر ہوئی تو ہمیں اپنا دنبہ پسند ہے اس کی مراد مسیلمہ اور رسول اللہ صلی اللہ علیہ وسلم تھے۔","",{"fn":"(1) الجرح والتعدیل (۵۱۶/۳)"}],[2757,"§۲۷۶۴ ۔ رداد\nقسم اول میں تذکرہ ہو چکا ہے۔"],[2758,"§۲۷۶۵ ۔ رفاعہ بن عبد المنذر(1)\nبن رفاعہ بن دینار انصاری۔ ابو نعیم نے ان کا ذکر کیا ہے اور ان میں اور قسم اول میں پہلے جن کا ذکر ہوا ہے جن کے متعلق دینار کے بدلہ زنبر کہا گیا ہے دونوں میں فرق کیا ہے۔ یہی درست ہے اس پر ابو موسیٰ نے متنبہ کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۹۱)"}],[2759,"§۲۷۶۶ ۔ رفاعہ بن عمرو الجہنی(1)\nابو عیاض نے ان کا تذکرہ بدری صحابہ میں کیا ہے ان کا نام تو دویدیہ بن عمرو ہے۔ اپنے مقام پر صحیح نام ذکر ہوگا۔","",{"fn":"(1) اسد الغابہ (۱۶۹۴) استیعاب (۷۸۳)"}],[2760,"§۲۷۶۷ ۔ رفاعہ البدری(1)\nابو موسیٰ نے ابو بکر بن ابی علی کے اتباع میں اپنے استدراک میں ان کا ذکر کیا ہے جو وہم پر مبنی ہے، اس لیے کہ حدیث تو رفاعہ بن رافع کی ہے جو بدری طرح نماز پڑھنے والے کی حدیث ہے۔ ابن مندہ نے اس کا صحیح ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۸۲)"}],[2761,"§۲۷۶۸ ۔ رفاعہ ابو عبایہ\nکسی نے وہم سے ان کا صحابہ میں ذکر کر دیا، جس کا شبہ میں حرف خاء خدیج کے ذیل میں ذکر کر چکا ہوں۔"],[2762,"§۲۷۶۹ ۔ رفاعہ (بے نسبت)(1)\nبیعت رضوان والے ہیں۔ ابو موسیٰ نے ان کا ذکر کیا اور بطریق ابو امیہ بن ابی المخارق روایت کی کہ مجھ سے ابو عبیدہ بن رفاعہ نے بحوالہ اپنے والد نقل کیا۔ ان کے والد نے درخت تلے بیعت کی تھی۔ فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم جب نیا چاند دیکھتے تو اللہ اکبر کہتے تھے۔ (حدیث) ابو موسیٰ فرماتے ہیں: یہ رفاعہ بن رافع کے علاوہ ہیں۔ ابو نعیم نے انہیں رفاعہ بن رافع کے حالات میں درج کر دیا ہے، لیکن مجھے ان کے کسی بیٹے کا علم نہیں جسے ابو عبیدہ کہا جاتا ہو، بظاہر یہ اور ہیں۔\nمیں کہتا ہوں: یہ وہی ہیں، ان سے روایت کرنے والے کا نام غلط ہو گیا ہے۔ درست عبید بن رفاعہ ہے۔ غیلانیات میں ایسا ہی لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۰۲)"}],[2763,"§۲۷۷۰ ۔ رقیس الاسدی\nبلاذری کا بیان ہے کہ کسی نے مہاجرین حبشہ میں ان کا ذکر کیا ہے۔ لکھتے ہیں: یہ غلط ہے درست نام قیس بن عبداللہ ہے۔"],[2764,"§۲۷۷۱ ۔ رکانہ ابو محمد(1)\nابن ابی داؤد اور بلاذری نے ان میں اور رکانہ بن عبد یزید المطلمی میں فرق کیا اور دونوں نے بطریق ابو جعفر محمد بن رکانہ بحوالہ اپنے والد روایت کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے کشتی لڑی، آپ نے مجھے پچھاڑ لیا۔ ابن مندہ(2) نے ان کا تذکرہ کر کے لکھا ہے: میرے خیال میں یہ پہلے ہیں۔\nمیں کہتا ہوں: ہاں یہی بات تحقیق سے ثابت ہے اس لیے کہ کشتی کا قصہ رکانہ بن عبد یزید کے حوالہ سے مشہور ہے۔ ترمذی اور ابن قانع وغیرہ نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۰۹)\n(2) جامع المسانید (۲۹۶/۴)"}],[2765,"§۲۷۷۲ ۔ رومان بن بعجہ\nبن زید بن عمیرہ الجذامی قسم اول میں تذکرہ ہو چکا ہے۔"],[2766,"§۲۷۷۳ ۔ رومہ الغفاری(1)\nبئر رومہ کے مالک، ابن مندہ نے ان کا ذکر کیا کہ بقول بعض وہ اسلام لے آئے تھے۔ ان کی حدیث عبد اللہ بن عمر بن ابان بواسطہ محاربی، ابو مسعود سے وہ ابو سلمہ سے وہ بشر بن بشیر اسلمی سے وہ اپنے والد سے روایت کرتے ہیں: جب مہاجرین مدینہ آئے تو انہیں یہاں کا پانی اوپر الگا۔ بنی غفار کے ایک شخص کا رومہ نامی ایک چشمہ تھا جس کا ایک مشک وہ مذ کے بدلہ میں بیچتا تھا آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: “یہ چشمہ میرے ہاتھ جنت کی ایک نہر کے عوض بیچ دو۔” وہ کہنے لگا: اللہ کے رسول صلی اللہ علیہ وسلم! میرا اور میرے اہل و عیال کا صرف یہی ذریعہ ہے۔ سیدنا عثمان رضی اللہ عنہ کو معلوم ہوا تو انہوں نے ان صاحب سے وہ چشمہ پینتیس ہزار(۳۵۰۰۰) دراہم میں خرید لیا، پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس آکر عرض کی: کیا آپ مجھے بھی وہی بشارت دے سکتے ہیں، جو رومہ کے لیے دی ہے کہ جنت میں ایک نہر ملے گی؟ آپ علیہ السلام نے فرمایا: ہاں! آپ نے عرض کی: تو میں نے وہ چشمہ خرید کر مسلمانوں کے لیے وقف کر دیا ہے۔ میں کہتا ہوں: ابن مندہ نے سیدنا عثمان رضی اللہ عنہ کی اس بات کو بنیاد بنایا ہے “کیا آپ مجھے بھی وہی بشارت دے سکتے ہیں جو رومہ کے لیے دی ہے۔ ان کے زعم کے مطابق اس سے مراد کنویں کا مالک ہے، حالانکہ ایسی بات نہیں کیونکہ حدیث کی ابتداء میں یہ بات واضح ہے کہ رومہ کنویں کا نام ہے اور ان کی اس بات سے مراد آپ نے رومہ کو دی، یعنی رومہ کے مالک کو دی، یا اس کا مفہوم مراد ہے۔ یہی روایت بغوی نے عبد اللہ بن عمر بن ابان سے اسی سند کے ساتھ نقل کی ہے، اس میں ہے: “اس کی مثل جو آپ نے اسے دی۔ یوں ضمیر غفاری کی طرف راجع ہوتی ہے۔ اسی طرح یہ روایت ابن شاہین اور طبرانی نے بطریق ابن ابان نقل کی ہے۔(2) بلاذری اپنی تاریخ میں لکھتے ہیں: رسول اللہ صلی اللہ علیہ وسلم بر رومہ کا پانی پیا کرتے تھے جو عقیق میں ہے، آپ نے اس میں اپنا لعاب دہن بھی ڈالا جس سے اس کا پانی شیریں ہو گیا۔ فرماتے ہیں: یہ پرانا کنواں ہے جو دلدل بن گیا تھا، ایک قوم جس کا تعلق مزینہ سے تھا اور وہ لوگ انصار کے حلیف تھے، آئی اور یہاں انہوں نے قیام کر لیا، اس کی اصلاح کی۔ رومہ انہی کی ایک خاتون تھی یا ان کی والدہ تھی جو لوگوں کو اس سے پانی پلاتی تھی، یوں یہ کنواں اسی کے نام سے منسوب ہو گیا۔ فرماتے ہیں: کسی راوی کا قول ہے اس کے کنارے کی وادی کو رومہ کہا جاتا ہے۔ عمر بن عتبہ نے اخبار مدینہ میں ابو غستان مدنی کی روایت نقل کی ہے کہ کئی لوگوں نے مجھے بتایا کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “مزنی کا کنواں کیا ہی بہترین کنواں ہے۔ پھر سیدنا عثمان رضی اللہ عنہ نے اسے خرید کر صدقہ کر دیا۔ عمر بن شبہ ایک ضعیف سند سے بحوالہ ابو قلابہ روایت کرتے ہیں کہ حویلی میں محاصرہ کے روز سیدنا عثمان رضی اللہ عنہ نے بلوایوں کو جھانک کر فرمایا، اور انہیں یاد دلایا: کیا تم لوگ جانتے ہو بئر رومہ فلاں یہودی کا تھا، جس کا وہ ایک قطرہ بھی کسی کو بغیر پیسے کے نہیں پینے دیتا تھا، اسے میں نے اپنے مال سے خریدا تھا؟ اس کے شواہد ترمذی وغیرہ میں ہیں۔ لیکن یہاں ان کی مراد ان کی یہ بات ہے: فلاں یہودی کا۔ ابن ہشام نے تیجان میں لکھا ہے کہ جب تبع نے یثرب پر حملہ کیا تو جو کنواں اس نے کھودا تھا اس کا پانی اسے پسند نہ آیا۔(3) تو فلیمہ بنت زید بن خالد بن عامر بن زریق اسے رومہ کا پانی پلانے کے لئے دیتی تھی، پھر قصہ ذکر کیا۔","",{"fn":"(1) اسد الغابہ (۱۷۱۶)\n(2) المعجم الکبیر (۱۲۲۶/۲)\n(3) اسد الغابہ (۱۷۱۵)"}],[2767,"§۲۷۷۴ ۔ رویبہ الثقفی (عمارہ کے والد)(1)\nطبرانی بطریق رقبہ بن مصقلہ، عبد الملک بن عمیر سے وہ عمارہ بن رویبہ سے وہ بحوالہ اپنے والد روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “وہ شخص ہرگز جہنم میں داخل نہیں ہوگا جس نے سورج نکلنے اور سورج غروب ہونے سے پہلے (فرض) نماز پڑھی۔” ابو موسیٰ(2) نے یہی روایت اسی سند سے نقل کی ہے جبکہ اس اسناد میں خلل ہے وہ یہ کہ مسلم وغیرہ نے یہ روایت کئی طرق سے روایت کی ہے جو عبد الملک بن عمیر سے بحوالہ ابن عمارہ انہوں نے اپنے والد سے نقل کی ہے۔ شاید پہلی روایت سے لفظ ابن رہ گیا ہے۔","",{"fn":"(1) مسلم کتاب المساجد باب فضل صلاتی الصبح والعصر والمحافظۃ علیھما (۱۳۳۵، ۱۳۳۴)\n(2) ابوداؤد کتاب الصلاۃ باب المحافظۃ فی وقت الصلاۃ (۴۲۷) نسائی کتاب الصلاۃ باب فضل صلاۃ العصر (۴۷۰)"}],[2768,"§۲۷۷۵ ۔ رئاب المزنی(1)\nمعاویہ بن قرہ کے دادا۔ طبرانی اور حسن بن سفیان نے بطریق عبد الواحد بن غیاث بحوالہ معاویہ بن قرہ بن رئاب روایت کی ہے کہ وہ اس وقت اپنے دادا کے ساتھ تھے، جب وہ نبی صلی اللہ علیہ وسلم کے پاس گئے۔ اور حسن بن سفیان کی بحوالہ اپنے والد والی روایت میں ہے کہ “میں اپنے والد کے ساتھ تھا جب وہ گئے۔” صحیح یہی ہے جو ابن قانع وغیرہ بطریق فرات بن ابی فرات، بواسطہ معاویہ بن قرہ بن ایاس بن رباب وہ اپنے والد سے نقل کرتے ہیں کہ میں اپنے والد کے ساتھ تھا، لہذا صحابی ہونا ایاس اور قرہ کے لیے ثابت ہوا نہ کہ رباب کے لیے۔ ادھر قسم اول میں ایاس بن ہلال بن رباب کے حالات میں یہ بات گزر چکی ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۱۷۹)"}],[2769,"§۲۷۷۶ ۔ الرئیس بن عامر\nبن الحصین الطائی۔ انہیں وفد میں آنے کا شرف حاصل ہے۔ ایسا ہی ذہبی نے تجرید میں اپنے استدراک میں ان کا ذکر کیا ہے، انہوں نے یہ نام “رئیس” قلمبند کیا ہے، جو لفظی غلطی کا خمیازہ ہے۔ درست نام “ربس” ہے، باقی اسی طرح ہے۔ میں پہلے درست ذکر کر چکا ہوں۔"],[2770,"§۲۷۷۷ ۔ الزارع بن عامر(1)\nبقول بعض: ابن عمرو العبدی، ابو الوازع، از عبد القیس۔ ان کا شمار بصرہ کے دیہاتیوں میں ہوتا ہے۔ ابن عبد البر(2) کا قول ہے: بقول بعض: ان کے والد کا نام زارع ہے اور وازع، واؤ سے، ان کے بیٹے کا نام ہے۔ ایک روایت ہے کہ وہ افتح العصری کے ساتھ وفد میں نبی علیہ السلام کے پاس آئے۔ ان کا ذکر جہم بن کم(3) کے سوانح میں پہلے آچکا ہے۔ امام بخاری رحمہ اللہ(4) نے الادب المفرد میں اور ابو داؤد نے ان کی حدیث روایت کی ہے، ان سے ان کی پوتی ام ابان بنت الوازع روایت کرتی ہیں۔ ابو الفتح ازدی کا قول ہے کہ ان سے روایت کرنے میں یہ اکیلی ہیں۔","",{"fn":"(1) اسد الغابہ (۱۷۲۲) استیعاب (۸۷۲)\n(2) استیعاب (۱۳۱/۲)\n(3) ابن ماجہ کتاب الزہد باب الحلم (۴۱۸۷) اتحاف السادۃ المتقین (۳۱/۸) کنز العمال (۵۸۱۲، ۵۸۲۴، ۵۸۳۵)\n(4) الادب المفرد (۹۷۵)"}],[2771,"§۲۷۷۸ ۔ زاملہ\nبریدہ بن الحصیب کا لقب ہے۔"],[2772,"§۲۷۷۹ ۔ زاہر بن الاسود(1)\nبن حجاج بن قیس اسلمی مجزآۃ کے والد۔ بیعت رضوان کے شرکاء میں سے ہیں، کوفہ سکونت تھی۔ نبی علیہ السلام سے پالتو گدھوں کا گوشت کھانے کی ممانعت والی حدیث روایت کرتے ہیں، ان سے ان کا بیٹا مجزآۃ روایت کرتا ہے۔ امام مسلم رحمہ اللہ وغیرہ نے ذکر کیا ہے کہ وہ ان سے روایت کرنے میں منفرد ہے۔ ان کی حدیث امام بخاری(2) نے اپنی صحیح میں نقل کی ہے، اس میں ہے کہ وہ حدیبیہ اور خیبر میں شریک تھے۔ محمد بن اسحاق کا قول ہے: عمرو بن احمق جب مصر میں تھے تو یہ ان کے ساتھیوں میں تھے، جس سے اندازہ لگایا جا سکتا ہے کہ وہ خلافت عثمانی تک حیات رہے۔","",{"fn":"(1) اسد الغابہ (۱۷۲۳) استیعاب (۸۰۸) تجرید (۱۸۷/۱)\n(2) بخاری کتاب المغازی باب غزوۃ الحدیبیہ (۴۱۷۳)"}],[2773,"§۲۷۸۰ ۔ زاہر بن حرام اشجعی(1)\nبقول ابن عبد البر:(2) بدر میں شریک ہوئے۔ (لیکن) کسی نے اس قول میں ان کی موافقت نہیں کی۔ بقول بعض: ان سے لفظی غلطی ہوگئی کیونکہ ان کے بارے بتایا جاتا ہے کہ وہ بدری ہیں۔ ایک صحیح حدیث میں ان کا ذکر آتا ہے جو امام احمد اور ترمذی نے شمائل میں بطریق معمر بواسطہ ثابت، بحوالہ سیدنا انس رضی اللہ عنہ نقل کی ہے کہ ایک دیہاتی صاحب جن کا نام زاہر تھا، نبی علیہ السلام کے لیے ہدیہ لائے تھے پھر وہ حدیث ذکر کی۔ اسی میں آپ علیہ السلام کا ارشاد ہے: 'زاہر ہمارے دیہاتی اور ہم ان کے شہری ہیں۔' رسول اللہ صلی اللہ علیہ وسلم جب دیہات کی جانب جانے کا ارادہ رکھتے تو انہیں کچھ دے کر آتے۔ 'زاہر' پستہ قد تھے، نبی علیہ السلام ان کے پاس آئے وہ بازار میں اپنی کوئی چیز فروخت کر رہے تھے۔ آپ صلی اللہ علیہ وسلم نے ان کے کندھوں کو اپنے بازوؤں میں بھر لیا، وہ کہنے لگے: ارے بھائی! کون ہے؟ مجھے چھوڑ دو۔ مڑ کر جو دیکھا تو نبی صلی اللہ علیہ وسلم تھے۔ نبی صلی اللہ علیہ وسلم فرمانے لگے: 'مجھ سے یہ غلام کون خریدے گا؟' وہ اپنی پیٹھ نبی صلی اللہ علیہ وسلم کے سینے اقدس سے ملا کر کہنے لگے: 'آپ صلی اللہ علیہ وسلم کو میری بہت تھوڑی قیمت ملے گی۔' نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: 'لیکن اللہ تعالیٰ کے ہاں تمہاری قیمت بہت زیادہ ہے۔' بغوی وغیرہ نے یہ روایت نقل کی ہے۔ جبکہ معمر نے ان کے خلاف روایت کی ہے۔ اسی روایت کو حماد بن سلمہ نے یوں نقل کیا ہے: ثابت، اسحاق بن عبداللہ بن حارث سے مرسلا نقل کرتے ہیں، اور ثابت کی روایت میں حماد معمر سے زیادہ قوی ہیں۔ لیکن اس حدیث کا بروایت سالم بن ابی الجعد الاشجعی بحوالہ الاشجعی کے زاہر بن حرام نامی شخص ایک شاہد موجود ہے، وہ دیہاتی شخص تھے جب بھی نبی صلی اللہ علیہ وسلم کے پاس آتے تو کوئی نئی پیداوار یا ہدیہ لے کر آتے تھے۔ ایک دفعہ نبی صلی اللہ علیہ وسلم نے انہیں سودا بیچتے دیکھا تو آ کر انہیں کمر سے پکڑ لیا۔ (حدیث) ان کے والد 'حرام' کا نام بقول بعض: حا اور زبر سے، اور ایک قول ہے: زیر اور زا سے 'حزام' ہے۔ عبدالرزاق کی روایت میں شک کے ساتھ (دونوں نام) لکھے ہیں۔","",{"fn":"(1) اسد الغابہ (۱۷۲۴) تجرید (۱۸۷/۵)\n(2) استیعاب (۸۸/۲)"}],[2774,"§۲۷۸۱ ۔ زائدہ بن حوالہ العنزی(1)\nابن عبدالبر(2) نے ان کا مختصر ذکر کیا ہے، ابن الاثیر(3) نے انہی کا اتباع کیا ہے۔ ذہبی نے امام احمد رحمہ اللہ کی کتاب کا حوالہ دیا ہے، جبکہ عماد بن کثیر نے ان صحابہ کے ناموں میں ان کا ذکر کیا ہے جن کی روایتیں امام احمد نے نقل کی ہیں، چنانچہ فرماتے ہیں: 'الجزء الثانی از مسند بصریین 'زائدہ یا مزیدہ بن حوالہ' مجھے ان کی حدیث امام احمد کی کتاب میں بطریق شمس بن حسن، بواسطہ عبداللہ بن شقیق مل گئی، فرماتے ہیں: مجھ سے عنزہ کے ایک زائدہ یا مزیدہ بن حوالہ نامی شخص نے بیان کیا، ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کسی سفر میں تھے، لوگ ایک مقام پر فروکش ہوئے۔ آپ صلی اللہ علیہ وسلم ایک تنے کے نیچے ٹھہرے ہوئے تھے، میں اپنے کسی کام سے آرہا تھا، اس وقت آپ کے اور آپ کے کاتب کے علاوہ کوئی نہیں تھا۔ آپ نے فرمایا: 'اے ابن حوالہ! کیا ہم تمہیں لکھ دیں۔' (حدیث)(4) یہی روایت یزید بن ہارون نے بحوالہ حمص نقل کی ہے۔ اسی طرح امام احمد رحمہ اللہ نے مسند عبداللہ بن حوالہ میں اسماعیل بن علیہ سے بواسطہ الجریری، عبداللہ بن شقیق بحوالہ ابن حوالہ نقل کی، پھر اس کا مفہوم نقل کیا۔ ایسا ہی انہوں نے اس حدیث کو سند عبداللہ بن حوالہ میں درج کیا۔ حدیث میں ان کا نام عبداللہ نہیں لیا گیا۔ البتہ طبرانی نے بطریق حماد بن سلمہ بواسطہ الجریری ان کا نام عبداللہ نقل کیا ہے۔ عبداللہ بن حوالہ مشہور صحابی ہیں، جو شام فروکش ہوئے۔ یہی ازدی نسبت سے مشہور ہیں۔ وہ اس حدیث کے راوی زائدہ سے زیادہ مشہور ہیں۔ شاید کسی راوی نے یہ سمجھ کر کہ یہ مشہور ابن حوالہ ہیں ان کا نام عبداللہ بیان کر دیا ہو جبکہ درست زائدہ یا مزیدہ (شک کے ساتھ) ہے۔ یہ عبداللہ کے بھائی بھی نہیں، کیونکہ عبداللہ ازدی ہیں بقول بعض عامری ہیں جنہوں نے ازد کے ساتھ معاہدہ کیا تھا، اور زائدہ عنزی کا ذکر میں نے صرف مسند احمد کی اس جگہ میں ہی دیکھا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۲۵) استیعاب (۸۶۸)\n(2) استیعاب (۱۲۸/۲)\n(3) اسد الغابہ (۲۰۶/۲)\n(4) مسند احمد (۱۰۹/۴)"}],[2775,"§۲۷۸۲ ۔ زبان(1)\nبقول بعض زبا رای کو عبدالغنی بن قسورہ نے راجح قرار دیا ہے۔ ایک قول ہے: قیور گلفی، الدار قطنی نے 'المؤتلف' میں ان کی حدیث بطریق محمد بن اسحاق بواسطہ یحیی بن عروہ انہوں نے اپنے والد سے انہوں نے بحوالہ ان کے نقل کی ہے۔ الدار قطنی لکھتے ہیں: ان کی حدیث منکر ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۲۶) استیعاب (۸۶۹)"}],[2776,"§۲۷۸۳ ۔ زبان العدوی\nان کی حدیث ابومحمد بن قتیبہ نے بطریق عیسی بن یزید بن داب نقل کی ہے کہ نبی صلی اللہ علیہ وسلم کے سامنے کسی نے کہانت کا ذکر کیا، تو زبان عدوی نے کہا: اللہ کے رسول! میں نے عجیب چیز دیکھی۔"],[2777,"§۲۷۸۴ ۔ الزبرقان بن بدر(1)\nبن امرئ القیس بن خلف بن بدلہ بن عوف بن کعب بن سعد بن زید مناۃ بن تمیم بن مر۔ التمیمی السعدی۔ بقول بعض: ان کا نام حصین تھا اور خوبصورتی کی وجہ سے ان کا لقب 'زبرقان' تھا جو چاند کا نام ہے۔ ابن اسحاق نے وفود عرب میں ذکر کیا ہے: تمیم کا وفد آیا جن میں عطارد بن حاجب تھے جو اپنی قوم کے معزز لوگوں کے ساتھ تھے، جن میں اقرع بن حابس، زبرقان بن بدر جو بنی سعد کے فرد ہیں۔ عمرو بن الاہتم، قیس بن عاصم شامل تھے۔ ان لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو حجروں کے باہر سے پکارا۔ پھر لمبا قصہ ذکر کیا کہ یہ لوگ اسلام لائے۔ ابن ابی خیثمہ نے ان کا قصہ، زبیر بن بکار سے بواسطہ محمد بن ضحاک انہوں نے اپنے والد سے مرسل اور طویل ذکر کیا ہے۔ اور ابن شاہین نے ایک اور کمزور سند سے اور ابو حاتم بجستانی نے کتاب المعمرین میں اکثم بن صیفی کے حالات میں دوسرے سیاق سے نقل کیا ہے۔ ابونعیم کی روایت ہے کہ عمرو بن الاہتم، قیس بن عاصم اور زبرقان بن بدر نبی صلی اللہ علیہ وسلم کے پاس آئے تو نبی صلی اللہ علیہ وسلم نے عمرو بن عاصم سے فرمایا: 'مجھے اس (یعنی زبرقان) کے بارے میں بتاؤ۔' پھر وہ حدیث ذکر کی۔ اسی میں آپ علیہ السلام کا یہ ارشاد ہے: 'بعض باتیں جادو کا اثر رکھتی ہیں۔'(2) اس کی سند حسن ہے صرف اس میں انقطاع پایا جاتا ہے۔ ابن شاہین نے یہی روایت ابوالمقوم انصاری کے طریق سے بواسطہ حکم مقسم سے بحوالہ ابن عباس رضی اللہ عنہ نقل کی ہے، فرمایا: نبی صلی اللہ علیہ وسلم کے پاس قیس بن عاصم، زبرقان بن بدر اور عمرو بن الاہتم اکٹھے ہوئے۔ پھر لمبی حدیث ذکر کی۔ یعقوب بن سفیان نے اپنی تاریخ میں زبرقان بن بدر کی روایت نقل کی ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس گیا تو ایک انصاری کے ہاں فروکش ہوا۔ پھر لمبی حدیث ذکر کی۔ ابن مندہ لکھتے ہیں: یہ حدیث غریب ہے، طبرانی نے اسی سند سے ایک اور حدیث اور عطیہ کے ساتھ ان کا قصہ ذکر کیا ہے، جسے میں قسم ثالث کے حرف حاء میں خطیبہ کے حالات میں بیان کر چکا ہوں۔ ابو عمر اور ابن عبد البر(3) کا قول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں ان کی قوم کی زکوۃ وصول کرنے پر مقرر کیا، جسے آپ نے دور صدیق میں بھی ادا کیا تو آپ نے انہیں اسی خدمت پر مامور رکھا پھر فاروقی دور میں بھی یہی ذمہ داری ادا کرتے رہے۔ وثیمہ نے 'کتاب الردۃ' میں ان کے وہ اشعار نقل کیے ہیں جن میں انہوں نے پوری طرح زکاۃ ادا کرنے کی خدمت کا ذکر کیا ہے۔ اور جبکہ قیس بن عاصم نے رسول اللہ صلی اللہ علیہ وسلم کے اونٹوں پر ہاتھ ڈالا۔ 'رسول اللہ صلی اللہ علیہ وسلم کے زکاۃ کے اونٹ آئے تو میں نے پورے کے پورے پہنچا دیئے۔ ان میں سے ایک اونٹ بھی نہیں لوٹایا گیا۔' دوہرے شعر میں کہتے ہیں: 'وقیس اور خندف کو میرا کوئی یہ پیام پہنچائے گا کہ ہمارے لئے اللہ تعالیٰ کا اٹل فیصلہ اور محمد صلی اللہ علیہ وسلم کا حکم ہے۔' میں کہتا ہوں: ان کا اس بارے میں قیس بن عاصم کے ساتھ ایک واقعہ بھی ہے، جسے ابوالفرج نے قیس کے سوانح میں لکھا ہے۔ زبرقان خلافت امیر معاویہ رضی اللہ عنہ تک حیات رہے۔ حافظ نے کتاب الایمان میں نقل کیا ہے کہ وہ زیاد کے پاس آئے جب ان کی نظر چلی گئی تھی۔ آ کر ہلکا سا سلام کیا۔ زیاد نے انہیں اپنے پاس بٹھایا اور کہنے لگا: ابو عباس! لوگ آپ کی بے وفائی پر ہنستے ہیں؟ فرمانے لگے: اگرچہ وہ ہنستے رہیں، اللہ کی قسم! کوئی شخص بھی یہ پسند نہیں کرے گا کہ میں اس کا باپ بنوں کم عقلی یا دانشمندی کی وجہ سے۔ مرادی نے 'فیمن عمی من الاشراف' (معزز لوگوں میں سے جو نابینا ہو گئے) نامی کتاب میں ان کا ذکر کیا ہے۔ کو کسی نے لکھا ہے وہ عبدالملک کے پاس آئے اور اس کی طرف پھپیں گھوڑے لائے اور ہر گھوڑے کا نسب اس کی ماں اور باپ تک بیان کیا۔ ہر گھوڑے پر ایک قسم کھائی جو دوسرے پر نہیں کھائی۔ عبد الملک کہنے لگا: مجھے ان کی مختلف قسموں پر گھوڑوں کے نسب کی جان پہچان کے مقابلہ میں زیادہ تعجب ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۲۸) استیعاب (۸۷۰) تجرید (۱۸۸/۱)\n(2) ابوداؤد کتاب الادب باب ما جاء فی الشعر (۵۰۱۱) ابن ماجہ کتاب الادب باب الشعر (۳۷۵۶) مسند احمد (۲۴۲۴) المعجم الکبیر (۱۰۰۲۵، ۱۰۰۹۴) مجمع الزوائد (۱۳۲۸۶)\n(3) استیعاب (۱۲۹/۲)"}],[2778,"§۲۷۸۵ ۔ زبرقان بن اضلم(1)\nاز آل ذی لغوہ۔ ابن مندہ نے بطریق عمرو بن شمر بواسطہ لیث، مجاہد سے بحوالہ ابووائل ان کا صحابہ میں تذکرہ کیا ہے کہ حسین بن علی جنگ صفین کے روز سامنے آئے۔ پھر ایک قصہ ذکر کیا جس میں ہے کہ زبرقان بن اصلم نے ان سے کہا: بیٹا! واپس لوٹ جاؤ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو قباء سے آتے دیکھا ہے اور تم ان کے آگے ہو، میں ایسا نہیں کہ تمہارے خون سے رسول اللہ صلی اللہ علیہ وسلم کا سامنا کروں۔(2)","",{"fn":"(1) اسد الغابہ (۱۷۲۷)\n(2) جامع المسانید (۳۲۰/۴) اسد الغابہ (۲۰۶/۲)"}],[2779,"§۲۷۸۶ ۔ الزبیب بن ثعلبہ(1)\nبن عمرو بن سواء العنبری۔ بقول بغوی: دیہات میں رہتے تھے۔ ان (بغوی) کے علاوہ کسی نے کہا: بصرہ فروکش ہوئے، اکثر کے نزدیک یہ نام تصغیر ہے۔ جبکہ عسکری نے ان کی مخالفت کرتے ہوئے پہلی با کو نون (الزنیب) لکھا ہے۔ اور اس کا اعتراف کیا ہے کہ محدثین یہ نام باء سے لیتے ہیں۔ ان کی ایک حدیث ابوداؤد(2) نے نقل کی ہے۔ ان سے ابن دجین اور ان کے پوتے شعیث نے روایت کی ہے ان سے ان کے سماع کی صراحت سنن ابوداؤد میں کی ہے۔ ان کی والدہ ام زینب کے حالات میں جو خواتین کی کنیتوں میں ہے، وہاں ان شاء اللہ تعالیٰ ان کا ذکر ہوگا۔","",{"fn":"(1) اسد الغابہ (۱۷۲۹) استیعاب (۸۷۱) تجرید (۱۸۸/۱)\n(2) ابوداؤد کتاب الاقضیہ باب القضاء بالیمین والشاہد (۳۶۱۲)"}],[2780,"§۲۷۸۷ ۔ زبید السلمی\nان کی حدیث محمد بن یحی عدنی بن ابی عمر نے اپنی مسند میں نقل کی ہے، سفیان نے اپنے ایک دوست عمرو بن حفص جو ثقہ ہیں وہ بنی سلیم کے ایک شیخ جنہیں زبید کہا جاتا ہے سے روایت کرتے ہیں، انہوں نے دس سال میں قرآن پڑھا، جس کا ختم وہ چوبیس گھنٹے میں کرتے اور بیس سال تک دو دنوں اور دو راتوں میں ایک ختم کرتے۔ فرماتے: اللہ کی قسم! ان کے چہرہ پر ایک نور تھا۔ آپ صلی اللہ علیہ وسلم جب اپنے صحابہ میں کوئی (شیطانی) دھوکا یا غفلت محسوس کرتے تو بلند آواز سے فرماتے: 'یقینا موت تمہیں آئی، یا تو بد بختی لے کر یا سعادت لے کر۔'"],[2781,"§۲۷۸۸ ۔ زبیر بن عبداللہ کلابی(1)\nیعقوب بن سفیان نے نبی صلی اللہ علیہ وسلم سے ملاقات کرنے والوں میں ان کا ذکر کیا ہے، جبکہ ابوعمر(2) لکھتے ہیں: مجھے ان کی ملاقات کا علم نہیں۔ البتہ انہوں نے دور جاہلیت پایا ہے اور خلافت عثمانی تک زندہ رہے۔ میں کہتا ہوں: شاید ان کی مراد وہ روایت ہے جو علاء بن زبیر نے اپنے والد سے نقل کی ہے: میں نے دیکھا کہ فارس رومیوں پر غالب آئے پھر روم کا غلبہ فارس پر دیکھا۔ پھر دیکھا کہ مسلمان فارس پر غالب آگئے، یہ سب کچھ پندرہ سالوں میں ہوا۔ ابوالحسن بن سمیع نے انہیں اہل شام کے تابعین کے دوسرے طبقہ میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۳۰) استیعاب (۸۰۹)\n(2) استیعاب (۸۹/۲)"}],[2782,"§۲۷۸۹ ۔ زبیر بن عبیدہ اسدی(1)\nاز بنی اسد بن خزیمہ ابن اسحاق نے انہیں بنی اسد میں سے مہاجرین مدینہ میں ذکر کیا ہے جن میں وہ اور ان کے بھائی تمام بن عبیدہ بھی تھے۔","",{"fn":"(1) اسد الغابہ (۱۷۳۱) استیعاب (۸۱۰)"}],[2783,"§۲۷۹۰ ۔ زبیر بن عدی\nبن نوفل بن اسد بن عبد العزی قرشی اسدی، ورقہ بن نوفل کے بھتیجے۔ بلاذری نے ان کا ذکر کیا ہے۔"],[2784,"§۲۷۹۱ ۔ زبیر بن عوام(1)\nبن خویلد بن اسد بن عبد العزی بن قصی بن کلاب قرشی اسدی۔ ابو عبد اللہ حواری رسول اللہ صلی اللہ علیہ وسلم اور آپ کے پھوپھی زاد بھائی۔ ان کی والدہ صفیہ بنت عبد المطلب تھیں۔ آپ عشرہ مبشرہ میں سے ہیں۔ اور شوریٰ کے چھ افراد میں سے ہیں، آپ کی والدہ نے آپ کی کنیت 'ابوالطاہر' رکھی تھی، جو ان کے بھائی زبیر بن عبد المطلب کی کنیت تھی۔ جبکہ انہوں نے اپنے بیٹے 'عبداللہ' سے کنیت رکھی ہے جس کا غلبہ ہو گیا۔ بارہ سال کی عمر میں اسلام لائے۔ بقول بعض: آٹھ سال میں۔ لیث کا قول ہے ابوالاسود نے مجھ سے بیان کیا کہ سیدنا زبیر کے چچا انہیں چٹائی میں لپیٹ کر اوپر سے دھواں چھوڑ دیتے تا کہ وہ واپس کفر اختیار کر لیں۔ وہ فرماتے: میں کبھی کفر نہیں کر سکتا۔ زبیر بن بکار نے کتاب النسب میں لکھا ہے کہ مجھ سے میرے چچا نے بحوالہ میرے دادا عبداللہ بن مصعب روایت کی ہے جب عوام کا انتقال ہوا تو نوفل بن خویلد اپنے بھتیجے زبیر کی پرورش کرتے تھے، اور سیدہ صفیہ انہیں مارتی تھیں، اس وقت وہ کم سن تھے اور انہیں ڈانٹتی تھیں، تو نوفل نے انہیں ڈانٹا اور کہا: کیا اس طرح بچوں کو مارا جاتا ہے تم تو اسے ایسے مارتی ہو جیسے اس سے ناراض ہو۔ تو سیدہ صفیہ نے فی البدیہ (بے ساختہ) یہ اشعار کہے: 'جو اس کا قائل ہے کہ میں اس سے ناراض ہوں تو وہ جھوٹا ہے میں تو اسے اس لئے مارتی ہوں تا کہ بہادر بنے اور لشکر کے چھکے چھڑا دے اور مقتول کا سامان لے کر لوٹے اور اپنے مال کے لئے چھپ کر نہ بیٹھے کہ گھر میں بیٹھا کھجوریں اور اناج کھاتا پھرے۔' بنی نوفل ان کے پیچھے پڑ گئے۔ وہ کہنے لگے: اے بنی ہاشم! کیا تم لوگ اسے میری طرف سے نہیں ڈانٹتے؟ سیدنا زبیر نے دو ہجرتیں کی ہیں۔ عروہ فرماتے ہیں: زبیر رضی اللہ عنہ وہ اتنے دراز قد تھے کہ جب وہ سوار ہوتے تو ان کے پاؤں زمین پر لگتے۔ یہ روایت زبیر بن بکار نے نقل کی ہے۔ سیدنا عثمان رضی اللہ عنہ سے کسی نے کہا کہ زبیر کو خلیفہ بنا دیجیے، تو آپ نے فرمایا: 'یہ تو رسول اللہ صلی اللہ علیہ وسلم کے سب سے بہترین اور آپ کے سب سے پسندیدہ شخص تھے۔' یہ روایت امام احمد اور بخاری رحمہ اللہ نے نقل کی ہے۔ ان کے بارے میں حسان بن ثابت رضی اللہ عنہ فرماتے ہیں جو زبیر بن بکار نے روایت کی ہے: 'آپ صلی اللہ علیہ وسلم کے حواری عہد نبوی میں آپ کے طریقہ پر کار بند رہے اور قول فعل کے برابر ہے۔' - اسی میں یہ بھی کہا: 'ان جیسا ان میں ہے اور نہ ان سے پہلے کوئی ہوا اور جب تک زمانہ ہے کوئی نہ ہوگا، جب تک پہاڑ 'یذبل' موجود ہے۔' - زبیر بن بکار بطریق ہشام بن عروہ وہ اپنے والد سے وہ عبداللہ بن زبیر رضی اللہ عنہ سے روایت کرتے ہیں، فرمایا: میں نے سیدنا زبیر سے پوچھا کہ آپ نے نبی صلی اللہ علیہ وسلم سے اتنی کم احادیث کیوں نقل کی ہیں، تو وہ فرمانے لگے: 'ہمارا رشتہ ناتا تم جانتے ہی ہو چونکہ میں نے آپ کو فرماتے سنا ہے: جس نے میرے بارے میں ایسی بات کہی جو میں نے نہیں کی تو وہ اپنا ٹھکانہ جہنم بنائے۔'(2) یہی روایت امام بخاری(3) نے دوسری سند سے بحوالہ عروہ نقل کی ہے کہ زبیر نے مکہ میں ایک آدمی سے لڑ کر اس کا ہاتھ توڑ دیا۔ (گلہ دینے کے لیے) اس شخص کو اٹھا کر سیدہ صفیہ کے پاس لایا گیا۔ پوچھ گچھ کے بعد آپ نے فرمایا: تم نے اپنے زبیر کو کیسا پایا: 'پنیر، کھجور، یا غضبناک شکرا؟' یہ روایت ابن سعد نے عروہ اور ابن المسیب سے نقل کی ہے۔ فرماتے ہیں: اللہ تعالیٰ کی راہ میں سب سے پہلے جس نے تلوار سونتی وہ زبیر ہی ہیں، جس کا قصہ یہ ہوا کہ شیطان نے یہ افواہ پھیلا دی کہ رسول اللہ صلی اللہ علیہ وسلم کفار کے نرغہ میں آگئے۔ سیدنا زبیر رضی اللہ عنہ اپنی تلوار سے انسانی سمندر چیرتے ہوئے آگے بڑھے بالآخر نبی صلی اللہ علیہ وسلم کو مکہ کے بالائی حصہ میں دیکھ کر مطمئن ہوئے۔(4) یہ روایت زبیر بن بکار نے دو سندوں سے نقل کی ہے۔ ابن المسیب کی روایت میں ہے: کسی نے کہہ دیا کہ رسول اللہ صلی اللہ علیہ وسلم شہید ہوگئے تو زبیر رضی اللہ عنہ نے اپنی تلوار لہراتے ہوئے (اس سمت) نکل پڑے۔ ابن سعد(5) نے صحیح سند سے بواسطہ ہشام انہوں نے اپنے والد سے نقل کیا ہے کہ جنگ بدر میں سیدنا زبیر رضی اللہ عنہ نے سپاہ عمامہ باندھ کر اس سے نقاب کیا ہوا تھا، آپ صلی اللہ علیہ وسلم نے دیکھ کر فرمایا: 'فرشتے زبیر کے مشابہ اترتے ہیں۔' اور طبرانی نے بطریق ابو اسحاق انہوں نے بحوالہ اپنے والد اسی کا مفہوم نقل کیا ہے۔ اور حدیث عروہ میں بحوالہ ابن زبیر رضی اللہ عنہ مروی ہے کہ مجھ سے زبیر فرمانے لگے: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا تھا: 'میرے ماں باپ تجھ پہ نثار ہوں۔'(6) عروہ سے مروی ہے کہ زبیر رضی اللہ عنہ کے جسم پر تلوار کے اتنے گہرے گھاؤ اور زخم تھے جن میں میں انگلیاں ڈالے کھیلا کرتا تھا۔ دو بدر میں اور ایک جنگ یرموک میں آیا۔(7) بخاری کی بحوالہ سیدہ عائشہ رضی اللہ عنہا روایت ہے کہ انہوں نے عروہ سے کہا: تمہارے والد ان لوگوں میں سے تھے، جنہوں نے مصیبت کے بعد بھی اللہ اور اس کے رسول کا حکم قبول کیا۔ آپ کی مراد ابوبکر اور زبیر تھی۔(8) اسی طرح سیدنا جابر رضی اللہ عنہ سے مروی ہے کہ بنی قریظہ سے معرکہ کے روز رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: میرے پاس اس قوم کی اطلاع کون لائے گا؟ سیدنا زبیر آگے بڑھے۔ نبی صلی اللہ علیہ وسلم نے فرمایا: 'ہر نبی کا ایک حواری ہوتا ہے اور میرا حواری زبیر ہے۔'(9) امام احمد رحمہ اللہ نے بطریق عاصم بن زر روایت کی ہے کہ کسی نے سیدنا علی رضی اللہ عنہ سے کہا کہ زبیر کا قاتل دروازے پر کھڑا ہے۔ آپ نے فرمایا: ابن صفیہ کا قاتل جہنمی ہے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: 'ہر نبی کا ایک حواری ہوتا ہے جبکہ میرا حواری زبیر ہے۔'(10) ابن عدی نے یہی متن حدیث ابوموسیٰ اشعری رضی اللہ عنہ سے نقل کیا ہے۔ ابویعلیٰ کی روایت ہے سیدنا ابن عمر رضی اللہ عنہ نے ایک شخص کو کہتے سنا: میں حواری کا بیٹا ہوں، آپ نے فرمایا: اگر تم زبیر کی اولاد سے ہو تو ٹھیک ورنہ نہیں۔ یعقوب بن سفیان نے مطیع بن الاسود کی روایت نقل کی ہے کہ انہوں نے زبیر رضی اللہ عنہ سے کوئی کام کہا: تو انہوں نے انکار کر دیا، یہ کہنے لگے: میں آپ کو اللہ تعالیٰ اور رشتہ داری کا واسطہ دیتا ہوں آپ مان لیں۔ کیونکہ میں نے سیدنا عمر رضی اللہ عنہ کو فرماتے سنا: 'زبیر دین کا ایک ستون ہے۔' 'النوادر' میں حمیدی نے لکھا ہے کہ سیدنا عثمان، مقداد، ابن مسعود، ابن عوف وغیرہ حضرات نے سیدنا زبیر رضی اللہ عنہ کو وصیت کر رکھی تھی، چنانچہ وہ ان حضرات کے مال کی حفاظت کرتے اور اپنے مال سے ان کے بال بچوں پر خرچ کرتے۔ زبیر بن بکار اور مطیع بن الاسود نے ابوالعاص بن الربیع کا اضافہ نقل کیا ہے۔ یعقوب بن سفیان کا بیان ہے کہ سیدنا زبیر رضی اللہ عنہ کے ہزار غلام تھے جو انہیں خراج ادا کرتے تھے تو وہ اس میں سے گھر کچھ بھی نہ لاتے سارا باہر صدقہ کر دیتے۔ قرض کی ادائیگی اور اس میں برکت کا قصہ صحیح بخاری میں کتاب النمس میں طوالت کے ساتھ مذکور ہے۔ سیدنا زبیر رضی اللہ عنہ کی شہادت جنگ جمل سے واپسی پر ہوئی جب سیدنا علی رضی اللہ عنہ نے انہیں یاد دلایا، چنانچہ ابویعلیٰ کی بطریق ابوجر والمازنی روایت میں ہے کہ میں نے سیدنا علی اور زبیر رضی اللہ عنہما کو جنگ جمل میں آمنے سامنے دیکھا تو سیدنا علی رضی اللہ عنہ نے ان سے فرمایا: میں تمہیں اللہ تعالیٰ کا واسطہ دے کر کہتا ہوں کیا تم نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا ہے کہ 'تم علی سے لڑو گے اور زیادتی تمہاری طرف سے ہوگی۔' انہوں نے فرمایا: ہاں، اور یہ بات مجھے ابھی یاد آئی ہے، پھر وہاں سے چلے گئے۔ ابن سعد نے صحیح سند سے بحوالہ ابن عباس رضی اللہ عنہ نقل کیا ہے کہ انہوں نے جنگ جمل کے روز سیدنا زبیر رضی اللہ عنہ سے کہا: کیا آپ ابن عبدالمطلب سے لڑنے آئے ہیں؟ تو سیدنا زبیر واپس آگئے۔ ابن جرموز نے تاک میں انہیں قتل کر دیا۔ ابن عباس رضی اللہ عنہ سیدنا علی رضی اللہ عنہ کے پاس آکر کہنے لگے: ابن صفیہ کے قاتل کا کیا انجام ہے؟ فرمایا: جہنمی ہے۔ ان کی شہادت کا واقعہ جمادی الاولیٰ چھتیں (۳۶ھ) میں پیش آیا، اس وقت ان کی عمر چھیاسٹھ(۶۶) یا سرسٹھ(۶۷) سال تھی۔ بنی تمیم کے ایک شخص نے انہیں شہید کیا جس کا نام عمرو بن جرموز تھا۔ اس نے وادی السباع میں دھوکے سے انہیں قتل کیا۔ یہ روایت خلیفہ بن خیاط کی ہے۔ یعقوب بن سفیان اپنی تاریخ میں بطریق حصین بواسطہ عمرو بن جاوان لکھتے ہیں: جب دونوں گروہ ایک دوسرے کے سامنے صف آراء ہوئے تو کعب بن سور کھڑے ہوئے ان کے ہاتھ قرآن شریف تھا وہ دونوں کو اللہ تعالیٰ اور اسلام کا واسطہ دینے لگے لیکن کسی شرارتی نے آگے بڑھ کر اس مصلحت کیش کا کام تمام کر دیا۔ اب دونوں جماعتیں گتھم گتھا ہوگئیں۔ سب سے پہلے طلحہ قتل ہوئے۔ سیدنا زبیر رضی اللہ عنہ اپنے گھوڑے کو ایڑ لگا کر نکل گئے احف کو معلوم ہوا تو وہ کہنے لگے جب انہوں نے مسلمانوں کے ساتھ مل کر حملہ کرنا تھا جب دیکھا کہ ایک دوسرے کی تلواریں پیشانیوں کو چیر رہی ہیں تو وہ اپنے بیٹے سے ملنا چاہتے ہیں۔ یہ بات عمرو بن جرموز نے سن لی وہ ان کے تعاقب میں چل پڑا، پیچھے سے پہنچ کر انہیں نیزہ گھونپا فضالہ بن حابس اور نفیع نے مزید مدد کی سب نے مل کر انہیں قتل کر دیا۔(11) متنبیہ: ہمارے سامنے جو نسخہ ہے اس میں نمبرنگ اور شمار میں تھوڑی غلطی ہے۔ اگلا نام بے نمبر ہے جو سابقہ ترتیب کے مطابق ۲۷۸۹ بنتا ہے جبکہ اس کے بعد والا ہونا تو ۲۷۹۰ چاہیے تھا لیکن ۲۷۹۲ لکھا ہے جس سے مغالطہ ہوتا ہے کہ شاید دو عنوان چھوڑ دیئے گئے، لیکن دار الفکر کا دوسرا نسخہ جو سات جلدوں پر مشتمل ہے اس میں نمبر شمار اور نام اسی ترتیب سے درست لکھے ہیں۔","",{"fn":"(1) اسد الغابہ (۱۷۳۲) استیعاب (۸۱۱)\n(2) بخاری کتاب العلم باب اثم من کذب علی النبی صلی اللہ علیہ وسلم (۱۰۶) مسند احمد (۱۴۲۸)\n(3) التاریخ الکبیر (۴۴۷/۱)\n(4) مستدرک للحاکم (۵۵۵۱، ۱۱۴۹)\n(5) الطبقات الکبری (۱/۲)\n(6) بخاری کتاب فضائل الصحابہ باب مناقب الزبیر بن العوام (۳۷۲۰) مسلم کتاب فضائل الصحابہ (۶۱۹۵) ابن ماجہ المقدمہ (۱۲۲)\n(7) بخاری کتاب المغازی باب قتل ابی جھل (۳۹۷۳)\n(8) مسلم کتاب فضائل الصحابہ باب من فضائل طلحہ والزبیر رضی اللہ عنہما (۶۱۹۹)\n(9) بخاری کتاب المغازی باب غزوۃ الخندق (۴۱۱۳)\n(10) مسلم کتاب فضائل الصحابہ (۶۱۹۳)\n(11) کنز العمال (۳۱۶۸۸)"}],[2785,"§۲۷۹۲ ۔ زبیر بن ابی ہالہ التمیمی(1)\nابن مندہ کی بحوالہ زبیر بن ابی ہالہ روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک قریشی کو قتل کروایا پھر فرمانے لگے: 'آج کے بعد کسی قریشی کو قید کر کے قتل نہیں کیا جائے گا۔' - اسی روایت کو ابن عدی نے(2) 'الکامل' میں مصعب بن سعید کے حالات میں نقل کیا ہے کہ وہ ثقات کے حوالہ سے منکر روایات نقل کرتے تھے اور اس حدیث کے آخر میں یہ الفاظ بڑھا دیئے ہیں 'سوائے عثمان رضی اللہ عنہ کے قاتل کے۔'(3) ابن ابی حاتم رحمہ اللہ لکھتے ہیں: ان کی حدیث سیف بن عمر کے طریق سے ذخیرہ احادیث میں شامل ہوئی ہے۔ میں کہتا ہوں: سیف نے فتوح میں وائل بن داؤد سے بواسطہ ابی اسحاق انہوں نے سیدنا زبیر رضی اللہ عنہ کے حوالہ سے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: 'اے اللہ! میری امت کے لیے میرے صحابہ میں برکت عطا فرما۔' (حدیث)(4) لیکن اکثر نسخوں میں 'زبیر بن عوام' لکھا ہے۔ فاللہ اعلم","",{"fn":"(1) اسد الغابہ (۱۷۳۳) تجرید (۱۸۹/۱)\n(2) مسند احمد (۱۵۴۰۹) المستدرک (۲۷۵/۴) تہذیب تاریخ دمشق (۶۳/۳)\n(3) الجرح والتعدیل (۵۷۹/۳)\n(4) تہذیب تاریخ دمشق (۱۳/۳)"}],[2786,"§۲۷۹۲ ۔ الزجاج\nعبدالرحمن کے والد۔ ام حبیبہ کے غلام۔ ان شاء اللہ تعالیٰ ان کا ذکر ان کے بیٹے کے حالات میں ہوگا۔"],[2787,"§۲۷۹۳ ۔ زغی (تصغیر ہے)\nابن مندہ اور ابو نعیم نے حرف زا میں ان کا تذکرہ کیا ہے، جبکہ ابن فنتون نے حرف راء میں ان کا ذکر کیا ہے۔ ہمارے ہاں ذویب بن معلم کے حالات میں ان کا ذکر ہو چکا ہے۔"],[2788,"§۲۷۹۴ ۔ زرارہ بن اوفی النخعی(1)\nابو عمرو(4)۔ ابن ابی حاتم(2) بحوالہ اپنے والد لکھتے ہیں: انہیں شرف صحابیت حاصل ہے۔ خلافت عثمانی میں وفات پائی۔(3) ابوعمرو نے بھی ان کا اتباع کر کے اتنا ہی لکھا ہے۔ میں کہتا ہوں: رہے زرارہ بن اوفی بصرہ کے قاضی تو وہ مشہور تابعی ہیں اور ثقہ ہیں وہ حرشی ہیں (شخصی نہیں) لہذا فرق واضح ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۳۷) استیعاب (۸۱۲)\n(2) الجرح والتعدیل (۶۰۳/۳)\n(3) استیعاب (۹۴۱۲)\n(4) اسد الغابہ (۱۷۳۸) استیعاب (۸۱۳)"}],[2789,"§۲۷۹۵ ۔ زرارہ بن جزئی(1)\nبن جزئی یا جزء بن عمرو بن عوف بن کعب بن ابی بکر بن کلاب کلابی۔ ابو یعلی اور حسن بن سفیان کی بطریق زفر ابن وثیمہ بحوالہ مغیرہ بن شعبہ روایت کی ہے کہ زرارہ بن نجومی نے سیدنا عمر بن خطاب رضی اللہ عنہ سے کہا کہ نبی صلی اللہ علیہ وسلم نے ضحاک بن سفیان کی طرف یہ تحریری حکمنامہ بھیجا کہ اشیم ضبابی کی بیوی کو اس کے خاوند کی دیت کا وارث بنائے۔(2) اس کی سند حسن ہے۔ اس کا ایک طریق اور بھی ہے جو شریک بن وائلہ کے سوانح میں ذکر ہوگا۔ جاحظ نے کتاب البیان میں لکھا ہے کہ زرارہ بن جزری جب سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس آئے اور آپ کے پاس گفتگو کی تو ان کی قدر و منزلت بڑھ گئی: 'میں ابو حفص کے پاس آیا جبکہ لوگوں میں سے کسی کی سکت نہیں وہ نیزہ کی طرح تیز ہے، مجھے رحمن نے توفیق دی جب ان سے میری ملاقات ہوئی، تو میں نے ان سے ایسی بات کہی جو ان کے دل کو لگی، اور دروازہ میں مد مقابلوں کے پیچھے چرچراہٹ تھی حالانکہ کہنے والوں کی کچھ باتیں دھوکہ پر مبنی ہوتی ہیں۔' ابن کلبی کا قول ہے کہ یہ مروان بن الحکم کی خلافت تک حیات رہے۔ زبیر بن بکار لکھتے ہیں مجھے میرے بھائی ہارون نے بحوالہ کسی دیہاتی بتایا کہ عبدالعزیز بن زرارہ صاحب شرافت اور مالدار آدمی تھے۔ عنبہ آئے تو اپنا مال انہیں پیش کیا، انہیں پسند آ گیا تو فرمانے لگے: اللہ! میں آپ کو گواہ بناتا ہوں کہ میں نے اپنے آپ کو اور اپنے اہل و مال کو آپ کی راہ میں روک رکھا ہے۔ پھر اپنے والد کے پاس آئے، انہیں اطلاع دی انہوں نے فرمایا: اللہ کی برکت سے روانہ ہو جاؤ چنانچہ شام کی جانب چل دیئے۔ امام واقدی کا بیان ہے کہ وہ یزید بن معاویہ رضی اللہ عنہ کے ساتھ قسطنطنیہ کے معرکہ میں شریک تھے۔ بقول بعض وہ اسی سفر میں فوت ہوئے تھے، تو امیر معاویہ رضی اللہ عنہ نے زرارہ کو ان کی فوتگی کی اطلاع دی۔ تو وہ بولے: عربی نوجوان فوت ہوا ہے۔ زرارہ بولے: میرا بیٹا یا آپ کا؟ انہوں نے فرمایا: تمہارا بیٹا۔ جس پر انہوں نے انا للہ پڑھا۔ ہشام بن کلبی کا قول ہے: مروان نے جب خلافت کی بیعت لی تو اس کا گزر زرارہ کے پاس سے ہوا اس وقت وہ اپنے پانی کے چشمہ پر تھے ان کی کافی عمر ہوگئی تھی۔ مروان نے پوچھا: آپ کیسے ہیں؟ فرمایا: خیریت سے ہوں۔ اللہ تعالیٰ نے ہمیں اچھی فصل دی جسے ہم سے اچھے طریق سے کٹوایا۔ ان کے سب لوگ جہاد میں شہید ہوئے تھے۔","",{"fn":"(1) اسد الغابہ (۱۷۳۸) استیعاب (۸۱۳)\n(2) ابوداؤد کتاب الفرائض باب فی المرأۃ ترث من دیۃ زوجہا، ترمذی کتاب الفرائض باب ماجاء فی میراث المرأۃ فی دیۃ زوجہا (۲۱۱۰) ابن ماجہ کتاب الدیات باب المیراث من الدیۃ (۲۶۴۲)"}],[2790,"§۲۷۹۶ ۔ زرارہ بن عمرو النخعی(1)\nابن ابی حاتم(2) بحوالہ اپنے والد نقل کرتے ہیں کہ یہ ۹ھ پندرہ محرم نبی علیہ السلام کے پاس آئے۔ ابوعمر(3) کا قول ہے: بلکہ ان کی آمد ۹ھ پندرہ رجب میں ہوئی تھی۔ جو قول ابن ابی حاتم نے ذکر کیا ہے اس پر ابن سعد(4) نے اعتماد کر کے لکھا ہے کہ محمد بن عمر اسلمی نے ہمیں بتایا کہ نبی علیہ السلام کے پاس آخری وفد جو آیا وہ نفع کا وفد تھا، یہ لوگ یمن سے ۹ھ پندرہ محرم کو آئے تھے۔ ان کی تعداد دوسو(۲۰۰) مرد تھی۔ انہوں نے معاذ بن جبل رضی اللہ عنہ سے بیعت کی تھی، ان میں زرارہ بن عمرو بھی تھے۔ ابوعمر(5) نے ان کی ایک حدیث ذکر کی ہے جس میں ہے کہ نبی صلی اللہ علیہ وسلم نے ان کے لیے دعا فرمائی کہ انہیں فتنہ کا زمانہ نہ دیکھنا پڑے، مذکورہ حدیث ابن شاہین نے بطریق ابوالحسن مدائنی بحوالہ اپنے شیوخ نقل کی ہے کہ نفع کا وفد حرم احد میں آیا۔ ان کے امیر زرارہ بن عمرو تھے یہ کل دوسو(۲۰۰) مرد تھے۔ زرارہ نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! میں نے راستہ میں ایک خوفناک خواب دیکھا ہے، میں نے خواب میں اپنی وہ گدھی دیکھی ہے جو اپنے گھر چھوڑ آیا ہوں۔ اس نے ایک بچہ جنا ہے جس کا سرخی مائل سیاہ اور سبزی مائل رنگ ہے۔ اور میں نے زمین سے نکلتی ایک آگ دیکھی جو میرے اور میرے بیٹے جس کا نام عمرو ہے حائل ہوگئی، وہ کہہ رہی تھی: لپٹ لپٹ بینا اور نا بینا۔ اور میں نے نعمان بن منذر کو دیکھا، اس نے دو بالیاں، دو بازو بند اور دو کنگن پہن رکھے ہیں اور میں نے کھچڑی بالوں والی ایک بڑھیا زمین سے نکلتی دیکھی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کیا تم پیچھے شب باشی والی حاملہ باندی چھوڑ آئے ہو؟ انہوں نے عرض کی: جی ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اس نے ایک لڑکا جنا ہے، جو تمہارا بیٹا ہے۔ عرض کی: اس کا رنگ سیاہ اور سرخی مائل کس وجہ سے ہے؟ آپ نے فرمایا: میرے نزدیک ہو جاؤ، چنانچہ وہ قریب ہوئے تو فرمایا: کیا تمہیں کہیں برص کا داغ ہے، جسے تم چھپاتے ہو؟ عرض کی: جی ہاں! اس ذات کی قسم! جس نے آپ کو حق دے کر بھیجا ہے، آپ سے پہلے کسی کو اس کا علم نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: بس وہ (رنگت) یہی ہے۔ رہی وہ آگ، تو اس سے مراد وہ فتنہ ہے جو میرے بعد ہوگا۔ عرض کی: فتنے کیا ہیں؟ آپ نے فرمایا: لوگ اپنے خلیفہ کو قتل کر دیں گے اور آپس میں لڑنے لگیں گے۔ پھر آپ صلی اللہ علیہ وسلم نے اپنی انگلیاں آپس میں ملا کر دکھائیں کہ اس طرح۔ ایسی حالت ہو جائے گی کہ مومن کا خون (کرنا) انہیں شہد سے شیریں معلوم ہوگا۔ برائی کرنے والا سمجھے گا میں نیکی کر رہا ہوں۔ اگر تم مر گئے تو تمہارے بیٹے کو ان فتنوں کا سامنا ہوگا۔ اور اگر تم زندہ رہے تو ان فتنوں کو دیکھو گے۔ عرض کی: آپ میرے لیے دعا فرما دیجئے کہ مجھے وہ فتنے نہ دیکھنے پڑیں۔ چنانچہ آپ نے ان کے لیے دعا فرما دی۔(6) فرماتے ہیں: ان کے بیٹے عمرو بن زرارہ پہلے انسان ہیں جنہوں نے سیدنا عثمان بن عفان رضی اللہ عنہ کو چھوڑ دیا۔ آپ علیہ السلام نے فرمایا: رہا نعمان تو وہ عرب بادشاہ تھا جسے مزید زیب و زینت ملے گی۔ اور کھچڑی بالوں والی بڑھیا باقیماندہ دنیا ہے۔ ابن شاہین نے بطریق ابن کلبی روایت کی کہ مجھ سے بزم کے ایک شخص نے بحوالہ ان کے کسی آدمی سے نقل کیا کہ نفع کا زرارہ بن قیس بن حارث بن عدی نامی شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا۔ پھر اسی طرح کا مفہوم ذکر کیا۔ اور حدیث میں یوں نقل کیا ہے کہ زرارہ تو فوت ہو گئے، اور ان کے بیٹے عمرو کو فتنہ نے آلیا۔ چنانچہ وہ کوفہ کے پہلے شخص ہیں جنہوں نے سیدنا عثمان رضی اللہ عنہ کی بیعت توڑ کر سیدنا علی رضی اللہ عنہ سے بیعت کر لی۔","",{"fn":"(1) اسد الغابہ (۱۷۳۹) استیعاب (۸۱۲) تجرید (۸۹/۱)\n(2) الجرح والتعدیل (۶۰۳/۳)\n(3) استیعاب (۹۴/۲)\n(4) الطبقات (۳۸۸/۵)\n(5) الاستیعاب (۹۵/۲)\n(6) الطبقات (۳۸۸/۵)"}],[2791,"§۲۷۹۷ ۔ زرارہ بن عمیر\nابو عزیز۔ مصعب بن عمیر رضی اللہ عنہ کے بھائی۔ کنیت سے ہی زیادہ مشہور ہیں، کنیتوں میں تذکرہ ہوگا۔"],[2792,"§۲۷۹۸ ۔ زرارہ بن قیس\nبن حارث بن عدی التھی۔ قریب ہی زرارہ بن عمرو میں تذکرہ ہو چکا ہے۔"],[2793,"§۲۷۹۹ ۔ زرارہ بن قیس(1)\nبن حارث بن فہر بن قیس بن ثعلبہ بن عبید بن ثعلبہ بن غنم بن مالک بن النجار الانصاری۔ ابن عبدالبر(2) نے ان کا ذکر کیا کہ جنگ یمامہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۷۴۲) استیعاب (۸۱۵)\n(2) استیعاب (۹۵/۲)"}],[2794,"§۲۸۰۰ ۔ زرارہ بن قیس(1)\nبن عمروہ تھی۔ میرے خیال میں یہ ان سے پہلے عنوان والے صاحب کے بھتیجے ہیں۔ ابن شاہین لکھتے ہیں: منذر بن محمد حسن بن محمد، یحیی بن زکریا بن ابراہیم بن سوید مخفی، حسن بن حکم، عبدالرحمن بن عابس شخصی وہ اپنے والد سے ان کے سلسلہ سند میں زرارہ بن قیس بن عمرو سے مروی ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو آپ نے ان کے لیے ایک تحریر لکھوائی اور دعا دی۔","",{"fn":"(1) اسد الغابہ (۱۷۴۱) استیعاب (۸۱۶) تجرید (۱۸۹/۱)"}],[2795,"§۲۸۰۱ ۔ زرارہ الانصاری(1)\nابن شاہین اور ابن مردویہ بطریق عمر ابی حفص، خالد بن سلمہ، سعید بن عمرو بن جعدہ المخزومی، وہ زرارہ انصاری کے بیٹے سے وہ اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک دن یہ آیات پڑھیں: 'یہ مجرم لوگ در حقیقت غلط فہمی میں ہیں اور ان کی عقل ماری گئی ہے، جس روز یہ چہروں کے بل گھسیٹے جائیں گے اس روز ان سے کہا جائے گا اب چکھو جہنم کی لپٹ کا مزا، ہم نے ہر چیز کو ایک تقدیر سے بنایا ہے۔'(2) پھر فرمایا: 'یہ آیت ان لوگوں کے بارے میں نازل ہوئی جو میری امت کے آخر میں ہوں گے اور تقدیر کو جھٹلائیں گے۔' اسی روایت کو ابن شاہین اور ابن مندہ ایک اور سند سے جو حفص بن سلیمان تک بحوالہ خالد بن سلمہ پہنچتی ہے۔ اسی اسناد سے نقل کی ہے، لیکن اس میں انصاری نہیں لکھا۔ اسی بنا پر ابن الاثیر کی سمجھ بیٹھے کہ یہ خفی ہیں۔ اور یہ بات صحیح ثابت ہو چکی ہے یہ اور ہیں۔ اسی طرح ابن مندہ اور ابن مردویہ نے بطریق حفص بن سلیمان سعید بن عمرو سے انہوں نے زیاد بن ابی زیاد انصاری سے وہ بحوالہ اپنے والد روایت کرتے ہیں، اس میں حفص بن سلیمان (جو ضعیف راوی ہے) کی طرف سے اضطراب ہے۔ ابن مندہ نے ان کے بیٹے عمرو سے ان کی کنیت ابو عمرو لکھی ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۴۰)\n(2) سورۃ القمر (۴۷)"}],[2796,"§۲۸۰۲ ۔ زر بن جابر\nبن سروس بن اسمع طائی نبھائی ابن کلبی کا بیان ہے کہ یہ زید الخیل کے ساتھ نبی علیہ السلام کے پاس آئے تھے۔ اس کی اسناد حارثہ بن قعین کے حالات میں گزر چکی ہے۔"],[2797,"§۲۸۰۳ ۔ زر بن عبداللہ(1)\nبن کلیب قیمی۔ بقول طبری انہیں شرف صحابیت اور آمد حاصل ہے۔ خورستان کی فتح میں لشکروں کے امیروں میں شامل تھے۔ جندیاپور کے محاصرہ میں لشکر کے کمانڈر تھے جسے صلح سے فتح کر لیا تھا ابن فنتون نے ان کا ذکر کیا ہے۔ ابن شاہین نے بطریق سیف بن عمر، ورقاء بن عبدالرحمن سے بحوالہ زر بن عبداللہ قیمی روایت کی ہے کہ یہ بنی تمیم کی ایک جماعت کے ساتھ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ اسلام قبول کیا نبی صلی اللہ علیہ وسلم نے ان کے لیے اور ان کی اولاد کے لیے دعا کی۔ پھر بطریق ابو معشر بحوالہ یزید بن رومان روایت کی ہے، فرمایا: رزین بن عبداللہ قیمی نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ابو موسیٰ لکھتے ہیں: بقول بعض: یہی درست ہے یعنی (زر کی بجائے) زرین۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۱۷۳۶)"}],[2798,"§۲۸۰۴ ۔ زرعہ بن خلیفہ الیمامی(1)\nابو حاتم(2) نے ان کا ذکر کیا ہے۔ بقول ابن السکن ان سے ایک مجہول سند سے ایک حدیث نقل کی جاتی ہے۔ پھر اسے بطریق ابو زرعہ رازی، موسیٰ بن حکم خراسانی، محمد بن زیاد رابسی بحوالہ زرعہ بن خلیفہ بیان کیا، فرمایا: میں نے یمامہ میں نبی صلی اللہ علیہ وسلم کو انہیں بلاتے سنا، پھر ہم آپ کے پاس آگئے آپ نے ہمیں اسلام کی پیشکش کی تو ہم لوگ اسلام لے آئے اور ہمارے لئے حصہ مقرر کیا اور عشاء کی نماز میں آپ نے یہ سورتیں تلاوت کیں۔ 'تین اور زیتون کی قسم! بے شک ہم نے یہ کلام لیلتہ القدر میں نازل کیا۔' ابن اسکن فرماتے ہیں: اگر ابوزرعہ نے ان سے مذکورہ حدیث روایت نہ کی ہوتی تو میں اس کا ذکر نہ کرتا۔ اس کی سند میں ان کے علاوہ اور ہمارے شیخ کے(3) علاوہ کوئی مشہور راوی نہیں۔ میں کہتا ہوں: شیرازی نے یہ روایت 'الالقاب' میں بطریق ابو حاتم رازی بحوالہ ابوزرعہ روایت کی ہے، پھر لکھا: خراسانی نے ایسا ہی کہا ہے۔ میں نے ایک اور مقام پر لکھا دیکھا ہے: موسیٰ بن حکم ابو عمران جرجانی، اسی طرح ابن السکن اور ابن مندہ نے بطریق محبوب بن مسعود بصری، ابو المعدل جرجانی روایت کی ہے، فرمایا: میں حج کے لیے نکلا، کسی نے مجھ سے کہا: یہاں ایک شخص رہتے ہیں جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ہے۔ ان کا نام زرعہ بن خلیفہ بتایا جاتا ہے، چنانچہ میں ان کے پاس آیا وہ اپنی قوم کے بے حد عمر رسیدہ بزرگ تھے۔ میں نے ان سے پوچھا: کیا آپ ہی نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ہے؟ وہ کہنے لگے: ہم لوگ اپنی قوم کی جماعت میں آپ کے پاس آئے۔ لیکن مدینہ میں آپ سے ہماری ملاقات نہ ہوسکی۔ آپ کسی غزوہ میں باہر گئے ہوئے تھے ہم لوگ واپس آگئے تو راستہ میں ہمارا آمنا سامنا ہو گیا، اتنے میں نماز فجر کا وقت ہو گیا۔ آپ صلی اللہ علیہ وسلم نے ہمیں نماز پڑھائی اور سورۃ قل ھو اللہ احد، اور قل یا ایھا الکافرون پڑھی۔ ابن مندہ فرماتے ہیں: یہ روایت غریب ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۴۴) استیعاب (۸۱۷)\n(2) الجرح والتعدیل (۶۰۵/۳)\n(3) جامع المسانید (۳۶۵/۴)"}],[2799,"§۲۸۰۵ ۔ زرعہ بن ضمرہ العامری(1)\nبقول ابن مندہ: ایک غلط حدیث میں ان کا ذکر آتا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۴۷)"}],[2800,"§۲۸۰۶ ۔ زرعہ بن عامر(1)\nبن مازن ابن ثعلبہ بن ہوازن بن اسلم اسلمی بقول ابن کلبی، انہیں بہت پرانا شرف صحابیت حاصل ہے۔ احد میں شرکت کی اور اسی میں شہادت سے سرفراز ہوئے۔ اور یہ پہلے مسلمان تھے جو احد میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۷۴۸)"}],[2801,"§۲۸۰۷ ۔ زرعہ الشقری\nان کا نام اصرم تھا۔ پھر نبی صلی اللہ علیہ وسلم نے ان کا نام زرعہ رکھا، حمزہ (الف) میں تذکرہ ہو چکا ہے۔"],[2802,"§۲۸۰۸ ۔ زرین\nزرین میں ذکر ہو چکا ہے۔"],[2803,"§۲۸۰۹ ۔ زعبہ بن ہشام الجہنی\nطبری کا بیان ہے کہ انہیں شرف صحابیت حاصل ہے۔"],[2804,"§۲۸۱۰ ۔ زفر بن حرثان(1)\nبن حارث بن حرثان بن زکوان بن کلفہ بن عوف بن نصر بن معاویہ انصری ثم اظفی۔ ابن کلبی کا قول ہے کہ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ یہی قول ابن سعد اور ابن جریر کا ہے۔ رشاطی لکھتے ہیں: ابو عمر اور ابن فنتون نے ان کا تذکرہ نہیں کیا۔","",{"fn":"(1) اسد الغابہ (۱۷۵۲)"}],[2805,"§۲۸۱۱ ۔ زفر بن زرعہ\nابو سعد نیشا پوری نے 'شرف المصطفی' میں ان کا ذکر کیا اور اپنی سند سے بحوالہ ان کے نقل کیا کہ انہوں نے جاہلیت میں حسب عادت ایک وادی میں جنات کے سردار کی پناہ اشعار میں بیان کی۔ تو انہوں نے جواب میں جنات کے اشعار سے جن سے نبی صلی اللہ علیہ وسلم کی بعثت کا پتا چلتا تھا۔ فرماتے ہیں: میں اپنے سفر سے واپس آیا تو نبی صلی اللہ علیہ وسلم کی بعثت کی خبر پھیل چکی تھی پھر ایک قصہ نقل کیا۔"],[2806,"§۲۸۱۲ ۔ زفر بن یزید(1)\nبن ہاشم بن کرملہ۔ بقول ابن مندہ: ایک حدیث میں ان کا ذکر آتا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۵۴)"}],[2807,"§۲۸۱۳ ۔ زکرہ بن عبداللہ (بے نسبت)(1)\nبلاذری نے صحابہ میں ان کا ذکر کیا ہے، انہوں نے اور علی العسکری نے بطریق بقیہ، عمرو بن عقبہ سے انہوں نے اپنے والد سے انہوں نے بحوالہ زیاد بن سمیہ ان کی حدیث نقل کی کہ میں نے ذکرہ کو فرماتے سنا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: 'اگر مجھے یحییٰ علیہ السلام کی قبر کا پتہ ہوتا تو میں اس کی زیارت کرتا۔'(2) ابو حاتم فرماتے ہیں: یہ زیاد وہ مشہور امیر نہیں جن کے بھائی ہونے کا دعویٰ امیر معاویہ رضی اللہ عنہ نے کیا تھا۔(3) ابن عبدالبر ہیں: اس کی سند قوی نہیں۔","",{"fn":"(1) اسد الغابہ (۱۷۵۶) استیعاب (۸۷۴) تجرید (۱۹۰/۱)\n(2) کنز العمال (۳۲۴۴۲) جامع المسانید (۳۷۰/۴) اسد الغابہ (۲۱۸/۲)\n(3) استیعاب (۱۳۲/۲)"}],[2808,"§۲۸۱۴ ۔ زلعب الجنّی\nشین کی ابتداء میں ان کا ذکر ہوگا۔"],[2809,"§۲۸۱۵ ۔ زمعہ بن ابی خلف الجمحی\nعمر بن شبہ نے مدینہ کو اپنا وطن اور وہاں اپنا گھر بنانے والوں میں ان کا ذکر کیا ہے۔ ان کے والد کو نبی صلی اللہ علیہ وسلم نے احد میں قتل کیا تھا۔ ان کے چچا زاد ربیعہ بن امیہ کا تذکرہ ہو چکا ہے۔"],[2810,"§۲۸۱۶ ۔ زمعہ بن اسود\nبن عامر القرشی۔ از بنی عامر بن لویٰ۔ ابو اسماعیل ازدی نے \"فتوح الشام\" میں ان کا ذکر کرتے ہوئے لکھا ہے۔ جن لوگوں کو سیدنا صدیق اکبر نے اجناد کا امیر بنا کر جھنڈا عطا کیا تھا ان میں زمعہ بن اسود بن عامر بھی تھے۔ آپ نے انہیں بلایا اور پرچم دے کر فرمایا: تم یزید بن ابی سفیان رضی اللہ عنہ کے ساتھ ہونا، اور پھر سیدنا یزید رضی اللہ عنہ کو حکم دیا کہ انہیں مقدمہ (پیش قدمی) کی ذمہ داری سونپیں اور فرمایا: یہ تمہاری قوم کا نیک شخص ہے۔ اور شہواروں میں شامل ہے۔ ہم بارہا ذکر کرتے آئے ہیں جو شخص شیخین (سیدنا صدیق و عمر رضی اللہ عنہما) کے دور میں مرد ہو گا اور ہوگا بھی قریش سے تو وہ صحابیت کی شرط پر پورا اترے گا۔ اس واسطے کہ حجتہ الوداع کے بعد ان میں سے کوئی بھی شرک پر قائم نہیں رہا، بلکہ مسلمان ہو کر سب نے حجتہ الوداع میں نبی صلی اللہ علیہ وسلم کے ساتھ شرکت کی ہے اور ہم یہ بھی ذکر کرتے آئے ہیں کہ فتوحات میں صرف صحابہ کرام رضی اللہ عنہم ہی امیر اور نگران بنائے جاتے تھے۔"],[2811,"§۲۸۱۷ ۔ زمل بن عمرو(1)\nبن عنز بن خشاف بن خدیج بن وائلہ بن حارثہ بن ہند بن حرام بن خثعمہ بن عبد بن کبیر بن عذرہ العذری۔ بقول بعض: زمل بن ربیعہ، انہیں زمیل (تصغیر سے) بھی کہا جاتا ہے۔ انہیں خدمت نبوی صلی اللہ علیہ وسلم آنے کی سعادت حاصل ہے۔ ہشام بن کلبی نے ان کا ذکر کیا ہے کہ ابن سعد نے طبقات میں ان کی روایت بواسطہ شرقی بن قطامی انہوں نے مدلج بن مقداد عذری سے وہ اپنے چچا عمارہ بن جزتی سے روایت کرتے ہیں۔ فرمایا، زمل نے فرمایا: مجھے بت سے ایک آواز سنائی دی(2)، میں آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، واقعہ عرض کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کسی مومن جن کی آواز تھی۔\" فرماتے ہیں۔ پھر وہ مسلمان ہو گئے اور اس موقعہ پر اشعار کہے:\nاللہ کے رسول! میں نے اس کی وضاحت آپ سے کر دی، میں سخت پتھر اور ریت کے مدور (گول) ٹیلوں سے اسے بناتا تھا۔\nاور ان کے اسلام لانے کی حکایت میں حدیث ذکر کی کہ وہ آئے اور آپ صلی اللہ علیہ وسلم نے انہیں ان کی قوم کی نگرانی کا پرچم باندھ کر دیا، ان کے لیے ایک تحریر لکھوائی۔ چنانچہ وہ بعد میں اپنی پرچم کے ساتھ امیر معاویہ رضی اللہ عنہ کا ساتھ دیتے ہوئے صفین میں شریک ہوئے۔ \"مرج راہط\" کی جنگ میں چونسٹھ (۶۴ھ) میں مروان کے ساتھ شرکت کرتے ہوئے شہید ہوئے۔ یہی روایت ابو سعد نیشاپوری نے \"شرف المصطفی\" میں بطریق ابو حاتم بجستانی، بواسطہ ابو عبیدہ بحوالہ شرقی درج کی ہے، لیکن انہوں نے کہا: مدلج عذری سے وہ اپنے والد سے وہ زمیل بن ربیعہ سے یہ روایت نقل کرتے ہیں۔ ان کی حدیث تمام نے اپنے فوائد میں ابو حارث سے بواسطہ محمد بن حارث بن ہانی، مدلج بن مقدام ابن زمل بن عمرو عذری وہ اپنے آباء و اجداد سے نقل کرتے ہیں اور یہ بھی ذکر کیا ہے کہ مذکورہ بت کا نام خثعم تھا۔ ابو عبیدہ کا قول ہے کہ امیر معاویہ رضی اللہ عنہ نے انہیں پولیس میں بھرتی کیا تھا، اور صفین میں حکم کے گواہوں میں سے تھے۔ امیر معاویہ نے انہیں باب توما کے پاس زمین کا ٹکڑا دیا۔ یزید بن معاویہ نے انہیں اپنی مہر لگانے کی ذمہ داری سونپی۔ جابیہ میں مروان کی بیعت میں شریک تھے۔ ابن سعد لکھتے ہیں: ان کے بیٹے مدلج بڑے شریف انسان تھے، انہوں نے خالد کی بہن امینہ بنت عبداللہ القسری سے نکاح کیا۔","",{"fn":"(1) اسد الغابہ (۱۷۵۸) استیعاب (۸۷۵) جامع المسانید (۳۷۱/۴)\n(2) اسد الغابہ (۲۱۸/۲) جامع المسانید (۳۷۲/۲)"}],[2812,"§۲۸۱۸ ۔ زنباع بن سلامہ(1)\nبقول بعض: ابن روح بن سلامہ بن حداد بن حدیدہ بن امید الجذامی روح کے والد۔ بقول ابن مندہ: اہل فلسطین میں شمار ہوتے ہیں۔ شرف صحابیت سے مشرف ہیں۔ ابوالحسین الرازی لکھتے ہیں: دمشق میں ان کی حویلی تھی جو \"درب العرمین\" کے پاس ہے۔ امام احمد رحمہ اللہ نے بطریق ابن جریج، عمرو بن شعیب سے انہوں نے اپنے والد کے واسطہ سے بحوالہ اپنے دادا روایت کی ہے کہ زنباع ابو روح نے اپنی لونڈی کے ساتھ غلام کو مشغول پایا تو غصہ میں آکر (اس کی ناک اور عضو کاٹ ڈالا، وہ غلام نبی صلی اللہ علیہ وسلم کے پاس (روتا ہوا) آیا، آپ صلی اللہ علیہ وسلم سے سارا ماجرا بیان کیا۔ آپ صلی اللہ علیہ وسلم نے زنباع سے فرمایا: تم نے ایسی سزا کس بنا پر دی؟ پھر اس کا ذکر کیا۔ اس کے بعد آپ صلی اللہ علیہ وسلم نے غلام سے فرمایا: جاؤ تم آزاد ہو۔ یہی روایت ابن مندہ نے بطریق مثنی بن صباح بواسطہ عمرو بن شعیب نقل کی ہے، اس میں غلام کا نام \"سندر\" بتایا ہے۔ اور بغوی نے بطریق عبداللہ بن سندر وہ اپنے والد سے روایت کرتے ہیں کہ وہ زنباع بن سلامہ جذامی کے پاس تھے، پھر وہ واقعہ ذکر کیا۔ ابن ماجہ(2) مذکورہ قصہ ایک ضعیف سند سے حدیث زنباع سے ہی روایت کرتے ہیں۔ زبیر بن بکار نے \"موفقیات\" میں بواسطہ مدائنی، ہشام بن کلبی سے بحوالہ اپنے والد روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ دور جاہلیت میں قریش کے چند لوگوں کے ساتھ تجارت کی غرض سے روانہ ہوئے جب یہ لوگ فلسطین پہنچے تو کسی نے ان سے کہا: زنباع بن روح بن سلامہ الجذامی اپنے ہاں سے گزرنے والوں سے حارث بن ابی شمر کے لیے ٹیکس وصول کرتا ہے۔ فرماتے ہیں: تو ہم نے اپنا سارا سونا ایک اونٹنی کو کھلا دیا کہ جب ہم اس سے گزر جائیں گے تو اسے ذبح کر کے سونا نکال لیں گے یوں ہمارا سونا بچ جائے گا۔ چنانچہ یہ تدبیر کر کے ہم لوگ زنباع کی حدود میں داخل ہو گئے۔ اس نے کہا: ان لوگوں کی تلاشی لو تو انہیں معمولی سا سونا ملا، وہ کہنے لگا: میرے سامنے ان کے اونٹ لاؤ، جب وہی اونٹنی اس کے سامنے آئی تو کہنے لگا: اس اونٹنی کو ذبح کرو۔ میں نے کہا: کس لیے؟ اس نے کہا: اگر اس کے پیٹ میں سونا ہوا تو بہتر ورنہ تمہیں اس کے بدلہ دوسری اونٹنی مل جائے گی اور اس کا گوشت تم ہی کھا لینا۔ فرماتے ہیں: انہوں نے اس کا پیٹ چاک کیا تو اس میں سے سونا بہنے لگا۔ یوں اس نے ہم سے بڑھا کر ٹیکس وصول کیا اور سیدنا عمر رضی اللہ عنہ سے خفا ہونے لگا۔ جس کے بارے میں سیدنا عمر رضی اللہ عنہ فرماتے ہیں:\n\"میری جب کبھی زنباع بن روح سے کسی شہر میں ملاقات ہو تو اس کا نصف میرا ہے۔ وہ ندامت کی وجہ سے دانت بجاتا ہے اور جانتا ہے کہ یہ ابن غالب کا قبیلہ ہے۔ ہجو میں فرمانبردار اور تہمت میں مد مقابل ہیں۔\"\nابن کلبی نے نسب بلوی میں یہ واقعہ نقل کیا ہے کہ زنباع بن روح اور حمزہ بن الصلیل بلوی کے درمیان جاہلیت میں مقابلہ ہوا۔ زنباع کھانا اور حمزہ دراہم لایا، جنہیں بکھیر دیا۔ لوگ بجائے کھانے کے دراہم کی طرف لپکے، جب زنباع نے یہ صورتحال دیکھی تو لا جواب ہو گئے۔ جس کے متعلق کسی شاعر نے کہا:\n\"تم تو ایسے لاجواب ہوئے کہ کچھ کہ نہیں پائے۔ کیا سعد اللہ بڑا ہے یا جذام، تجھے تم پر کوئی فضیلت نہیں ہم تو ایسی قوم نہیں کہ ہمارے سرداری اور اونچائی ہے (جیسے اونٹ کی گردن اور کوہان بلند ہوتا ہے)۔\"","",{"fn":"(1) اسد الغابہ (۱۷۶۹) استیعاب (۸۷۶) تجرید (۱۹۱/۱)\n(2) ابن ماجہ کتاب الدیات باب من مثل بعبده فھو حر (۲۶۸۰)"}],[2813,"§۲۸۱۹ ۔ زنگل (بے نسبت)\nوحدان میں ابو محمد بن حزم نے بقی بن مخلد کی مسند سے ان کا ذکر کیا ہے۔ تجرید میں ذہبی نے اپنے استدراک میں ان کا ذکر کیا ہے۔ مجھے خدشہ ہے کہ کسی مبہم مشخص کی \"لفظ رجل\" سے بگڑی ہوئی صورت ہے۔"],[2814,"§۲۸۲۰ ۔ زنیم (بے نسبت)\nبقول طبری: انہیں شرف صحابیت حاصل ہے۔ عبد بن حمید اپنی تفسیر میں یونس سے بواسطہ شیبان وہ قتادہ سے اس آیت کی تفسیر \"وہی ہے جس نے ان کے ہاتھوں کو تم سے باز رکھا۔\"(1) میں نقل کرتے ہیں کہ ایک صحابی ثنیہ الوداع پر چڑھے جن کا نام زنیم بتایا جاتا ہے۔ مشرکین نے انہیں شہید کر دیا۔ یہ حدیبیہ کا واقعہ ہے جس پر یہ آیت نازل ہوئی۔ یہی روایت طبری نے بطریق قتادہ نقل کی ہے۔ البتہ مسلم میں سلمہ بن اکوع کی حدیث سے مروی ہے کہ ابن زنیم شہید ہوئے تھے۔","",{"fn":"(1) سورۃ الفتح (۲۴)"}],[2815,"§۲۸۲۱ ۔ زنیم (دوسرے)\nیہ ان سے پہلے والے ہیں۔ ابن ابی شیبہ بطریق ابو جعفر باقر مرسل روایت نقل کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک چھوٹے قد والا شخص گزرا آپ نے سجدہ شکر ادا کیا اور فرمایا: \"تمام تعریفیں اللہ کے لیے جس نے مجھے زنیم جیسا (پست قد) نہیں بنایا۔\"(1) اور بطریق یحیی بن خراز مروی ہے کہ نبی صلی اللہ علیہ وسلم کے پاس سے ایک شخص گزرا جو کسی بیماری میں مبتلا تھا۔ آپ نے اس کا نام نہیں لیا۔ صرف سجدہ شکر ادا کیا۔ ابو علی بن اشعث نے بطریق جعفر بن محمد، بواسطہ اپنے والد بحوالہ سیدنا علی رضی اللہ عنہ موصولاً ذکر کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب مسجد میں داخل ہوئے تو وہاں زنیم نظر آیا اس شخص کا چہرہ بدنما قد ٹھگنا اور ہیئت بڑی عجیب تھی، آپ سجدہ میں گر گئے پھر اپنا سر اٹھایا اور فرمایا: \"تمام تعریفیں اللہ کے لیے جس نے مجھے زنیم جیسا نہیں بنایا۔\"","",{"fn":"(1) ابن ابی شیبہ کتاب الجہاد باب ماقالوا فی الفتح یاتی فیشربہ الوالی یسجد سجدۃ الشکر (۶۱۱/۷)"}],[2816,"§۲۸۲۲ ۔ زہرہ بن خویہ(1)\nبن عبد اللہ بن قتادہ اسیمی السعدی، سیف اور ابن کلبی کا بیان ہے کہ ہجر کے بادشاہ نے انہیں نبی صلی اللہ علیہ وسلم کے پاس بھیجا تو یہ مسلمان ہو گئے اور بعد میں جنگ قادسیہ میں سیدنا سعد کے ساتھ شریک ہوئے۔ انہوں نے ہی جالینوس کو قتل کیا اور حجاج کے دور تک زندہ رہے۔ شبیب خارجی سے جنگ میں سنتر (۷۷ھ) میں شہید ہوئے۔ حجاج نے انہیں عتاب بن ورقاء کے ساتھ بھیجا وہ انتہائی ضعیف العمر تھے، جہاں گھوڑوں نے انہیں روند دیا یہ اپنا دفاع کرنے لگے اتنے میں وہاں سے فضل بن عامر شیبانی کا گزر ہوا اور اس نے انہیں قتل کر دیا۔ شبیب آکر ان کے پاس کھڑا ہو کر کہنے لگا: اسے کس نے قتل کیا ہے؟ تو فضل نے کہا: میں نے، اس نے کہا: زہرہ تعجب کی بات ہے، اللہ کی قسم! تم کیسے گمراہی پر مارے گئے۔ مسلمانوں کے کئی معرکوں میں تمہاری اچھی کارکردگی تھی اور تم نے مشرکین کے کئی لشکروں کو شکست دی، اور ان کی کئی بستیاں تم نے فتح کیں۔ پھر طبری(2) نے بحوالہ ابو مخنف ان کا ذکر کیا۔ ابو عمر کا زعم ہے کہ وہ جنگ قادسیہ میں شہید ہوئے۔ رشاطی نے ان کا تعاقب کیا اور درست کیا۔","",{"fn":"(1) اسد الغابہ (۱۷۶۰) استیعاب (۸۷۷)\n(2) تاریخ الامم والمملوک (۲۶۵/۶)"}],[2817,"§۲۸۲۳ ۔ زہیر بن ابی امیہ(1)\nبن مغیرہ بن عبداللہ بن عمر بن مخزوم المخزومی۔ سیدہ ام المومنین ام سلمہ رضی اللہ عنہا کے بھائی۔ ہشام بن کلبی نے تالیف قلبی والوں میں ان کا ذکر کیا ہے۔ ابن مندہ کی روایت ہے کہ بطریق مجاہد سائب رسول اللہ صلی اللہ علیہ وسلم کے شریک سفر سے منقول ہے کہ عثمان اور زہیر بن ابی امیہ مجھے رسول اللہ صلی اللہ علیہ وسلم کے پاس لے گئے اور وہاں میری تعریفیں کرنے لگے۔ آپ نے فرمایا: \"میں تم دونوں سے زیادہ اسے جانتا ہوں۔\" (حدیث)(2) بقول ابن اسحاق یہ ان لوگوں میں سے ہیں جنہوں نے قریش کی بنی ہاشم کے خلاف لکھی تحریر کو ختم کرنے کی تجویز دی تھی، ان کے اور ہشام بن عمرو کے علاوہ کوئی مسلمان نہیں ہوا۔ ابن سعد کی کتاب میں ان کا نام قریش کے ان لوگوں میں لکھا ہے، جو رسول اللہ صلی اللہ علیہ وسلم کو رو برو اذیت پہنچاتے اور دشمنی کرتے تھے۔ یعقوب بن عقبہ سے مروی ہے کہ انہوں نے ان کا شمار کیا ہے کہ وہ بیس سے زیادہ مرد تھے۔ پھر فرمایا: ان میں سے سوائے ابو سفیان اور حکم بن ابی العاص کے کوئی مسلمان نہیں ہوا۔ میں کہتا ہوں: اس پر یہ اعتراض ہوتا ہے کہ یہ زہیر بن ابی امیہ بھی مسلمان ہوئے تھے۔ فاکہی نے بطریق ابن جریج بواسطہ ابن ابی ملیکہ بحوالہ علقمہ بن وقاص روایت کی ہے کہ ام سلمہ نے محمد بن عبد اللہ بن زہیر بن ابی امیہ کے حق میں یہ گواہی دی کہ ابو ربیعہ بن امیہ نے اپنے بھائی زہیر کو مکان میں سے اپنا حصہ دیا تھا۔ جس کی بنا پر امیر معاویہ رضی اللہ عنہ نے فیصلہ کیا اور علقمہ وہاں موجود تھے۔","",{"fn":"(1) اسد الغابہ (۱۷۶۲) استیعاب (۸۲۱) تجرید (۱۹۱/۱)\n(2) مسند احمد (۴۲۵/۳) المعجم الکبیر (۵۳۰۹/۵)"}],[2818,"§۲۸۲۴ ۔ زہیر بن ابی جبل\nقسم رابع میں تذکرہ ہوتا ہے۔"],[2819,"§۲۸۲۵ ۔ زہیر بن الحارث\nزہیر بن عوف میں تذکرہ ہوا ہے۔"],[2820,"§۲۸۲۶ ۔ زہیر بن حطامہ الکنانی\nان کے بھائی اسود بن خطامہ کے حالات میں ان کا تذکرہ ہوا ہے۔"],[2821,"§۲۸۲۷ ۔ زہیر بن صرد السعدی(1)\nالجشمی ابو صرد۔ بقول بعض ابو صرد۔ بقول ابن مندہ: شام میں رہتے تھے۔ مغازی میں ابن اسحاق(2) کا قول ہے کہ مجھے عمرو بن شعیب نے اپنے والد سے بحوالہ اپنے دادا بتایا کہ ھوازن کا وفد نبی صلی اللہ علیہ وسلم کے پاس آیا اور اسلام قبول کر لیا، پھر عرض کرنے لگے اللہ کے رسول! ہم (آپ کے) رشتہ دار اور خاندان والے ہیں ہمیں قحط کی جو مصیبت پہنچی ہے وہ آپ سے مخفی نہیں۔ اس لیے ہم پر احسان فرمائیے۔ اللہ تعالیٰ آپ کو اس کا بدلہ دے گا۔ فرماتے ہیں: ھوازن کا ایک شخص تھا جس کی کنیت ابو صرد تھی، وہ کہنے لگا: یا رسول اللہ! گھروں میں تو آپ کی پھوپھیاں، خالائیں اور آپ کو گود لینے والی خواتین ہیں جنہوں نے آپ کی پرورش کی۔ پھر وہ حدیث ذکر کی جس میں اشعار بھی ہیں۔ مجھے یہ حدیث لکھی ملی ہے(3) اس میں اکثر اشعار دسیوں اسناد والے ہیں۔ جنہیں میں نے عشرۃ العشاریہ میں ذکر کیا ہے اور \"الاربعین المتباینۃ\" میں دوسری سند سے املا کرایا ہے۔ ادھر ابن عبدالبر نے ایک بے عیب سبب سے اس روایت کو معلول کہا ہے جس کی وضاحت میں نے لسان المیزان میں کر دی ہے جو زیاد بن طارق کے حالات میں درج ہے۔ واللہ المستعان ابن سعد کی روایت ہے کہ غزوہ حنین میں جعرانہ کے مقام پر غنیموں کی تقسیم کے وقت ھوازن کے چار شخص مسلمان ہو کر آئے، اور اپنی قوم کے باقیماندہ لوگوں کے اسلام کی اطلاع بھی لائے۔ ان کا سردار اور متکلم ابو صرد زہیر بن صرد تھا، وہ کہنے لگا: اللہ کے رسول! ہم رشتہ دار اور خاندان والے ہیں۔ پھر اشعار کے سوا باقی روایت ذکر کی۔ اسی میں ہے: ان میں جو جتنا دور ہے وہ آپ کے زیادہ قریبی ہے ان عورتوں نے آپ کو گود لیا، اپنی چھاتیوں سے آپ کو دودھ پلایا اور آپ کو اپنی رانوں پر بٹھایا آپ تو سب سے بہتر پرورش پانے والے تھے۔","",{"fn":"(1) اسد الغابہ (۱۷۶۹) استیعاب (۸۲۳)\n(2) السیرۃ النبویہ (۱۰۴،۱۰۳/۴)\n(3) السنن الکبری (۳۳۶/۶) (۷۵/۹) دلائل النبوۃ (۱۷۵/۵)"}],[2822,"§۲۸۲۸ ۔ زہیر بن طہفہ الکندی\nابن مندہ نے بطریق ایاد بن لقیط بحوالہ زہیر بن طہفہ الکندی روایت کی ہے کہ اللہ کی قسم! میں اس وفد میں تھا جو رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اس میں ملیکہ کے دونوں بیٹے بھی تھے۔ (حدیث) ابن مندہ فرماتے ہیں: یہ روایت غریب ہے جو صدقہ ابی عمران کی حدیث سے مروی ہے، وہ کوفی ہیں، ان کی حدیث جمع کی جاتی ہے۔"],[2823,"§۲۸۲۹ ۔ زہیر بن عاصم(1)\nبن حصین بن مشمت۔ ان کے دادا کا ذکر ہو چکا ہے، بقول ابن مندہ: زہیر نبی صلی اللہ علیہ وسلم کے پاس آئے۔ حصین بن مشمت کی حدیث میں ان کا ذکر آتا ہے۔ شاید ان کا اشارہ اس حدیث کی طرف ہے جو حصین کے سوانح میں ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں مختلف چشمے جاگیر میں دیئے تھے۔ پھر وہ حدیث ذکر کی۔ اس کے آخر میں ہے، زہیر بن عصام بن حصین نے کہا:\n\"میرے شہر نرم نہ تھے ان میں قلم کے خط نے سانسیں چلا دیں جو نبی صلی اللہ علیہ وسلم کی طرف سے تھا جب آپ نے لوگوں کو عطا کیا تھا۔\"\nمیں کہتا ہوں: ان اشعار پر مشہور شاعر ابو خیلہ سعدی نے بنی امیہ کے دور حکومت کے آخر میں اعتراض کیا تھا۔ بہر کیف اس قصہ سے زہیر کے آنے کا پتہ نہیں چلتا۔ ہو سکتا ہے انہوں نے یہ اشعار بطور فخر کہے ہوں، اگر چہ وہ دور نہیں پایا۔","",{"fn":"(1) اسد الغابہ (۱۷۷۰)"}],[2824,"§۲۸۳۰ ۔ زہیر بن عبداللہ(1)\nبن جدعان۔ ابو ملیکہ تمیمی صدیق اکبر رضی اللہ عنہ کے خاندان سے تعلق رکھتے ہیں۔ بقول ابن شاہین انہیں شرف صحابیت حاصل ہے۔ صحیح بخاری میں بطریق ابن ابی ملیکہ بواسطہ ان کے دادا سیدنا ابو بکر رضی اللہ عنہ کے حوالہ سے ان کا ذکر آتا ہے۔ ابن عبدالبر لکھتے ہیں: ابن ابی ملیکہ کے دادا صحابی ہیں۔ اور ان کے والد عبد اللہ بن جدعان اسلام لانے سے پہلے فوت ہو گئے تو جب ان کا بیٹا اتنا عرصہ زندہ رہا کہ وہ صدیق اکبر رضی اللہ عنہ سے حدیث نقل کرتا ہے معلوم ہوا کہ وہ صحابی ہوئے اس لیے کہ نبی صلی اللہ علیہ وسلم کی وفات سے پہلے کوئی بھی روئے زمین پر قریشی کفر پر قائم نہیں تھا۔ عمر بن شبہ نے اخبار مدینہ میں عبد العزیز بن مطلب سے روایت کی ہے کہ مسعود بن عمرو القاری جو عبد اللہ بن جدعان کا حلیف تھا کی آل نے ابن جدعان کی وفات کے وقت کہا: ابو مساحق! آپ کا کوئی بیٹا نہیں اس لیے ہمیں ہمارا معاہدہ واپس کر دیں۔ انہوں نے ایسا ہی کیا بعد میں ان لوگوں نے نوفل بن اہیب بن عبد مناف بن زہرہ سے معاہدہ کر لیا۔ پھر ابن جدعان کے ہاں ان کی وفات کے بعد ابو ملیکہ پیدا ہوئے۔ جو ابو قیس بن عبد مناف بن زہرہ کی بیٹی سے تھے۔","",{"fn":"(1) اسد الغابہ (۱۷۷۲)"}],[2825,"§۲۸۳۱ ۔ زہیر بن عثمان الثقفی(1)\nبصرہ فروکش ہوئے۔ ابوداؤد اور نسائی کی کتاب(2) میں ولیمہ کے بارے میں ان کی ایک حدیث اسی سند سے مروی ہے جس میں کوئی حرج نہیں۔ ابن السکن لکھتے ہیں: یہ صحابہ میں مشہور تو نہیں البتہ عمرو بن علی نے صحابہ میں ان کا تذکرہ کیا ہے۔ امام بخاری(3) لکھتے ہیں: ان کی صحابیت مشہور نہیں اور نہ اس حدیث کی سند صحیح ہے۔ ابن ابی خیثمہ، ابو حاتم، ترمذی(4) اور ازدی وغیرہ نے ان کا صحابی ہونا ثابت کیا ہے۔ ازدی نے یہ اضافہ نقل کیا ہے کہ عبداللہ بن عثمان ثقفی ان سے روایت کرنے میں متفرد ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۷۳) استیعاب (۸۲۴) تجرید (۱۹۲/۱)\n(2) ابوداؤد کتاب الاطعمہ باب فی کم تستحب الولیمہ (۳۷۴۵)\n(3) التاریخ الکبیر (۴۲۵/۱)\n(4) الجرح والتعدیل (۵۸۶/۳)"}]])